def get_broker_runtime_readiness() -> Dict[str, Any]:
    exness_demo_path = str(os.getenv('EXNESS_DEMO_PATH', '') or '').strip().strip('"')
    exness_live_path = str(os.getenv('EXNESS_LIVE_PATH', '') or '').strip().strip('"')
    fxcm_helper_python = get_fxcm_forexconnect_python()
    fxcm_helper_script = get_fxcm_forexconnect_helper_script()
    log_file_path = os.path.abspath('multi_broker_backend.log')

    binance_api_key = str(os.getenv('BINANCE_API_KEY', '') or '').strip()
    binance_api_secret = str(os.getenv('BINANCE_API_SECRET', '') or '').strip()
    fxcm_login = str(os.getenv('FXCM_LOGIN', '') or '').strip()
    fxcm_password = str(os.getenv('FXCM_PASSWORD', '') or '').strip()
    exness_account = str(os.getenv('EXNESS_ACCOUNT', '') or '').strip()
    exness_password = str(os.getenv('EXNESS_PASSWORD', '') or '').strip()
    exness_server = str(os.getenv('EXNESS_SERVER', '') or '').strip()

    mt5_import_ok = False
    try:
        import MetaTrader5  # type: ignore # noqa: F401
        mt5_import_ok = True
    except Exception:
        mt5_import_ok = False

    forexconnect_helper_ready = bool(fxcm_helper_python and os.path.exists(fxcm_helper_python) and fxcm_helper_script and os.path.exists(fxcm_helper_script))

    active_bot_count = 0
    blocked_bot_count = 0
    bots_in_drawdown_cooldown = 0
    market_pause_bots = 0
    no_setup_bots = 0
    high_severity_blockers: List[str] = []
    blocker_samples: List[Dict[str, Any]] = []

    now = datetime.now()
    for bot_id, bot in list(active_bots.items()):
        if not isinstance(bot, dict):
            continue
        if not bool(bot.get('enabled', False)):
            continue

        active_bot_count += 1
        broker_name = canonicalize_broker_name(
            bot.get('brokerName') or bot.get('broker_type') or bot.get('broker') or ''
        )

        drawdown_pause_until_raw = bot.get('drawdownPauseUntil')
        drawdown_active = False
        if drawdown_pause_until_raw:
            try:
                drawdown_pause_until = datetime.fromisoformat(str(drawdown_pause_until_raw))
                drawdown_active = drawdown_pause_until > now
            except Exception:
                drawdown_active = False
        if drawdown_active:
            bots_in_drawdown_cooldown += 1

        last_no_trade_reason = str(bot.get('lastNoTradeReason') or '').strip()
        last_order_block_reason = str(bot.get('lastOrderBlockReason') or '').strip()
        last_pause_event = bot.get('lastPauseEvent') or {}
        pause_type = str((last_pause_event or {}).get('pause_type') or '').strip().upper()
        pause_reason = str((last_pause_event or {}).get('pause_reason') or '').strip()

        market_paused = pause_type in {'MARKET_CLOSED', 'NO_LIQUIDITY', 'SYMBOL_HALTED', 'TRADE_MODE_DISABLED'}
        if market_paused:
            market_pause_bots += 1

        has_no_setup_block = 'no qualifying setups' in last_no_trade_reason.lower()
        if has_no_setup_block:
            no_setup_bots += 1

        has_current_block = bool(drawdown_active or market_paused or last_order_block_reason or has_no_setup_block)
        if has_current_block:
            blocked_bot_count += 1

        if drawdown_active:
            high_severity_blockers.append(f"{bot_id}: drawdown cooldown active")
        if market_paused:
            high_severity_blockers.append(f"{bot_id}: market paused ({pause_type})")

        if len(blocker_samples) < 8 and has_current_block:
            blocker_samples.append({
                'botId': bot_id,
                'broker': broker_name,
                'drawdownCooldownActive': drawdown_active,
                'lastOrderBlockReason': last_order_block_reason,
                'lastNoTradeReason': last_no_trade_reason,
                'lastPauseType': pause_type,
                'lastPauseReason': pause_reason,
            })

    binance_worker_pool_ready = bool(binance_worker_pool_manager and binance_worker_pool_manager.enabled)
    if CONFIGURED_BINANCE_WORKER_COUNT > 0 and not binance_worker_pool_ready:
        high_severity_blockers.append(
            'Binance worker pool is configured but unavailable (falling back to local threads)'
        )

    go_live_ready = len(high_severity_blockers) == 0

    return {
        'goLive': {
            'ready': go_live_ready,
            'status': 'GO' if go_live_ready else 'NO_GO',
            'highSeverityBlockerCount': len(high_severity_blockers),
            'highSeverityBlockers': high_severity_blockers[:20],
            'activeBotCount': active_bot_count,
            'blockedBotCount': blocked_bot_count,
            'blockerSamples': blocker_samples,
        },
        'logging': {
            'log_level': logging.getLevelName(logger.getEffectiveLevel()),
            'log_file_path': log_file_path,
            'log_file_exists': os.path.exists(log_file_path),
        },
        'fxcm': {
            'login_configured': bool(fxcm_login and fxcm_password),
            'helper_python_path': fxcm_helper_python,
            'helper_python_exists': bool(fxcm_helper_python and os.path.exists(fxcm_helper_python)),
            'helper_script_path': fxcm_helper_script,
            'helper_script_exists': bool(fxcm_helper_script and os.path.exists(fxcm_helper_script)),
            'helper_ready': forexconnect_helper_ready,
        },
        'exness': {
            'credentials_configured': bool(exness_account and exness_password and exness_server),
            'mt5_import_available': mt5_import_ok,
            'demo_terminal_path': exness_demo_path,
            'demo_terminal_exists': bool(exness_demo_path and os.path.exists(exness_demo_path)),
            'live_terminal_path': exness_live_path,
            'live_terminal_exists': bool(exness_live_path and os.path.exists(exness_live_path)),
        },
        'binance': {
            'credentials_configured': bool(binance_api_key and binance_api_secret),
            'api_key_present': bool(binance_api_key),
            'api_secret_present': bool(binance_api_secret),
            'worker_pool_configured_count': CONFIGURED_BINANCE_WORKER_COUNT,
            'worker_pool_ready': binance_worker_pool_ready,
        },
        'runtime': {
            'activeBotCount': active_bot_count,
            'blockedBotCount': blocked_bot_count,
            'botsInDrawdownCooldown': bots_in_drawdown_cooldown,
            'botsWithMarketPauseSignals': market_pause_bots,
            'botsWithNoSetupSignals': no_setup_bots,
        },
    }


def ensure_forexconnect_sdk_available() -> bool:
    """Try to make the locally installed ForexConnect SDK importable on Windows."""
    global _forexconnect_bootstrap_attempted
    if _forexconnect_bootstrap_attempted:
        return importlib.util.find_spec('forexconnect') is not None

    _forexconnect_bootstrap_attempted = True

    if importlib.util.find_spec('forexconnect') is not None:
        return True

    candidate_roots = []
    for raw_path in [
        os.getenv('FOREXCONNECT_HOME', ''),
        os.getenv('FOREXCONNECT_SDK_PATH', ''),
        r'C:\Program Files\Candleworks\ForexConnectAPIx64',
        r'C:\Program Files\Candleworks\ForexConnectAPI',
        r'C:\ForexConnectAPI-master',
    ]:
        normalized = str(raw_path or '').strip().strip('"')
        if normalized and os.path.exists(normalized) and normalized not in candidate_roots:
            candidate_roots.append(normalized)

    def _add_path_once(path_value: str) -> None:
        if path_value and path_value not in sys.path:
            sys.path.insert(0, path_value)

    def _add_dll_dir(path_value: str) -> None:
        if not path_value or not os.path.isdir(path_value):
            return
        try:
            if hasattr(os, 'add_dll_directory'):
                os.add_dll_directory(path_value)
        except Exception:
            pass
        existing_path = os.environ.get('PATH', '')
        if path_value.lower() not in existing_path.lower():
            os.environ['PATH'] = path_value + os.pathsep + existing_path

    for root in candidate_roots:
        for dll_dir in [root, os.path.join(root, 'bin')]:
            if os.path.isdir(dll_dir):
                _add_dll_dir(dll_dir)

        search_roots = [root, os.path.join(root, 'bin')]
        for search_root in search_roots:
            if not os.path.isdir(search_root):
                continue
            for current_root, dirnames, filenames in os.walk(search_root):
                if 'forexconnect' in dirnames and os.path.isfile(os.path.join(current_root, 'forexconnect', '__init__.py')):
                    _add_path_once(current_root)
                    if importlib.util.find_spec('forexconnect') is not None:
                        logger.info(f"[FXCM] ForexConnect SDK discovered at {current_root}")
                        return True
                if 'fxcorepy.py' in filenames or any(name.startswith('fxcorepy') and name.endswith(('.pyd', '.so')) for name in filenames):
                    _add_path_once(current_root)
                    if importlib.util.find_spec('forexconnect') is not None:
                        logger.info(f"[FXCM] ForexConnect SDK discovered via fxcorepy at {current_root}")
                        return True

    return importlib.util.find_spec('forexconnect') is not None

