def _resolve_exness_server(account_number: Any = None, is_live: bool = False, server: str = None) -> str:
    provided_server = str(server or '').strip()
    invalid_mt5_aliases = {
        'rest-api',
        'rest_api',
        'metaapi',
        'meta-api',
        'socket',
        'socket-bridge',
        'socket_bridge',
    }
    if provided_server and provided_server.lower() not in invalid_mt5_aliases:
        provided_lower = provided_server.lower()
        demo_like = any(token in provided_lower for token in ['demo', 'trial'])
        live_like = any(token in provided_lower for token in ['live', 'real'])
        if is_live and demo_like:
            logger.warning(
                f"[DUAL MT5] Exness live credential received demo server '{provided_server}' for account {account_number}; resolving to live server instead"
            )
        elif (not is_live) and live_like:
            logger.warning(
                f"[DUAL MT5] Exness demo credential received live server '{provided_server}' for account {account_number}; resolving to demo server instead"
            )
        else:
            return provided_server

    normalized_account = _normalize_exness_account_number(account_number)
    mapped_server = EXNESS_ACCOUNT_SERVER_MAP.get(normalized_account, '').strip()
    if mapped_server:
        return mapped_server

    if is_live:
        return str(EXNESS_LIVE.get('server') or 'Exness-MT5Real27').strip()
    return str(EXNESS_DEMO.get('server') or 'Exness-MT5Trial9').strip()


def _normalize_exness_path_candidate(path: str) -> Optional[str]:
    candidate = str(path or '').strip().strip('"')
    if not candidate:
        return None
    candidate = os.path.expandvars(candidate)
    if candidate.lower().endswith('.exe'):
        return candidate
    trimmed_candidate = candidate.rstrip('\\/')
    terminal_candidate = os.path.join(trimmed_candidate, 'terminal64.exe')
    if os.path.isfile(terminal_candidate):
        return terminal_candidate
    return trimmed_candidate


def _resolve_exness_terminal_path(
    configured_path: str = None,
    is_live: Optional[bool] = None,
    server: str = None,
    account_number: Any = None,
) -> Optional[str]:
    normalized_account = _normalize_exness_account_number(account_number)
    resolved_server = _resolve_exness_server(account_number, bool(is_live), server)
    default_live_path = str(globals().get('EXNESS_LIVE_PATH') or os.getenv('EXNESS_LIVE_PATH', r'C:\MT5\Exness-Live')).strip()
    default_demo_path = str(globals().get('EXNESS_DEMO_PATH') or os.getenv('EXNESS_DEMO_PATH', r'C:\MT5\Exness-Demo')).strip()

    candidate_paths: List[str] = []
    if configured_path:
        candidate_paths.append(str(configured_path).strip())

    account_path = EXNESS_ACCOUNT_PATH_MAP.get(normalized_account, '').strip()
    if account_path:
        candidate_paths.insert(0, account_path)

    server_path = EXNESS_SERVER_PATH_MAP.get(resolved_server, '').strip()
    if server_path:
        candidate_paths.insert(0, server_path)

    if is_live is True and default_live_path:
        candidate_paths.append(default_live_path)
    elif is_live is False and default_demo_path:
        candidate_paths.append(default_demo_path)

    # Two-pass resolution: prefer any candidate that resolves to a real terminal
    # executable on disk (handles the nested terminal64.exe\terminal64.exe folder
    # layout used on the VPS). Only fall back to a non-existent path hint if none
    # of the candidates point at a file that actually exists, so a stale DB/env
    # path can never shadow a working terminal further down the list.
    # NOTE: resolution is inlined here (not via resolve_mt5_terminal_executable_path)
    # because this function runs at module import time, before that helper is defined.
    def _exness_candidate_executable(candidate: str) -> Optional[str]:
        if not candidate:
            return None
        if os.path.isfile(candidate):
            return candidate
        if os.path.isdir(candidate):
            for exe_name in ('terminal64.exe', 'terminal.exe'):
                direct = os.path.join(candidate, exe_name)
                if os.path.isfile(direct):
                    return direct
                # Some VPS installs unpack into a directory literally named
                # terminal64.exe/terminal.exe containing the real executable.
                if os.path.isdir(direct):
                    for nested_name in ('terminal64.exe', 'terminal.exe'):
                        nested = os.path.join(direct, nested_name)
                        if os.path.isfile(nested):
                            return nested
        return None

    fallback_candidate: Optional[str] = None
    for path in candidate_paths:
        normalized_candidate = _normalize_exness_path_candidate(path)
        if not normalized_candidate:
            continue
        resolved_candidate = _exness_candidate_executable(normalized_candidate)
        if resolved_candidate and os.path.isfile(resolved_candidate):
            return resolved_candidate
        if fallback_candidate is None:
            fallback_candidate = normalized_candidate

    return fallback_candidate


def _exness_live_slot_candidates() -> List[str]:
    candidates: List[str] = []
    pattern = str(EXNESS_LIVE_SLOT_PATTERN or '').strip()
    if not pattern:
        return candidates

    for slot in range(1, EXNESS_LIVE_SLOT_COUNT + 1):
        try:
            candidate = pattern.replace('{n}', str(slot)).replace('{slot}', str(slot))
            candidate = os.path.expandvars(candidate)
            normalized = _normalize_exness_path_candidate(candidate)
            if normalized:
                candidates.append(normalized)
        except Exception:
            continue
    return candidates


def _claim_exness_live_slot_path(
    user_id: str,
    account_number: Any,
    configured_path: Optional[str] = None,
    server: Optional[str] = None,
) -> Optional[str]:
    """Pick a non-occupied Exness LIVE terminal path and persist by credential path.

    Priority:
    1) explicit configured path
    2) account/server map overrides
    3) first unoccupied Live{n} slot path from EXNESS_LIVE_SLOT_PATTERN
    4) existing default Exness resolver fallback
    """
    explicit = _normalize_exness_path_candidate(configured_path or '')
    if explicit:
        return resolve_mt5_terminal_executable_path(explicit) or explicit

    normalized_account = _normalize_exness_account_number(account_number)
    # Keep an existing assignment stable for this exact user/account.
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            '''
            SELECT mt5_terminal_path
            FROM broker_credentials
            WHERE user_id = ?
              AND broker_name = 'Exness'
              AND account_number = ?
              AND is_live = 1
            ORDER BY COALESCE(updated_at, created_at, '') DESC
            LIMIT 1
            ''',
            (str(user_id or '').strip(), normalized_account),
        )
        existing_row = cursor.fetchone()
        conn.close()
        if existing_row:
            existing_path = existing_row[0] if isinstance(existing_row, (tuple, list)) else existing_row.get('mt5_terminal_path')
            normalized_existing = normalize_mt5_terminal_path_input(existing_path)
            if normalized_existing:
                return resolve_mt5_terminal_executable_path(normalized_existing) or normalized_existing
    except Exception as exc:
        logger.warning(f"Could not load existing Exness live slot assignment: {exc}")

    preferred = _resolve_exness_terminal_path(
        configured_path=None,
        is_live=True,
        server=server,
        account_number=account_number,
    )

    slot_candidates = _exness_live_slot_candidates()
    if not slot_candidates:
        return resolve_mt5_terminal_executable_path(preferred) or preferred

    occupied: Set[str] = set()
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute(
            '''
            SELECT mt5_terminal_path
            FROM broker_credentials
            WHERE broker_name = 'Exness'
              AND is_active = 1
              AND is_live = 1
              AND user_id != ?
            ''',
            (str(user_id or '').strip(),)
        )
        rows = cursor.fetchall()
        conn.close()
        for row in rows:
            value = row[0] if isinstance(row, (tuple, list)) else row.get('mt5_terminal_path')
            normalized = normalize_mt5_terminal_path_input(value)
            resolved = resolve_mt5_terminal_executable_path(normalized)
            final = os.path.normcase(os.path.normpath(resolved or normalized or ''))
            if final:
                occupied.add(final)
    except Exception as exc:
        logger.warning(f"Could not inspect occupied Exness live slots: {exc}")

    fallback_existing: Optional[str] = None
    for candidate in slot_candidates:
        resolved = resolve_mt5_terminal_executable_path(candidate)
        final_candidate = resolved or candidate
        final_key = os.path.normcase(os.path.normpath(final_candidate)) if final_candidate else ''
        if not final_key:
            continue
        # Prefer existing executable paths; allow non-existing as last fallback.
        if resolved and os.path.isfile(resolved) and final_key not in occupied:
            return resolved
        if fallback_existing is None and final_key not in occupied:
            fallback_existing = final_candidate

    if fallback_existing:
        return fallback_existing

    # All slots appear occupied; fall back to default live path behavior.
    return resolve_mt5_terminal_executable_path(preferred) or preferred


def get_exness_mt5_config(is_live: Optional[bool] = None, server: str = None, account_number: Any = None) -> Dict:
    """Return a fresh Exness MT5 config derived from the resolved environment mode."""
    target_is_live = ENVIRONMENT == 'LIVE' if is_live is None else bool(is_live)
    base_config = EXNESS_LIVE if target_is_live else EXNESS_DEMO
    config = dict(base_config)
    resolved_account = _normalize_exness_account_number(account_number or config.get('account'))
    config['server'] = _resolve_exness_server(resolved_account, target_is_live, server or config.get('server'))
    resolved_path = _resolve_exness_terminal_path(
        is_live=target_is_live,
        server=config['server'],
        account_number=resolved_account,
    )
    if resolved_path:
        config['path'] = resolved_path
    return config

