def get_referrer_id(user_id):
    """Get the referrer user_id for a given user (returns None if no referrer)"""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT referrer_id FROM users WHERE user_id = ?', (user_id,))
