def _get_default_signup_referrer_id(cursor) -> Optional[str]:
    try:
        cfg = _get_commission_config(cursor)
        developer_id = _get_developer_account_id(cfg)
        if not developer_id or developer_id == OWNER_USER_ID:
            return None
        cursor.execute('SELECT user_id FROM users WHERE user_id = ?', (developer_id,))
        row = cursor.fetchone()
        return row[0] if row and row[0] else None
    except Exception:
        return None


def _resolve_signup_referrer_id(cursor, referral_code: Optional[str] = None) -> Optional[str]:
    if referral_code:
        cursor.execute('SELECT user_id FROM users WHERE referral_code = ?', (referral_code.upper(),))
        referrer = cursor.fetchone()
        if referrer:
            return referrer['user_id'] if isinstance(referrer, sqlite3.Row) else referrer[0]
    return _get_default_signup_referrer_id(cursor)

class PaymentGateway:
    """Unified payment gateway for Stripe, bank transfers, crypto, and internal payments"""
    
    @staticmethod
    def process_payout(user_id: str, amount: float, reason: str, method: str = 'stripe') -> Dict:
        """
        Process a payout to a user via specified method
        
        Methods supported:
        - 'stripe': Stripe Connect (fastest, recurring payouts)
        - 'bank': Bank transfer (slower, verified method)
        - 'crypto': Cryptocurrency transfer (Bitcoin, Ethereum, USDT)
        - 'internal': Internal account credit (instant, no fees)
        """
        try:
            conn = get_db_connection()
            cursor = conn.cursor()
            
            # Get user payment method preference
            cursor.execute('SELECT payment_method, stripe_account_id, bank_account_id, crypto_wallet FROM users WHERE user_id = ?', (user_id,))
            user = cursor.fetchone()
            
            if not user:
                return {'success': False, 'error': 'User not found'}
            
            # Create transaction record
            transaction_id = str(uuid.uuid4())
            
            if method == 'stripe' or (method == 'auto' and user[1]):  # Stripe Connect
                result = PaymentGateway._process_stripe_payout(user_id, amount, reason, transaction_id)
                
            elif method == 'bank' or (method == 'auto' and user[2]):  # Bank transfer
                result = PaymentGateway._process_bank_payout(user_id, amount, reason, transaction_id)
                
            elif method == 'crypto' or (method == 'auto' and user[3]):  # Crypto transfer
                result = PaymentGateway._process_crypto_payout(user_id, amount, reason, transaction_id)
                
            elif method == 'internal':
                result = PaymentGateway._process_internal_payout(user_id, amount, reason, transaction_id)
            else:
                return {'success': False, 'error': f'Payment method {method} not configured for user'}
            
            # Log transaction
            if result['success']:
                cursor.execute('''
                    INSERT INTO transactions (transaction_id, user_id, type, amount, method, status, reason, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                ''', (transaction_id, user_id, 'payout', amount, method, 'completed', reason, datetime.now()))
                conn.commit()
                logger.info(f"✅ [PAYOUT] {amount:.2f} USD to {user_id} via {method}: {result.get('reference', 'N/A')}")
            else:
                cursor.execute('''
                    INSERT INTO transactions (transaction_id, user_id, type, amount, method, status, reason, created_at)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                ''', (transaction_id, user_id, 'payout', amount, method, 'failed', reason, datetime.now()))
                conn.commit()
                logger.error(f"❌ [PAYOUT FAILED] {amount:.2f} USD to {user_id}: {result.get('error')}")
            
            conn.close()
            return result
            
        except Exception as e:
            logger.error(f"Error processing payout: {e}")
            return {'success': False, 'error': str(e)}
    
    @staticmethod
    def _process_stripe_payout(user_id: str, amount: float, reason: str, transaction_id: str) -> Dict:
        """Process payout via Stripe Connect"""
        try:
            stripe = get_stripe_module()
            stripe.api_key = os.getenv('STRIPE_SECRET_KEY')
            
            conn = get_db_connection()
            cursor = conn.cursor()
            cursor.execute('SELECT stripe_account_id FROM users WHERE user_id = ?', (user_id,))
            result = cursor.fetchone()
            conn.close()
            
            if not result or not result[0]:
                return {'success': False, 'error': 'Stripe account not connected'}
            
            stripe_account_id = result[0]
            
            # Create payout
            payout = stripe.Payout.create(
                amount=int(amount * 100),  # Convert to cents
                currency='usd',
                description=reason,
                statement_descriptor=f"Zwesta-{transaction_id[:8]}",
                stripe_account=stripe_account_id
            )
            
            return {
                'success': True,
                'reference': payout.id,
                'status': payout.status,
                'amount': amount,
                'method': 'stripe'
            }
        except Exception as e:
            logger.error(f"Stripe payout error: {e}")
            return {'success': False, 'error': str(e)}
    
    @staticmethod
    def _process_bank_payout(user_id: str, amount: float, reason: str, transaction_id: str) -> Dict:
        """Process bank transfer payout"""
        try:
            conn = get_db_connection()
            cursor = conn.cursor()
            
            # Get bank details
            cursor.execute('''
                SELECT bank_name, account_holder, account_number, routing_number, swift_code
                FROM users WHERE user_id = ?
            ''', (user_id,))
            
            bank_info = cursor.fetchone()
            conn.close()
            
            if not bank_info or not bank_info[2]:  # No account number
                return {'success': False, 'error': 'Bank account not configured'}
            
            # Create bank transfer (ACH in US, SEPA in EU, etc.)
            # This would integrate with your banking API (e.g., Wise, Stripe ACH, etc.)
            
            logger.info(f"📧 Bank transfer scheduled: {amount:.2f} to {bank_info[1]} ({bank_info[0]})")
            
            return {
                'success': True,
                'reference': transaction_id,
                'status': 'pending',
                'amount': amount,
                'method': 'bank',
                'estimatedDays': 1-3,
                'bankName': bank_info[0],
                'accountHolder': bank_info[1]
            }
        except Exception as e:
            logger.error(f"Bank payout error: {e}")
            return {'success': False, 'error': str(e)}
    
    @staticmethod
    def _process_crypto_payout(user_id: str, amount: float, reason: str, transaction_id: str) -> Dict:
        """Process cryptocurrency payout (Bitcoin, Ethereum, USDT)"""
        try:
            conn = get_db_connection()
            cursor = conn.cursor()
            
            # Get crypto wallet
            cursor.execute('SELECT crypto_wallet, crypto_type FROM users WHERE user_id = ?', (user_id,))
            result = cursor.fetchone()
            conn.close()
            
            if not result or not result[0]:
                return {'success': False, 'error': 'Crypto wallet not configured'}
            
            wallet = result[0]
            crypto_type = result[1] or 'USDT'  # Default to USDT stablecoin
            
            # This would integrate with your crypto API (Coinbase, Kraken API, etc.)
            # For now, log the transaction
            
            logger.info(f"🪙 Crypto transfer scheduled: {amount:.2f} USD worth of {crypto_type} to {wallet[:10]}...")
            
            return {
                'success': True,
                'reference': transaction_id,
                'status': 'pending',
                'amount': amount,
                'method': 'crypto',
                'cryptoType': crypto_type,
                'wallet': f"{wallet[:6]}...{wallet[-4:]}",
                'estimatedMinutes': 5  # Blockchain confirmation time
            }
        except Exception as e:
            logger.error(f"Crypto payout error: {e}")
            return {'success': False, 'error': str(e)}
    
    @staticmethod
    def _process_internal_payout(user_id: str, amount: float, reason: str, transaction_id: str) -> Dict:
        """Process internal account credit (instant)"""
        try:
            conn = get_db_connection()
            cursor = conn.cursor()
            
            # Add to user's internal balance
            cursor.execute('''
                UPDATE users SET internal_balance = internal_balance + ? WHERE user_id = ?
            ''', (amount, user_id))
            conn.commit()
            conn.close()
            
            logger.info(f"💳 Internal credit: +{amount:.2f} to {user_id}")
            
            return {
                'success': True,
                'reference': transaction_id,
                'status': 'completed',
                'amount': amount,
                'method': 'internal',
                'instant': True
            }
        except Exception as e:
            logger.error(f"Internal payout error: {e}")
            return {'success': False, 'error': str(e)}


def pay_user(user_id: str, amount: float, reason: str, method: str = 'auto') -> bool:
    """
    Pay a user via their preferred payment method
    
    Args:
        user_id: User to pay
        amount: Amount in USD
        reason: Reason for payment (commission, profit, etc.)
        method: Payment method ('auto' = user preference, 'stripe', 'bank', 'crypto', 'internal')
    
    Returns:
        True if payment initiated successfully, False otherwise
    """
    if amount <= 0:
        logger.warning(f"Invalid payout amount: {amount}")
        return False
    
    result = PaymentGateway.process_payout(user_id, amount, reason, method)
    return result.get('success', False)

def distribute_profit_split_and_commissions(user_id, profit, bot_id):
    """Settle a trader withdrawal internally after per-trade commissions are already booked."""
    if profit <= 0:
        return {'owner': 0.0, 'referrer': 0.0, 'trader': 0.0, 'settledInternally': False}

    trader_share = float(profit)
    payout_success = pay_user(
        user_id,
        trader_share,
        f"Trader profit withdrawal from bot {bot_id}",
        method='internal',
    )
    logger.info(
        f"[PROFIT WITHDRAWAL] Bot {bot_id}: credited {trader_share:.2f} internally to trader {user_id} "
        f"(platform commissions are booked separately per profitable trade)"
    )
    return {
        'owner': 0.0,
        'referrer': 0.0,
        'trader': trader_share,
        'settledInternally': payout_success,
    }


_public_crypto_market_data_cache: Dict[str, Dict[str, Any]] = {}
_PUBLIC_CRYPTO_MARKET_DATA_TTL_SECONDS = 15


def _fetch_public_crypto_market_data(symbol: str) -> Optional[Dict[str, Any]]:
    normalized_symbol = str(_resolve_analysis_symbol(symbol) or symbol or '').strip().upper()
    if normalized_symbol.endswith('M'):
        normalized_symbol = normalized_symbol[:-1]
    if not normalized_symbol.endswith('USDT'):
        return None

    now = time.monotonic()
    cached_entry = _public_crypto_market_data_cache.get(normalized_symbol)
    if cached_entry and (now - float(cached_entry.get('ts') or 0.0)) < _PUBLIC_CRYPTO_MARKET_DATA_TTL_SECONDS:
        cached_data = cached_entry.get('data')
        if isinstance(cached_data, dict):
            return dict(cached_data)

    try:
        import requests

        response = requests.get(
            'https://api.binance.com/api/v3/klines',
            params={'symbol': normalized_symbol, 'interval': '1m', 'limit': 50},
            timeout=5,
        )
        if response.status_code != 200:
            return None

        payload = response.json()
        if not isinstance(payload, list) or not payload:
            return None

        close_prices = []
        for candle in payload:
            if isinstance(candle, list) and len(candle) > 4:
                try:
                    close_prices.append(float(candle[4]))
                except (TypeError, ValueError):
                    continue

        if not close_prices:
            return None

        current_price = float(close_prices[-1])
        high_price = max(close_prices)
        low_price = min(close_prices)
        volatility_pct = abs(high_price - low_price) / current_price * 100 if current_price > 0 else 1.0
        market_data = {
            'current_price': current_price,
            'price': current_price,
            'volatility_pct': max(volatility_pct, 0.1),
            'price_history': close_prices[-50:],
            'analysis_symbol': normalized_symbol,
            'data_source': 'binance_public_klines',
        }
        _public_crypto_market_data_cache[normalized_symbol] = {'ts': now, 'data': market_data}
        return dict(market_data)
    except Exception as exc:
        logger.debug(f'Public crypto market data fetch failed for {normalized_symbol}: {exc}')

    return None


def _get_market_data_for_symbol(symbol: str) -> Dict[str, Any]:
    resolved_symbol = _resolve_analysis_symbol(symbol)
    candidate_symbols = []
    for candidate in (symbol, resolved_symbol):
        normalized_candidate = str(candidate or '').strip()
        if normalized_candidate and normalized_candidate not in candidate_symbols:
            candidate_symbols.append(normalized_candidate)
        if normalized_candidate.endswith('m') and normalized_candidate[:-1] not in candidate_symbols:
            candidate_symbols.append(normalized_candidate[:-1])

    for candidate in candidate_symbols:
        if candidate in commodity_market_data:
            return commodity_market_data[candidate]

    # Fetch public crypto data once per 30 seconds per symbol
    public_crypto_market_data = _fetch_public_crypto_market_data(symbol)
    if public_crypto_market_data:
        return public_crypto_market_data

    return {'current_price': 0, 'volatility_pct': 1.0, 'price_history': [0]}


def _enrich_market_data_with_bot_context(
    bot_config: Optional[Dict[str, Any]],
    symbol: str,
    market_data: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    base_market_data = dict(market_data or _get_market_data_for_symbol(symbol))
    if not bot_config:
        return base_market_data

    broker_name = canonicalize_broker_name(
        bot_config.get('brokerName') or bot_config.get('broker_type') or bot_config.get('broker') or ''
    )
    if broker_name == 'Binance':
        public_crypto_market_data = _fetch_public_crypto_market_data(symbol)
        if public_crypto_market_data:
            base_market_data.update(public_crypto_market_data)

    adaptive_offset = int(bot_config.get('adaptiveSignalThresholdOffset') or 0)
    adaptive_miss_count = int(bot_config.get('adaptiveSignalMissCount') or 0)
    adaptive_reduction = min(adaptive_offset, ADAPTIVE_STRATEGY_MIN_SIGNAL_REDUCTION_MAX)
    if bot_config.get('managementState') == 'recovery':
        adaptive_reduction = 0

    base_market_data['adaptive_signal_threshold_offset'] = adaptive_offset
    base_market_data['adaptive_signal_miss_count'] = adaptive_miss_count
    base_market_data['adaptive_min_signal_reduction'] = adaptive_reduction
    # Propagate the bot's effective signal threshold so the per-symbol strategy floor
    # (min_signal_strength in SYMBOL_PARAMETERS, default 65) is clamped to the bot's
    # actual operating threshold rather than the hardcoded symbol default.
    # This ensures a Binance bot with effective threshold ~12 can trade signals like 43
    # that would otherwise be silently rejected by the strategy's internal floor.
    try:
        _effective_thr = int(
            bot_config.get('effectiveSignalThreshold')
            or bot_config.get('signalThreshold')
            or 0
        )
        if _effective_thr > 0:
            base_market_data['bot_signal_threshold_override'] = _effective_thr
        elif str(bot_config.get('signalThresholdMode') or '').strip().lower() == 'manual':
            _manual_thr = int(bot_config.get('signalThreshold') or 0)
            if _manual_thr > 0:
                base_market_data['bot_signal_threshold_override'] = _manual_thr
    except (TypeError, ValueError):
        pass
    return base_market_data


def _strategy_cache_key(strategy_func, symbol: str) -> str:
    return f"{getattr(strategy_func, '__name__', 'strategy')}::{symbol}"


def _average_absolute_price_move(prices: List[float], period: int = 14) -> float:
    cleaned_prices = [
        _safe_float(price, 0.0)
        for price in list(prices or [])
        if _safe_float(price, 0.0) > 0
    ]
    if len(cleaned_prices) < 2:
        return 0.0

    deltas = [
        abs(cleaned_prices[index] - cleaned_prices[index - 1])
        for index in range(1, len(cleaned_prices))
    ]
    if not deltas:
        return 0.0

    window = deltas[-max(1, min(int(period or 14), len(deltas))):]
    return sum(window) / len(window)


def _estimate_forex_pip_size(symbol: str) -> float:
    symbol_base = _normalize_symbol_base(symbol)
    if not _is_exness_forex_symbol(symbol_base):
        return 0.0
    return 0.01 if symbol_base.endswith('JPY') else 0.0001


def _build_dynamic_trade_plan(
    symbol: str,
    market_data: Optional[Dict[str, Any]],
    direction: Optional[str],
    signal_strength: float,
) -> Dict[str, Any]:
    params = _get_effective_symbol_params(symbol, market_data)
    base_sl = max(_safe_float(params.get('stop_loss_pips'), 0.0), 1.0)
    base_tp = max(_safe_float(params.get('take_profit_pips'), 0.0), base_sl)
    pair_sl_multiplier = max(_safe_float(params.get('sl_multiplier'), 0.0), 0.0)
    pair_tp1_multiplier = max(_safe_float(params.get('tp1_multiplier'), 0.0), 0.0)
    pair_tp2_multiplier = max(_safe_float(params.get('tp2_multiplier'), 0.0), 0.0)
    pair_trailing_enabled = bool(params.get('trailing_stop_enabled')) if 'trailing_stop_enabled' in params else True
    default_tp_levels = [
        {'rr': 1.0, 'closePct': 50},
        {'rr': 2.5, 'closePct': 30},
        {'rr': 4.0, 'closePct': 20},
    ]
    if pair_sl_multiplier > 0 and pair_tp1_multiplier > 0 and pair_tp2_multiplier > 0:
        default_tp_levels = [
            {'rr': round(max(pair_tp1_multiplier / pair_sl_multiplier, 0.1), 2), 'closePct': 50},
            {'rr': round(max(pair_tp2_multiplier / pair_sl_multiplier, 0.1), 2), 'closePct': 50},
        ]

    plan = {
        'slPips': round(base_sl, 2),
        'tpPips': round(base_tp, 2),
        'rr': round(base_tp / base_sl, 2) if base_sl > 0 else 0.0,
        'cleanPath': True,
        'trailingStopPips': round(max(base_sl * 0.9, 1.0), 2) if pair_trailing_enabled else 0.0,
        'tpLevels': default_tp_levels,
        'usedAtrPlan': False,
    }

    if direction not in {'BUY', 'SELL'}:
        return plan

    current_price = _safe_float((market_data or {}).get('current_price', (market_data or {}).get('price', 0.0)), 0.0)
    pip_size = _estimate_forex_pip_size(symbol)
    price_history = [
        _safe_float(price, 0.0)
        for price in ((market_data or {}).get('price_history') or [])
        if _safe_float(price, 0.0) > 0
    ]

    if current_price <= 0 or pip_size <= 0 or len(price_history) < 20:
        return plan

    closes = price_history[-50:]
    highs = [
        _safe_float(price, 0.0)
        for price in ((market_data or {}).get('high_history') or (market_data or {}).get('highs') or [])
        if _safe_float(price, 0.0) > 0
    ][-len(closes):]
    lows = [
        _safe_float(price, 0.0)
        for price in ((market_data or {}).get('low_history') or (market_data or {}).get('lows') or [])
        if _safe_float(price, 0.0) > 0
    ][-len(closes):]

    if len(highs) == len(closes) and len(lows) == len(closes) and len(closes) >= 15:
        atr_price = calculate_atr(highs, lows, closes, period=14)
    else:
        atr_price = _average_absolute_price_move(closes, period=14)

    atr_pips = max(atr_price / pip_size, base_sl * 0.5, 1.0)
    swing_window = closes[-20:]
    if direction == 'BUY':
        swing_distance_pips = max(0.0, (current_price - min(swing_window)) / pip_size)
    else:
        swing_distance_pips = max(0.0, (max(swing_window) - current_price) / pip_size)

    min_sl = max(4.0, base_sl * 0.85, atr_pips * 1.0)
    max_sl = max(min_sl, base_sl * 2.5, atr_pips * 3.0)
    raw_sl = max(base_sl * 0.9, atr_pips * 1.5, swing_distance_pips)
    sl_pips = round(min(max(raw_sl, min_sl), max_sl), 2)

    rr_target = 2.8 if signal_strength >= 85 else (2.5 if signal_strength >= 70 else 2.0)
    tp_pips = round(max(base_tp * 0.9, sl_pips * rr_target), 2)

    recent_high = max(swing_window)
    recent_low = min(swing_window)
    obstacle_room_pips = 0.0
    if direction == 'BUY' and recent_high > current_price:
        obstacle_room_pips = (recent_high - current_price) / pip_size
    elif direction == 'SELL' and current_price > recent_low:
        obstacle_room_pips = (current_price - recent_low) / pip_size

    if pair_sl_multiplier > 0 and pair_tp1_multiplier > 0 and pair_tp2_multiplier > 0:
        min_sl = max(4.0, base_sl * 0.85, atr_pips * max(pair_sl_multiplier * 0.6, 0.75))
        max_sl = max(min_sl, base_sl * 3.0, atr_pips * max(pair_sl_multiplier * 1.35, pair_sl_multiplier + 0.8))
        structural_sl = swing_distance_pips * 1.02 if swing_distance_pips > 0 else 0.0
        raw_sl = max(base_sl * 0.85, atr_pips * pair_sl_multiplier, structural_sl)
        sl_pips = round(min(max(raw_sl, min_sl), max_sl), 2)
        tp1_pips = round(max(atr_pips * pair_tp1_multiplier, sl_pips * 0.6), 2)
        tp2_pips = round(max(atr_pips * pair_tp2_multiplier, tp1_pips, sl_pips * 1.0), 2)
        tp_levels = [
            {'rr': round(max(tp1_pips / sl_pips, 0.1), 2), 'closePct': 50},
            {'rr': round(max(tp2_pips / sl_pips, 0.1), 2), 'closePct': 50},
        ]
        trailing_stop_pips = 0.0
        if pair_trailing_enabled:
            trailing_stop_pips = round(max(atr_pips * max(pair_sl_multiplier * 0.9, 1.0), sl_pips * 0.85), 2)

        plan.update({
            'slPips': sl_pips,
            'tpPips': tp2_pips,
            'rr': round(tp2_pips / sl_pips, 2) if sl_pips > 0 else 0.0,
            'cleanPath': obstacle_room_pips <= 0 or obstacle_room_pips >= min(tp1_pips, max(sl_pips * 0.8, atr_pips * 0.8)),
            'trailingStopPips': trailing_stop_pips,
            'tpLevels': tp_levels,
            'usedAtrPlan': True,
        })
        return plan

    tp_levels = [
        {'rr': 1.0, 'closePct': 50},
        {'rr': 2.5, 'closePct': 30},
        {'rr': 4.0, 'closePct': 20},
    ]
    if signal_strength >= 90:
        tp_levels[1]['closePct'] = 20
        tp_levels[2]['closePct'] = 30
    elif signal_strength < 75:
        tp_levels[0]['closePct'] = 70
        tp_levels[1]['closePct'] = 30
        tp_levels[2]['closePct'] = 0

    plan.update({
        'slPips': sl_pips,
        'tpPips': tp_pips,
        'rr': round(tp_pips / sl_pips, 2) if sl_pips > 0 else 0.0,
        'cleanPath': obstacle_room_pips <= 0 or obstacle_room_pips >= max(sl_pips * 0.8, atr_pips),
        'trailingStopPips': round(max(atr_pips * 2.0, sl_pips * 0.9), 2),
        'tpLevels': tp_levels,
        'usedAtrPlan': True,
    })
    return plan


def _score_signal_setup(
    symbol: str,
    market_data: Optional[Dict[str, Any]],
    signal_eval: Optional[Dict[str, Any]],
    bot_config: Optional[Dict[str, Any]] = None,
    strategy_name: str = '',
) -> Dict[str, Any]:
    signal_payload = dict(signal_eval or {})
    direction = extract_signal_direction(signal_payload.get('signal'))
    strength = _safe_float(signal_payload.get('strength'), 0.0)
    trend = str(signal_payload.get('trend') or 'RANGING').upper()
    volatility_label = str(signal_payload.get('volatility') or 'MEDIUM').upper()
    current_price = _safe_float((market_data or {}).get('current_price', (market_data or {}).get('price', 0.0)), 0.0)
    prices = [
        _safe_float(price, 0.0)
        for price in ((market_data or {}).get('price_history') or [])
        if _safe_float(price, 0.0) > 0
    ]
    if current_price <= 0 and prices:
        current_price = prices[-1]

    reasons: List[str] = []
    score = 0.0
    trend_points = 0
    regime_allowed = True
    regime_label = 'ranging'
    strategy_name = str(strategy_name or signal_payload.get('strategyName') or '').strip()
    range_strategy = strategy_name in {'Range Trading', 'Mean Reversion'}
    broker_name = ''
    live_binance_mode = False
    if isinstance(bot_config, dict):
        broker_name = canonicalize_broker_name(
            bot_config.get('brokerName') or bot_config.get('broker_type') or bot_config.get('broker') or ''
        )
        live_binance_mode = broker_name == 'Binance' and str(bot_config.get('mode') or '').strip().lower() == 'live'
    strong_regime_signal_floor = 25.0 if live_binance_mode else 50.0
    compressed_regime_signal_floor = 20.0 if live_binance_mode else 45.0
    trade_plan = _build_dynamic_trade_plan(symbol, market_data, direction, strength)

    if direction not in {'BUY', 'SELL'} or current_price <= 0 or len(prices) < 20:
        return {
            'score': 0.0,
            'takeTrade': False,
            'reasons': ['No directional setup'],
            'marketRegime': 'insufficient_data',
            'positionSizeMultiplier': 0.0,
            'rr': round(_safe_float(trade_plan.get('rr'), 0.0), 2),
            'tradePlan': trade_plan,
            'symbolPerformance': None,
        }

    ma_fast, ma_slow = calculate_moving_averages(prices[-50:], short=10, long=20)
    ma_anchor_fast, ma_anchor_slow = calculate_moving_averages(prices[-50:], short=20, long=40)
    macd_line, signal_line, histogram = calculate_macd(prices[-50:])
    average_move = max(_average_absolute_price_move(prices[-20:], period=14), current_price * 0.0004)
    trend_gap_pct = abs(ma_fast - ma_slow) / ma_slow * 100 if ma_slow > 0 else 0.0
    volatility_pct = _safe_float((market_data or {}).get('volatility_pct'), 0.0)
    volatility_history = [
        _safe_float(value, 0.0)
        for value in ((market_data or {}).get('volatility_history') or [])
        if _safe_float(value, 0.0) > 0
    ]
    volatility_percentile = 50.0
    if volatility_history:
        lower_samples = sum(1 for sample in volatility_history if sample <= max(volatility_pct, 0.0))
        volatility_percentile = (lower_samples / len(volatility_history)) * 100.0

    if trend != 'RANGING' and ((direction == 'BUY' and trend == 'UP') or (direction == 'SELL' and trend == 'DOWN')):
        score += 1.0
        trend_points += 1
        reasons.append('Trend aligned')
    if (direction == 'BUY' and ma_fast >= ma_slow and ma_anchor_fast >= ma_anchor_slow) or (
        direction == 'SELL' and ma_fast <= ma_slow and ma_anchor_fast <= ma_anchor_slow
    ):
        score += 1.0
        trend_points += 1
        reasons.append('EMA stack aligned')
    if (direction == 'BUY' and current_price >= ma_fast) or (direction == 'SELL' and current_price <= ma_fast):
        score += 1.0
        trend_points += 1
        reasons.append('Price closed with direction')

    if trend == 'RANGING':
        regime_label = 'ranging'
    elif trend_gap_pct >= 0.18:
        regime_label = 'strong_trend'
    else:
        regime_label = 'trend'

    if not range_strategy and trend == 'RANGING' and strength < 85.0:
        regime_allowed = False
        reasons.append('Ranging regime blocked for trend strategy')
    elif trend_points < 1 and strength < 25.0 and not range_strategy:
        regime_allowed = False
        reasons.append('Higher timeframe alignment too weak')

    pullback_threshold = max(average_move * 0.75, current_price * 0.0003)
    if abs(current_price - ma_fast) <= pullback_threshold:
        score += 1.0
        reasons.append('Pullback near trend base')
    if (direction == 'BUY' and histogram > 0 and macd_line >= signal_line) or (
        direction == 'SELL' and histogram < 0 and macd_line <= signal_line
    ):
        score += 1.0
        reasons.append('Momentum confirmation')
    recent_changes = [prices[index] - prices[index - 1] for index in range(max(1, len(prices) - 3), len(prices))]
    directional_pushes = sum(
        1 for delta in recent_changes
        if (direction == 'BUY' and delta > 0) or (direction == 'SELL' and delta < 0)
    )
    if directional_pushes >= 2:
        score += 1.0
        reasons.append('Recent candles confirm entry')

    rr_value = round(_safe_float(trade_plan.get('rr'), 0.0), 2)
    if rr_value >= 2.0:
        score += 1.0
        reasons.append(f'RR {rr_value:.1f}')
    if trade_plan.get('cleanPath', False):
        score += 1.0
        reasons.append('Clean path to target')

    if trend_gap_pct >= 0.10 or strength >= 70:
        score += 1.0
        reasons.append('Trend structure strong')
    if volatility_percentile >= 40.0 and volatility_label in {'LOW', 'MEDIUM'}:
        score += 1.0
        reasons.append('Volatility in active range')
    elif volatility_percentile < 5.0 and not range_strategy and strength < 20.0:
        regime_allowed = False
        reasons.append('ATR regime too compressed')

    if volatility_label == 'HIGH' and strength < 80:
        score -= 1.0
        reasons.append('Event/spike penalty')

    symbol_performance = None
    required_setup_score = 7.0
    if isinstance(bot_config, dict):
        management_mode = str(bot_config.get('managementMode') or 'assisted').strip().lower()
        required_setup_score = _default_setup_score_for_broker_profile(
            bot_config.get('managementProfile'),
            broker_name,
            bot_config.get('mode'),
            management_mode,
        )
        # WIN-RATE FIX: Exness demo was letting 4.5/10 setups through, which is basically random.
        # The 5.0 floor still let ~25% win-rate (near break-even) noise through. Raise the floor
        # to 6.5 so only higher-confluence setups trade. 6.5 is just below the 7.0 quality bar
        # used everywhere else, so we cut the random entries without stalling open positions.
        # If win rate is still poor, push toward 7.0; if the bot stops trading, drop toward 6.0.
        if broker_name == 'Exness':
            required_setup_score = max(6.5, required_setup_score)
        try:
            symbol_performance = _evaluate_symbol_performance(bot_config, symbol)
        except Exception:
            symbol_performance = None
        if symbol_performance:
            verdict = str(symbol_performance.get('verdict') or 'normal')
            if verdict == 'favored':
                score += 0.8
                reasons.append('Symbol performance favored')
            elif verdict == 'demoted':
                score -= 0.8
                reasons.append('Symbol performance demoted')
            elif verdict == 'blacklisted':
                regime_allowed = False
                reasons.append('Symbol performance blacklisted')

        consecutive_losses = int(bot_config.get('consecutiveLosses') or 0)
        if broker_name == 'Binance':
            if consecutive_losses >= 3:
                score -= 0.5
                reasons.append('Loss streak penalty (Binance)')
        else:
            if consecutive_losses >= 3:
                score -= 1.0
                reasons.append('Loss streak penalty')
        symbol_base = _normalize_symbol_base(symbol)
        if broker_name == 'Binance' and symbol_base not in {'BTCUSDT', 'BTCUSD', 'ETHUSDT', 'ETHUSD'}:
            btc_market_data = commodity_market_data.get('BTCUSDT') or commodity_market_data.get('BTCUSD') or {}
            btc_prices = [
                _safe_float(price, 0.0)
                for price in (btc_market_data.get('price_history') or [])
                if _safe_float(price, 0.0) > 0
            ]
            if len(btc_prices) >= 13:
                btc_anchor = btc_prices[-13]
                if btc_anchor > 0:
                    btc_move_pct = abs(btc_prices[-1] - btc_anchor) / btc_anchor * 100.0
                    if btc_move_pct > 8.0:
                        score -= 0.3
                        reasons.append('BTC impulse mild penalty on alt setup')

    score = round(max(0.0, min(10.0, score)), 1)
    trend_aligned = trend in {'UP', 'DOWN'} and (
        (direction == 'BUY' and trend == 'UP') or (direction == 'SELL' and trend == 'DOWN')
    )
    if live_binance_mode and not trend_aligned:
        extreme_countertrend_exception = strength >= 25 and score >= 3.0 and rr_value >= 1.5
        if extreme_countertrend_exception:
            reasons.append('Counter-trend high conviction allowed')
        else:
            # Allow counter-trend with reduced score instead of full block
            score -= 1.0
            reasons.append('Counter-trend penalty applied')

    # Multi-signal ensemble gate (#3): fuse strength + MACD + RSI + Bollinger +
    # regime fit into a calibrated entry probability. Only block on very low
    # probability for non-high-conviction setups, so strong trending entries
    # are never accidentally dropped — but weak-confluence noise is filtered.
    ensemble_p = _ensemble_entry_probability(
        symbol, market_data, direction, strength, strategy_name, bot_config
    )
    if ensemble_p < 0.30 and score < 8.5 and not range_strategy:
        regime_allowed = False
        reasons.append('Ensemble probability too low (%.2f)' % ensemble_p)

    # News / event guard (#5): pause NEW entries during scheduled high-impact
    # windows or a live volatility spike, so we don't open into a violent move.
    _pause, _pause_reason = _news_guard_should_pause(bot_config, symbol, market_data)
    if _pause:
        regime_allowed = False
        reasons.append('News/event guard: ' + _pause_reason)

    # Portfolio-level risk (#6): account drawdown budgeting + correlation-aware
    # exposure. Pause NEW entries when the account is already deep in drawdown or
    # the symbol's correlated group is already saturated with open positions.
    _ppause, _ppause_reason = _portfolio_risk_should_pause(bot_config, symbol)
    if _ppause:
        regime_allowed = False
        reasons.append('Portfolio risk: ' + _ppause_reason)

    take_trade = regime_allowed and score >= required_setup_score
    size_multiplier = 0.0
    if take_trade:
        size_multiplier = 1.2 if score >= 9.0 and rr_value >= 2.5 else 1.0
        if symbol_performance:
            size_multiplier *= max(0.7, min(_safe_float(symbol_performance.get('multiplier'), 1.0), 1.1))
        if isinstance(bot_config, dict) and int(bot_config.get('consecutiveLosses') or 0) >= 2:
            size_multiplier *= 0.75
        size_multiplier = round(max(0.5, min(size_multiplier, 1.2)), 3)

    return {
        'score': score,
        'takeTrade': take_trade,
        'reasons': reasons,
        'marketRegime': regime_label,
        'ensembleProbability': ensemble_p,
        'positionSizeMultiplier': size_multiplier,
        'rr': rr_value,
        'tradePlan': trade_plan,
        'symbolPerformance': symbol_performance,
    }


def _apply_setup_quality_to_trade_params(
    trade_params: Optional[Dict[str, Any]],
    symbol: str,
    market_data: Optional[Dict[str, Any]],
    bot_config: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
    if not isinstance(trade_params, dict):
        return None

    adjusted = dict(trade_params)
    signal_info = dict(adjusted.get('signal') or {})
    setup_eval = _score_signal_setup(
        symbol,
        market_data,
        signal_info,
        bot_config=bot_config,
        strategy_name=str(signal_info.get('strategyName') or ''),
    )
    if not setup_eval.get('takeTrade', False):
        return None

    trade_plan = dict(setup_eval.get('tradePlan') or {})
    signal_info['setupScore'] = _safe_float(setup_eval.get('score'), 0.0)
    signal_info['setupReasons'] = list(setup_eval.get('reasons') or [])
    signal_info['marketRegime'] = setup_eval.get('marketRegime', 'unknown')
    signal_info['rr'] = _safe_float(setup_eval.get('rr'), 0.0)
    symbol_performance = setup_eval.get('symbolPerformance') or {}
    performance_multiplier = _safe_float(symbol_performance.get('multiplier'), 1.0)
    performance_verdict = str(symbol_performance.get('verdict') or 'normal')
    signal_info['entry_reason'] = (
        f"{signal_info.get('entry_reason', 'Qualified setup')} + "
        f"Setup score {signal_info['setupScore']:.1f}/10 ({', '.join(signal_info['setupReasons'][:4])})"
    )
    signal_info['symbolPerformance'] = symbol_performance or None
    signal_info['symbolPerformanceVerdict'] = performance_verdict
    adjusted['signal'] = signal_info
    adjusted['setupScore'] = signal_info['setupScore']
    adjusted['marketRegime'] = signal_info['marketRegime']
    adjusted['rankingScore'] = round(
        ((signal_info['setupScore'] * 100.0) + (_safe_float(signal_info.get('strength'), 0.0) * 2.0) + (signal_info['rr'] * 10.0))
        * max(0.7, min(performance_multiplier, 1.25)),
        2,
    )
    if performance_verdict == 'blacklisted':
        return None

    base_volume = max(_safe_float(adjusted.get('volume'), 0.0), 0.0)
    if base_volume > 0:
        adjusted['volume'] = round(base_volume * max(_safe_float(setup_eval.get('positionSizeMultiplier'), 1.0), 0.0), 4)

    if trade_plan:
        adjusted['stop_loss'] = round(max(_safe_float(trade_plan.get('slPips'), adjusted.get('stop_loss', 0.0)), 0.0), 2)
        adjusted['take_profit'] = round(max(_safe_float(trade_plan.get('tpPips'), adjusted.get('take_profit', 0.0)), 0.0), 2)
        adjusted['trailingStopPips'] = round(max(_safe_float(trade_plan.get('trailingStopPips'), 0.0), 0.0), 2)
        adjusted['tpLevels'] = trade_plan.get('tpLevels') or []

    # Volatility-aware sizing (intelligence #2): shrink exposure when current ATR
    # is elevated vs the symbol's own baseline, so we don't load size into a hot
    # tape (e.g. XPT/USD spiking). Applied before the SL cap so the cap uses the
    # already-shrunk volume.
    if isinstance(bot_config, dict) and adjusted.get('volume', 0) > 0 and market_data:
        _vol_mult = _volatility_size_multiplier(symbol, market_data)
        if _vol_mult != 1.0:
            adjusted['volume'] = round(max(0.001, adjusted['volume'] * _vol_mult), 4)

    # Cap stop_loss to the bot's hard-loss limit so a single trade cannot
    # lose more than the per-trade budget before manage_protected_open_positions
    # gets a chance to force-close it. Without this, ATR-based SLs on volatile
    # symbols (XAU, indices) can place the broker SL 10-15 points away, and
    # the trade hits that SL before the runtime check ever fires.
    if isinstance(bot_config, dict) and adjusted.get('volume', 0) > 0:
        _hard_loss_limit, _ = _resolve_hard_loss_limits(bot_config)
        if _hard_loss_limit > 0 and adjusted.get('stop_loss', 0) > 0:
            _symbol_base = _normalize_symbol_base(symbol)
            _is_metal = _symbol_base in {'XAUUSD', 'XAGUSD', 'XPTUSD', 'XPDUSD', 'USOIL', 'UKOIL', 'XAUSD', 'XAUUSDm', 'XAGUSDm', 'XPTUSDm', 'XPDUSDm', 'USOILm', 'UKOILm'}
            _is_index = _symbol_base in {
                'US30', 'USTEC', 'US500', 'US100', 'NDX', 'NDXF',
                'NAS100', 'DAX', 'GER30', 'UK100', 'FR40', 'JP225',
                'AUS200', 'SPX', 'CAC40',
            }
            if _is_metal or _is_index:
                _usd_per_sl_unit_per_0_01lot = 1.0
            elif _is_exness_forex_symbol(_symbol_base):
                _usd_per_sl_unit_per_0_01lot = 0.01
            else:
                _usd_per_sl_unit_per_0_01lot = 0.01
            _max_sl_units = max(0.1, _hard_loss_limit / (adjusted['volume'] * _usd_per_sl_unit_per_0_01lot))
            if adjusted['stop_loss'] > _max_sl_units:
                adjusted['stop_loss'] = round(_max_sl_units, 2)

            # Dollar-risk guard on volume: even after capping the SL distance,
            # ensure the planned stop can't exceed the hard-loss budget at this
            # size. If it would, shrink volume to fit (this is the second half
            # of volatility-aware sizing — control HOW MUCH we risk, not just
            # HOW FAR the stop sits).
            _planned_risk = adjusted['stop_loss'] * adjusted['volume'] * _usd_per_sl_unit_per_0_01lot
            if _planned_risk > _hard_loss_limit:
                _safe_volume = _hard_loss_limit / max(0.01, adjusted['stop_loss'] * _usd_per_sl_unit_per_0_01lot)
                adjusted['volume'] = round(max(0.001, min(adjusted['volume'], _safe_volume)), 4)

    return adjusted


def _get_cached_strategy_params(strategy_cache: Dict[str, Optional[Dict[str, Any]]], strategy_func, symbol: str,
                                account_id: str, risk_per_trade: float,
                                market_data: Optional[Dict[str, Any]] = None,
                                bot_config: Optional[Dict[str, Any]] = None) -> Optional[Dict[str, Any]]:
    cache_key = _strategy_cache_key(strategy_func, symbol)
    if cache_key in strategy_cache:
        return strategy_cache[cache_key]

    if market_data is None:
        market_data = _get_market_data_for_symbol(symbol)

    raw_trade_params = strategy_func(symbol, account_id, risk_per_trade, market_data)
    strategy_cache[cache_key] = _apply_setup_quality_to_trade_params(
        raw_trade_params,
        symbol,
        market_data,
        bot_config=bot_config,
    )
    return strategy_cache[cache_key]


def _get_effective_symbol_params(symbol: str, market_data: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    symbol_key = _normalize_symbol_base(symbol)
    params = dict(SYMBOL_PARAMETERS.get(symbol_key, DEFAULT_SYMBOL_PARAMS))
    pair_config = _get_pair_execution_config(symbol_key)
    if pair_config:
        params.update(_build_pair_param_overrides(symbol_key, pair_config))

    sl_multiplier = max(_safe_float(params.get('sl_multiplier'), 0.0), 0.0)
    tp2_multiplier = max(_safe_float(params.get('tp2_multiplier'), 0.0), 0.0)
    base_stop_loss = max(_safe_float(params.get('stop_loss_pips'), 0.0), 1.0)
    if sl_multiplier > 0 and tp2_multiplier > 0:
        params['take_profit_pips'] = round(max(base_stop_loss * (tp2_multiplier / sl_multiplier), base_stop_loss), 2)

    adaptive_reduction = 0
    if isinstance(market_data, dict):
        try:
            adaptive_reduction = int(market_data.get('adaptive_min_signal_reduction') or 0)
        except (TypeError, ValueError):
            adaptive_reduction = 0

    if symbol_key in SMALL_LIVE_ACCOUNT_OPTIONAL_CRYPTO_BASE_SYMBOLS:
        adaptive_reduction = min(adaptive_reduction, 5)

    params['effective_min_signal_strength'] = max(5, int(params['min_signal_strength']) - max(0, adaptive_reduction))
    # Honor bot manual signalThreshold: clamp per-symbol floor down to user's threshold
    # (never raise it). This lets a manual threshold of e.g. 2 actually allow weak signals
    # to pass strategy gates instead of being silently filtered by the 50-floor in SYMBOL_PARAMETERS.
    if isinstance(market_data, dict):
        _bot_thr_override = market_data.get('bot_signal_threshold_override')
        if _bot_thr_override is not None:
            try:
                params['effective_min_signal_strength'] = max(
                    5,
                    min(int(params['effective_min_signal_strength']), int(_bot_thr_override)),
                )
            except (TypeError, ValueError):
                pass
    return params


def _try_ml_auto_execute_override(
    symbol: str,
    market_data: Dict[str, Any],
    raw_signal: Dict[str, Any],
    bot_config: Optional[Dict[str, Any]] = None,
    existing_trade_params: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
    """If ML confidence is high enough, override strategy rejection with ML-driven trade params."""
    if existing_trade_params is not None:
        return existing_trade_params
    ml_confidence_threshold = _safe_float((bot_config or {}).get('mlAutoExecuteConfidence'), 0.0)
    if ml_confidence_threshold <= 0:
        ml_confidence_threshold = _resolve_ml_confidence_threshold(bot_config, market_data=market_data)
        if ml_confidence_threshold <= 0:
            return None
    ml_eval = (raw_signal or {}).get('ml_pipeline') or {}
    ml_signal_score = ml_eval.get('signal_score') or {}
    ml_p_win = _safe_float(ml_signal_score.get('p_win'), 0.0)
    if ml_p_win < ml_confidence_threshold:
        return None
    ml_sltp = ml_eval.get('sltp') or {}
    ml_direction = str((raw_signal or {}).get('signal') or '').upper()
    if 'BUY' in ml_direction:
        order_type = 'BUY'
    elif 'SELL' in ml_direction:
        order_type = 'SELL'
    else:
        return None
    return {
        'type': order_type,
        'signal': {
            'signal': order_type,
            'strength': 100.0,
            'entry_reason': f"ML auto-execute: P(win)={ml_p_win:.1f}% >= {ml_confidence_threshold:.1f}% threshold",
            'rr': _safe_float(ml_sltp.get('rr_ratio'), 0.0),
        },
        'stop_loss': _safe_float(ml_sltp.get('sl_pips'), 0.0),
        'take_profit': _safe_float(ml_sltp.get('tp1_pips'), 0.0),
        'take_profit_2': _safe_float(ml_sltp.get('tp2_pips'), 0.0),
        'source': 'ml_auto_execute',
        'ml_pipeline': ml_eval,
    }


def _resolve_ml_confidence_threshold(
    bot_config: Optional[Dict[str, Any]] = None,
    market_data: Optional[Dict[str, Any]] = None,
) -> float:
    """Auto-derive ML confidence threshold from model accuracy when not explicitly configured.

    When market_data is provided, the threshold is nudged based on regime confidence:
    - CHOP_HIGH_VOL regime: +10% (more selective in choppy markets)
    - Strong trending regime with high confidence: -5% (more aggressive in clear trends)
    - Low regime confidence (<0.6): +5% (more selective when uncertain)
    """
    configured = _safe_float((bot_config or {}).get('mlAutoExecuteConfidence'), 0.0)
    if configured > 0:
        return configured
    try:
        from ml_pipeline import get_ml_pipeline
        pipeline = get_ml_pipeline()
        base_threshold = 60.0
        if pipeline and getattr(pipeline, 'anomaly', None) and getattr(pipeline.anomaly, 'win_history', None):
            history = pipeline.anomaly.win_history
            if len(history) >= 20:
                recent = history[-40:] if len(history) >= 40 else history
                accuracy = sum(1 for r in recent if r.get('actual')) / len(recent)
                base_threshold = max(55.0, min(75.0, accuracy * 100.0))
        if market_data and pipeline and getattr(pipeline, 'regime_filter', None) and pipeline.regime_filter.is_ready:
            try:
                regime_eval = pipeline.regime_filter.classify_regime(market_data)
                regime_conf = _safe_float(regime_eval.get('confidence'), 0.0)
                regime_label = str(regime_eval.get('regime', '')).upper()
                if 'CHOP' in regime_label:
                    base_threshold = min(85.0, base_threshold + 10.0)
                elif regime_conf >= 80.0 and ('TREND' in regime_label):
                    base_threshold = max(50.0, base_threshold - 5.0)
                elif regime_conf < 60.0:
                    base_threshold = min(80.0, base_threshold + 5.0)
            except Exception:
                pass
        return base_threshold
    except Exception:
        pass
    return 60.0


def _apply_ml_sizing_to_position(
    bot_config: Optional[Dict[str, Any]],
    symbol: str,
    market_data: Optional[Dict[str, Any]],
    position_size: float,
    existing_positions: Optional[List[Dict[str, Any]]] = None,
) -> float:
    """Apply ML position-size multiplier to the base position_size.

    Returns the adjusted position_size. If ML is unavailable or the symbol
    is not approved by ML, the original position_size is returned unchanged.
    """
    if not bot_config or position_size <= 0:
        return position_size
    try:
        from ml_pipeline import get_ml_pipeline
        pipeline = get_ml_pipeline()
        if not pipeline:
            return position_size
        existing_pos = [p.get('symbol', '') for p in (existing_positions or []) if isinstance(p, dict)]
        raw_signal_for_ml = {'signal': 'BUY'}
        ml_eval = pipeline.evaluate_entry(symbol, market_data or {}, raw_signal_for_ml, existing_pos)
        if not ml_eval.get('should_trade', True):
            return 0.0
        ml_pos = ml_eval.get('position_size') or {}
        ml_mult = _safe_float(ml_pos.get('size_multiplier'), 0.0)
        if ml_mult > 0:
            return max(0.0, position_size * ml_mult)
    except ImportError:
        pass
    except Exception:
        pass
    return position_size


def _get_ml_drawdown_throttle(bot_config: Optional[Dict[str, Any]] = None) -> float:
    """Return a size throttle multiplier based on recent ML model performance.

    If the ML pipeline's recent win rate is underperforming, reduce exposure
    to protect account balance growth. Returns 1.0 when ML is healthy or unavailable.
    """
    try:
        from ml_pipeline import get_ml_pipeline
        pipeline = get_ml_pipeline()
        if not pipeline or not getattr(pipeline, 'anomaly', None):
            return 1.0
        history = getattr(pipeline.anomaly, 'win_history', None) or []
        if len(history) < 10:
            return 1.0
        recent = history[-30:]
        wins = sum(1 for r in recent if r.get('actual'))
        win_rate = wins / len(recent)
        if win_rate < 0.35:
            return 0.5
        if win_rate < 0.45:
            return 0.75
        return 1.0
    except ImportError:
        pass
    except Exception:
        pass
    return 1.0


def _ml_exit_evaluate(
    bot_id: str,
    symbol: str,
    tracked: Dict[str, Any],
    current_position: Dict[str, Any],
    market_data: Dict[str, Any],
    bot_config: Optional[Dict[str, Any]] = None,
) -> Optional[str]:
    """Use ML exit model to evaluate whether to close or adjust an open position.
    
    Returns a close_reason string if ML recommends exiting, otherwise None.
    Only acts on profitable positions unless ML is very confident about a loss exit.
    """
    current_profit = _safe_float(tracked.get('profit'), 0.0)
    peak_profit = _safe_float(tracked.get('peakProfit'), 0.0)
    if current_profit <= 0 and peak_profit <= 0:
        return None
    ml_confidence_threshold = _resolve_ml_confidence_threshold(bot_config)
    try:
        from ml_exit_manager import get_exit_predictor
        exit_predictor = get_exit_predictor()
        if not exit_predictor.is_ready:
            return None
        entry_time = str(tracked.get('entryTime') or '')
        time_in_trade_min = _position_age_minutes(entry_time)
        exit_pred = exit_predictor.predict_exit(
            symbol=symbol,
            direction=str(tracked.get('type', 'buy')).upper(),
            current_pnl=current_profit,
            peak_pnl=peak_profit,
            entry_time=entry_time,
            current_rsi=market_data.get('rsi', 50.0),
            current_macd=market_data.get('macd_hist', 0.0),
            volatility_pct=market_data.get('volatility_pct', 1.0),
            distance_to_tp_pips=_safe_float(tracked.get('takeProfitPips'), 100),
            distance_from_sl_pips=_safe_float(tracked.get('stopLossPips'), 50),
            consecutive_bars=max(1, int(time_in_trade_min / 2)),
            spread_pct=0.01,
        )
        confidence = _safe_float(exit_pred.get('confidence'), 0.0)
        if confidence < ml_confidence_threshold:
            return None
        action = str(exit_pred.get('action', 'HOLD')).upper()
        if action == 'CLOSE_FULL':
            return 'EXIT_ML_FULL'
        elif action == 'CLOSE_PARTIAL':
            return 'EXIT_ML_PARTIAL'
        elif action == 'TRAIL_STOP':
            return 'EXIT_ML_TRAIL'
        return None
    except ImportError:
        return None
    except Exception as e:
        logger.debug(f"[ExitML] Evaluation error for {symbol}: {e}")
        return None


def _build_adaptive_raw_trade_params(
    symbol: str,
    market_data: Dict[str, Any],
    raw_signal: Dict[str, Any],
    bot_config: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
    """Build a conservative fallback trade when scanner finds a strong raw setup.

    Used only by adaptive scanner mode when strategy-specific filters reject a
    setup that still has unusually strong raw signal quality.
    """
    order_type = extract_signal_direction(raw_signal.get('signal'))
    trend = str(raw_signal.get('trend') or '').upper()
    broker_name = canonicalize_broker_name(
        (bot_config or {}).get('brokerName') or (bot_config or {}).get('broker_type') or (bot_config or {}).get('broker') or ''
    )
    mode_value = str((bot_config or {}).get('mode') or (bot_config or {}).get('botMode') or 'demo').strip().lower()
    is_demo_mode = mode_value != 'live' and not bool((bot_config or {}).get('is_live'))
    demo_validation_fallback_enabled = _coerce_bool(
        os.getenv('DEMO_BINANCE_VALIDATION_FALLBACK', 'false'),
        False,
    )
    is_binance_demo_validation = (
        isinstance(bot_config, dict)
        and broker_name == 'Binance'
        and is_demo_mode
        and demo_validation_fallback_enabled
    )
    if trend == 'RANGING' and not is_binance_demo_validation:
        return None

    signal_payload = dict(raw_signal)
    if order_type is None and isinstance(bot_config, dict):
        broker_name = canonicalize_broker_name(
            bot_config.get('brokerName') or bot_config.get('broker_type') or bot_config.get('broker') or ''
        )
        adaptive_floor = _adaptive_signal_threshold_floor(bot_config)
        strength = float(raw_signal.get('strength') or 0.0)
        volatility = str(raw_signal.get('volatility') or '').upper()
        if (
            broker_name == 'FXCM'
            and strength >= adaptive_floor
            and trend in {'UP', 'DOWN'}
            and volatility in {'LOW', 'MEDIUM'}
        ):
            order_type = 'BUY' if trend == 'UP' else 'SELL'
            signal_payload['signal'] = order_type
            signal_payload['entry_reason'] = (
                f"{signal_payload.get('entry_reason', 'Neutral raw setup')} + "
                f"FXCM trend-directed fallback at adaptive floor"
            )

    if order_type is None and is_binance_demo_validation:
        strength = float(raw_signal.get('strength') or 0.0)
        adaptive_floor = _adaptive_signal_threshold_floor(bot_config)
        if strength >= adaptive_floor:
            order_type = 'BUY'
            signal_payload['signal'] = 'BUY'
            signal_payload['entry_reason'] = (
                f"{signal_payload.get('entry_reason', 'Neutral raw setup')} + "
                f"Demo Binance validation fallback BUY"
            )

    if order_type is None:
        return None

    params = _get_effective_symbol_params(symbol, market_data)
    strength = float(raw_signal.get('strength') or 0.0)
    if broker_name == 'FXCM':
        volume = 0.01 if strength < 85 else 0.02
    else:
        volume = 0.6 if strength < 85 else 0.75
    raw_reason = signal_payload.get('entry_reason', 'High-conviction raw scanner setup')
    signal_payload['entry_reason'] = f"{raw_reason} + Adaptive scanner raw-signal fallback"

    return {
        'symbol': symbol,
        'type': order_type,
        'volume': volume,
        'stop_loss': params['stop_loss_pips'],
        'take_profit': params['take_profit_pips'] * 1.4,
        'signal': attach_execution_direction(signal_payload, order_type, 'Adaptive Scanner Fallback'),
        'duration_seconds': 900,
        'execution_source': 'adaptive_raw_fallback',
    }


def _get_binance_spot_inventory_snapshot(active_conn, symbol: str, market_price: float = 0.0) -> Dict[str, Any]:
    normalized_symbol = active_conn._normalize_symbol(symbol) if hasattr(active_conn, '_normalize_symbol') else str(symbol or '').upper()
    base_asset = str(normalized_symbol or symbol or '').upper()
    if base_asset.endswith('USDT'):
        base_asset = base_asset[:-4]

    free_balance = 0.0
    if hasattr(active_conn, '_get_spot_asset_free_balance'):
        free_balance = _safe_float(active_conn._get_spot_asset_free_balance(base_asset), 0.0)

    min_qty = 0.0
    min_notional = 0.0
    step_size = 0.0
    normalized_balance = free_balance

    if hasattr(active_conn, '_get_spot_symbol_filters'):
        spot_filters = active_conn._get_spot_symbol_filters(normalized_symbol)
        if isinstance(spot_filters, dict):
            lot_size_filter = spot_filters.get('LOT_SIZE', {})
            min_notional_filter = spot_filters.get('MIN_NOTIONAL', {})
            notional_filter = spot_filters.get('NOTIONAL', {})
            min_qty = _safe_float(lot_size_filter.get('minQty'), 0.0)
            step_size = _safe_float(lot_size_filter.get('stepSize'), 0.0)
            min_notional = max(
                _safe_float(min_notional_filter.get('minNotional'), 0.0),
                _safe_float(notional_filter.get('minNotional'), 0.0),
            )
            if hasattr(active_conn, '_normalize_spot_quantity'):
                normalized_balance = _safe_float(
                    active_conn._normalize_spot_quantity(free_balance, step_size, 0.0),
                    free_balance,
                )

    if market_price <= 0 and hasattr(active_conn, '_get_spot_symbol_price'):
        market_price = _safe_float(active_conn._get_spot_symbol_price(normalized_symbol), 0.0)

    has_min_qty = min_qty <= 0 or normalized_balance >= min_qty
    has_min_notional = min_notional <= 0 or market_price <= 0 or (normalized_balance * market_price) >= min_notional
    is_sellable = normalized_balance > 0 and has_min_qty and has_min_notional

    return {
        'symbol': normalized_symbol,
        'baseAsset': base_asset,
        'freeBalance': free_balance,
        'normalizedBalance': normalized_balance,
        'marketPrice': market_price,
        'minQty': min_qty,
        'minNotional': min_notional,
        'isSellable': is_sellable,
    }

def validate_api_key():
    """Validate API key from request headers"""
    api_key = request.headers.get('Authorization', '').replace('Bearer ', '')
    if not api_key:
        return False, "Missing API key in Authorization header"
    if api_key != API_KEY:
        return False, "Invalid API key"
    return True, "Valid"

def require_api_key(f):
    """Decorator to require API key authentication"""
    from functools import wraps
    @wraps(f)
    def decorated_function(*args, **kwargs):
        valid, message = validate_api_key()
        if not valid:
            return jsonify({'success': False, 'error': message}), 401
        return f(*args, **kwargs)
    return decorated_function

def require_session(f):
    """Decorator to require valid session token and extract user_id"""
    from functools import wraps
    @wraps(f)
    def decorated_function(*args, **kwargs):
        # Get session token from header - CRITICAL DEBUGGING FOR 401 ISSUES
        session_token = request.headers.get('X-Session-Token')

        def _mask_session_token(token: str) -> str:
            token_str = str(token or '').strip()
            if not token_str:
                return '<empty>'
            if len(token_str) <= 12:
                return token_str
            return f"{token_str[:6]}...{token_str[-4:]}"
        
        # Log all headers to diagnose missing token issue
        if not session_token:
            event_key = f"missing_token:{request.method}:{request.path}:{request.remote_addr}"
            if should_log_session_event(event_key, 30):
                logger.warning(f"🚨 [CRITICAL] MISSING X-Session-Token for {request.method} {request.path}")
                logger.warning(f"🌐 Client IP: {request.remote_addr}")
        else:
            logger.debug(f"[SESSION CHECK] Endpoint: {request.endpoint}, Token present")
        
        if not session_token:
            if should_log_session_event(f"missing_token_fail:{request.endpoint}:{request.remote_addr}", 30):
                logger.error(f"[SESSION FAIL] Missing X-Session-Token header for {request.endpoint}")
            return jsonify({'success': False, 'error': 'Missing session token in X-Session-Token header'}), 401

        cached_user_id, cache_source = get_recent_cached_session(session_token)
        if cached_user_id:
            request.user_id = cached_user_id
            logger.debug(f"[SESSION OK] {cache_source.title()} cache hit for user {cached_user_id} on {request.endpoint}")
            return f(*args, **kwargs)
        
        try:
            conn = get_db_connection()
            cursor = conn.cursor()
            
            # Query user_sessions table
            logger.debug(f"[SESSION QUERY] Looking for token: '{_mask_session_token(session_token)}'")
            cursor.execute('''
                SELECT user_id, expires_at, is_active 
                FROM user_sessions 
                WHERE token = ? AND is_active = 1
            ''', (session_token,))
            
            session = cursor.fetchone()
            logger.debug(f"[SESSION QUERY RESULT] token_found={bool(session)}")
            conn.close()
            
            if not session:
                # Try without the is_active filter to see if token exists at all
                conn2 = get_db_connection()
                cursor2 = conn2.cursor()
                cursor2.execute('SELECT token, is_active FROM user_sessions WHERE token = ?', (session_token,))
                all_sessions = cursor2.fetchall()
                if should_log_session_event(f"token_status:{request.endpoint}:{request.remote_addr}", 30):
                    logger.info(f"[🔍 TOKEN STATUS] Found {len(all_sessions)} matching token(s): {all_sessions}")
                conn2.close()
                if should_log_session_event(f"invalid_token:{request.endpoint}:{request.remote_addr}", 30):
                    logger.error(f"[SESSION FAIL] Token not found in DB or inactive: {session_token[:20]}...")
                return jsonify({'success': False, 'error': 'Invalid or inactive session token'}), 401
            
            # Check expiration
            expires_at = datetime.fromisoformat(session['expires_at'])
            if expires_at < datetime.now():
                if should_log_session_event(f"expired_token:{session['user_id']}:{request.endpoint}", 30):
                    logger.error(f"[SESSION FAIL] Token expired for user {session['user_id']}")
                return jsonify({'success': False, 'error': 'Session token expired'}), 401
            
            # Attach user_id to request for use in the route handler
            request.user_id = session['user_id']
            SESSION_VALIDATION_CACHE[session_token] = {
                'user_id': session['user_id'],
                'expires_at': session['expires_at'],
                'validated_at': time.time(),
            }
            _enforce_cache_bound(SESSION_VALIDATION_CACHE)
            logger.debug(f"[SESSION OK] User {session['user_id']} authenticated for {request.endpoint}")
            return f(*args, **kwargs)
        except sqlite3.OperationalError as e:
            if 'locked' in str(e).lower():
                cached_user_id, cache_source = get_recent_cached_session(session_token)
                if cached_user_id:
                    request.user_id = cached_user_id
                    if should_log_session_event(f"session_lock_cache_fallback:{request.endpoint}:{request.remote_addr}", 15):
                        logger.warning(
                            f"[SESSION WARN] SQLite locked during session validation for {request.endpoint}; "
                            f"using {cache_source} cache for user {cached_user_id}"
                        )
                    return f(*args, **kwargs)
            logger.error(f"Error validating session: {e}")
            return jsonify({'success': False, 'error': 'Session validation error'}), 500
        except Exception as e:
            logger.error(f"Error validating session: {e}")
            return jsonify({'success': False, 'error': 'Session validation error'}), 500
    
    return decorated_function


@app.before_request
def audit_bot_requests():
    if request.path not in ['/api/bot/create', '/api/bot/start', '/api/bot/quick-create']:
        return None

    try:
        token = request.headers.get('X-Session-Token', '')
        token_preview = f"{token[:12]}..." if token else 'missing'
        payload = request.get_json(silent=True) or {}
        logger.info(
            f"[BOT REQUEST] {request.method} {request.path} from {request.remote_addr} "
            f"token={token_preview} payload_keys={sorted(payload.keys())}"
        )

        if request.path == '/api/bot/create':
            logger.info(
                f"[BOT CREATE REQUEST] credentialId={payload.get('credentialId')} "
                f"mode={payload.get('mode') or payload.get('botMode')} "
                f"isLive={payload.get('isLive', payload.get('is_live'))} "
                f"symbols={payload.get('symbols') or payload.get('symbol')} strategy={payload.get('strategy')}"
            )
        elif request.path == '/api/bot/start':
            logger.info(
                f"[BOT START REQUEST] botId={payload.get('botId')} user_id={payload.get('user_id')}"
            )
        elif request.path == '/api/bot/quick-create':
            logger.info(
                f"[BOT QUICK REQUEST] credentialId={payload.get('credentialId')} preset={payload.get('preset')}"
            )
    except Exception as exc:
        logger.warning(f"[BOT REQUEST] Audit logging failed for {request.path}: {exc}")

    return None

def require_admin(f):
    """Decorator to require admin authorization"""
    from functools import wraps
    @wraps(f)
    def decorated_function(*args, **kwargs):
        # Get API key for admin verification
        valid, message = validate_api_key()
        if not valid:
            return jsonify({'success': False, 'error': 'Admin authentication required'}), 401
        
        # Optionally add additional admin role check from database if needed
        # For now, API key validation is sufficient for admin endpoints
        return f(*args, **kwargs)
    
    return decorated_function

