@app.route('/api/admin/metaapi/provision', methods=['POST'])
def provision_metaapi_account():
    """Provision a new MetaAPI cloud account for REST trading"""
    api_key = request.headers.get('Authorization', '').replace('Bearer ', '')
    if api_key != API_KEY:
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401

    if not metaapi_client or not metaapi_client.enabled:
        return jsonify({'success': False, 'error': 'MetaAPI not configured. Set METAAPI_TOKEN in .env'}), 400

    data = request.json or {}
    login = data.get('login')
    password = data.get('password')
    server = data.get('server')
    broker = data.get('broker', 'Exness')

    if not login or not password or not server:
        return jsonify({'success': False, 'error': 'login, password, and server are required'}), 400

    try:
        account_id = metaapi_client.get_or_provision(
            login=login, password=password, server=server, broker=broker)
        ready = metaapi_client.wait_for_ready(account_id, timeout_seconds=60)
        return jsonify({
            'success': True,
            'metaapi_account_id': account_id,
            'ready': ready,
            'message': f'Account provisioned and {"connected" if ready else "connecting"}',
        })
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)}), 500


# ==================== BOT LIST ENDPOINT ====================
@app.route('/api/bots/list', methods=['GET'])
def get_bots_list():
    """Get list of all bots (public endpoint, no auth required)"""
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Get all bots from database
        cursor.execute("""
            SELECT * FROM user_bots ORDER BY created_at DESC
        """)
        
        rows = cursor.fetchall()
        columns = [desc[0] for desc in cursor.description]
        conn.close()
        
        # Convert to list of dicts
        bots = []
        for row in rows:
            bot = {}
            for i, col_name in enumerate(columns):
                val = row[i]
                # Type conversion for known fields
                if col_name == 'enabled' or col_name == 'is_live':
                    bot[col_name] = bool(val)
                elif col_name in ('daily_profit', 'total_profit'):
                    bot[col_name] = float(val) if val else 0.0
                else:
                    bot[col_name] = val
            bots.append(bot)

            # Keep a last known-good snapshot so transient DB faults don't make
            # clients clear bot state and appear empty.
            get_bots_list._last_successful_bots = list(bots)
            get_bots_list._last_successful_at = datetime.now().isoformat()
        
        logger.info(f"[/api/bots/list] Returning {len(bots)} bots")
        
        return jsonify({
            'success': True,
            'bots': bots,
            'count': len(bots),
            'timestamp': datetime.now().isoformat()
        }), 200
    
    except Exception as e:
        logger.exception(f"[/api/bots/list] Error: {e}")
        fallback_bots = []
        fallback_source = 'none'

        cached_bots = getattr(get_bots_list, '_last_successful_bots', None)
        if isinstance(cached_bots, list) and cached_bots:
            fallback_bots = list(cached_bots)
            fallback_source = 'last_successful_snapshot'
        elif isinstance(active_bots, dict) and active_bots:
            for fallback_bot_id, fallback_bot in active_bots.items():
                if not isinstance(fallback_bot, dict):
                    continue
                fallback_bots.append({
                    'id': fallback_bot.get('id') or fallback_bot.get('bot_id') or fallback_bot_id,
                    'bot_id': fallback_bot.get('bot_id') or fallback_bot.get('id') or fallback_bot_id,
                    'name': fallback_bot.get('name') or fallback_bot.get('botName') or f"Bot {fallback_bot_id}",
                    'symbol': fallback_bot.get('symbol') or ','.join(fallback_bot.get('symbols') or []),
                    'broker_type': fallback_bot.get('broker_type') or fallback_bot.get('brokerName') or fallback_bot.get('broker'),
                    'enabled': bool(fallback_bot.get('enabled', False)),
                    'is_live': bool(fallback_bot.get('is_live') or str(fallback_bot.get('mode', '')).lower() == 'live'),
                    'daily_profit': _safe_float(fallback_bot.get('daily_profit'), 0.0),
                    'total_profit': _safe_float(fallback_bot.get('total_profit'), _safe_float(fallback_bot.get('totalProfit'), 0.0)),
                    'runtime_fallback': True,
                })
            fallback_source = 'active_bots_runtime'

        status_code = 200 if fallback_bots else 500
        return jsonify({
            'success': bool(fallback_bots),
            'degraded': True,
            'error': str(e),
            'bots': fallback_bots,
            'count': len(fallback_bots),
            'timestamp': datetime.now().isoformat(),
            'source': fallback_source,
            'snapshot_at': getattr(get_bots_list, '_last_successful_at', None),
        }), status_code


# ==================== CLEANUP ENDPOINT ====================
@app.route('/api/bots/runtime/prune-ghosts', methods=['POST'])
@require_session
def prune_runtime_ghost_bots():
    """Remove inactive runtime-only ghost bots for the current user."""
    try:
        user_id = request.user_id
        removed = []

        for bot_id, bot in list(active_bots.items()):
            if not isinstance(bot, dict):
                continue
            if bot.get('user_id') != user_id:
                continue

            open_positions = bot.get('open_positions') if isinstance(bot.get('open_positions'), dict) else {}
            bot_thread = bot_threads.get(bot_id)
            is_running = bool(running_bots.get(bot_id, False))
            is_alive = bool(bot_thread and bot_thread.is_alive())
            is_pending = bool(bot_start_pending.get(bot_id))
            is_enabled = bool(bot.get('enabled', False))

            if is_enabled or is_running or is_alive or is_pending or open_positions:
                continue

            active_bots.pop(bot_id, None)
            running_bots.pop(bot_id, None)
            bot_threads.pop(bot_id, None)
            bot_stop_flags.pop(bot_id, None)
            bot_start_pending.pop(bot_id, None)
            removed.append(bot_id)

        logger.info(
            f"🧹 Pruned {len(removed)} runtime ghost bot(s) for user {user_id}: "
            f"{', '.join(removed[:10]) if removed else 'none'}"
        )
        return jsonify({'success': True, 'removed': removed, 'removedCount': len(removed)}), 200
    except Exception as e:
        logger.error(f"❌ Error pruning runtime ghost bots: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/bots/cleanup', methods=['POST'])
def cleanup_demo_bots():
    """Remove all demo/test bots from database and memory (admin/protected endpoint)"""
    # Optionally, require API key or session for security
    api_key = request.headers.get('Authorization', '').replace('Bearer ', '')
    if api_key != API_KEY:
        return jsonify({'success': False, 'error': 'Unauthorized'}), 401
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        # Remove bots with 'demo', 'test', 'sample', or 'dummy' in name or strategy
        match_clause = "LOWER(name) LIKE '%demo%' OR LOWER(name) LIKE '%test%' OR LOWER(name) LIKE '%sample%' OR LOWER(name) LIKE '%dummy%' OR LOWER(strategy) LIKE '%demo%' OR LOWER(strategy) LIKE '%test%' OR LOWER(strategy) LIKE '%sample%' OR LOWER(strategy) LIKE '%dummy%'"
        cursor.execute(f"SELECT bot_id FROM user_bots WHERE {match_clause}")
        matched_bot_ids = [row[0] for row in cursor.fetchall()]
        if matched_bot_ids:
            params = [(bid,) for bid in matched_bot_ids]
            # Delete child rows first (bot_credentials.bot_id FK -> user_bots.bot_id),
            # otherwise Postgres raises "violates foreign key constraint
            # bot_credentials_bot_id_fkey ... is still referenced from table bot_credentials"
            cursor.executemany('DELETE FROM bot_credentials WHERE bot_id = ?', params)
            cursor.executemany('DELETE FROM bot_deletion_tokens WHERE bot_id = ?', params)
            cursor.executemany('DELETE FROM bot_activation_pins WHERE bot_id = ?', params)
            cursor.executemany('DELETE FROM user_bots WHERE bot_id = ?', params)
        conn.commit()
        conn.close()
        # Remove from memory
        to_remove = [bid for bid, bot in active_bots.items() if any(x in (bot.get('strategy','')+bot.get('botId','')+bot.get('accountId','')).lower() for x in ['demo','test','sample','dummy'])]
        for bid in to_remove:
            del active_bots[bid]
        logger.info(f"✅ Removed {len(to_remove)} demo/test bots from memory and database.")
        return jsonify({'success': True, 'removed': len(to_remove)}), 200
    except Exception as e:
        logger.error(f"❌ Error cleaning up demo/test bots: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/bots/delete-all', methods=['POST'])
@require_session
def delete_all_user_bots():
    """Delete ALL bots for the current user to start fresh"""
    try:
        user_id = request.user_id  # From session decorator
        
        # Get all bot IDs for this user
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('SELECT bot_id FROM user_bots WHERE user_id = ?', (user_id,))
        db_bot_ids = [row[0] for row in cursor.fetchall()]

        conn.close()

        runtime_bot_ids = [
            bot_id for bot_id, bot_config in active_bots.items()
            if bot_config.get('user_id') == user_id
        ]
        bot_ids = list(dict.fromkeys(db_bot_ids + runtime_bot_ids))

        removed_count = 0
        closed_positions = 0
        errors = []
        for bot_id in bot_ids:
            try:
                was_running = bot_id in active_bots and bool(active_bots[bot_id].get('enabled', False))
                deletion_result = _delete_bot_internal(bot_id, user_id, reason='delete all request')
                if was_running:
                    removed_count += 1
                closed_positions += len(deletion_result.get('closed_positions', []))
            except Exception as delete_error:
                errors.append({'botId': bot_id, 'error': str(delete_error)})

        if errors:
            return jsonify({
                'success': False,
                'error': 'One or more bots could not be deleted safely',
                'deleted_count': len(bot_ids) - len(errors),
                'stopped_count': removed_count,
                'closed_positions': closed_positions,
                'failures': errors,
            }), 500
        
        logger.info(f"✅ Deleted {len(bot_ids)} bots for user {user_id} ({removed_count} were running)")
        
        return jsonify({
            'success': True,
            'message': f'Successfully deleted {len(bot_ids)} bots',
            'deleted_count': len(bot_ids),
            'stopped_count': removed_count,
            'closed_positions': closed_positions,
        }), 200
        
    except Exception as e:
        logger.error(f"❌ Error deleting all bots for user: {e}", exc_info=True)
        return jsonify({'success': False, 'error': str(e)}), 500


