@app.route('/api/trades-public', methods=['GET'])
def get_trades_public():
    """Get all trades (public - no authentication required) - for demo/public bots"""
    try:
        trades_list = []
        
        # Get trades from active bots' trade history
        for bot_id, bot in active_bots.items():
            if 'tradeHistory' in bot:
                trades_list.extend(bot['tradeHistory'][-100:])  # Last 100 trades per bot
        
        # Sort by recent first and limit to 1000 total
        # Normalize sort key to str to prevent TypeError when mixing int and str timestamps
        trades_list = sorted(trades_list, key=lambda x: str(x.get('time', '')), reverse=True)[:1000]
        
        logger.info(f"Returning {len(trades_list)} public trades from active bots")
        return jsonify({
            'success': True,
            'trades': trades_list,
            'timestamp': datetime.now().isoformat(),
        })
    except Exception as e:
        logger.error(f"Error getting public trades: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/trades/unified', methods=['GET'])
@require_session
def get_unified_trades():
    """Get unified trades from all user's brokers (XM + MT5)"""
    try:
        user_id = request.user_id
        trades_list = []
        broker_summary = {}

        # Fetch trades from all connected brokers
        conn = get_db_connection()
        cursor = conn.cursor()
        
        # Get all broker credentials for this user
        cursor.execute('''
            SELECT broker_name, account_number, credential_id 
            FROM broker_credentials
            WHERE user_id = ? AND is_active = 1
        ''', (user_id,))
        
        credentials = cursor.fetchall()
        
        for cred in credentials:
            broker_name = cred['broker_name']
            account_number = cred['account_number']
            
            try:
                # Get connection for this broker
                connection = broker_manager.connections.get(f"{broker_name}_{account_number}")
                
                if connection and connection.connected:
                    # Fetch trades from broker
                    broker_trades = connection.get_trades()
                    
                    # Add broker info to each trade
                    for trade in broker_trades:
                        trade['broker'] = broker_name
                        trade['account'] = account_number
                        trades_list.append(trade)
                    
                    # Track broker summary
                    broker_summary[broker_name] = {
                        'account': account_number,
                        'trades_count': len(broker_trades),
                        'total_profit': sum(t.get('profit', 0) for t in broker_trades)
                    }
                    
                    logger.info(f"✅ Fetched {len(broker_trades)} trades from {broker_name} account {account_number}")
            except Exception as e:
                logger.warning(f"⚠️  Could not fetch trades from {broker_name}: {e}")
        
        conn.close()
        
        # Also get demo trades from active bots for this user
        for bot_id, bot in active_bots.items():
            if bot.get('user_id') == user_id and 'tradeHistory' in bot:
                for trade in bot['tradeHistory'][-50:]:  # Last 50 trades
                    trade['broker'] = 'DEMO'
                    trade['bot_id'] = bot_id
                    trades_list.append(trade)
        
        # Sort by time (most recent first)
        trades_list = sorted(trades_list, key=lambda x: str(x.get('time', '')), reverse=True)[:500]
        
        logger.info(f"✅ Returning {len(trades_list)} unified trades for user {user_id}")
        
        return jsonify({
            'success': True,
            'trades': trades_list,
            'total_trades': len(trades_list),
            'broker_summary': broker_summary,
            'timestamp': datetime.now().isoformat()
        }), 200
        
    except Exception as e:
        logger.error(f"Error fetching unified trades: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500
    except Exception as e:
        logger.error(f"Error in get_trades_public: {e}")
        return jsonify({
            'success': False,
            'trades': [],
            'error': str(e),
            'timestamp': datetime.now().isoformat(),
        }), 500


# ==================== ALIAS ROUTES (for Flutter app compatibility) ====================
@app.route('/api/trades', methods=['GET'])
@require_session
def get_trades_alias():
    """Get trades for the authenticated user - returns flattened trades list"""
    try:
        user_id = request.user_id  # From require_session decorator
        runtime_bots_by_id = {
            str(bot_id): bot
            for bot_id, bot in active_bots.items()
            if bot.get('user_id') == user_id
        }

        def _load_trades_from_sources():
            trades_list = []
            seen_trade_keys = set()
            conn = build_sqlite_connection(wal=False)
            cursor = conn.cursor()

            try:
                cursor.execute('''
                    SELECT bot_id FROM user_bots WHERE user_id = ?
                ''', (user_id,))
                user_bots = cursor.fetchall()

                bot_ids = [bot[0] for bot in user_bots]

                if bot_ids:
                    placeholders = ','.join(['?' for _ in bot_ids])
                    cursor.execute(f'''
                        SELECT trade_id, bot_id, user_id, symbol, order_type, volume, price,
                               profit, commission, swap, ticket, time_open, time_close,
                               status, created_at, updated_at
                        FROM trades WHERE bot_id IN ({placeholders})
                        ORDER BY COALESCE(time_close, time_open, created_at, updated_at) DESC
                    ''', bot_ids)
                    trade_columns = [description[0] for description in (cursor.description or [])]

                    for row in cursor.fetchall():
                        try:
                            if isinstance(row, sqlite3.Row):
                                trade = dict(row)
                            elif trade_columns:
                                trade = dict(zip(trade_columns, row))
                            else:
                                continue
                            trade['userId'] = user_id
                            bot_id = str(trade.get('bot_id') or '')
                            runtime_bot = runtime_bots_by_id.get(bot_id)
                            trade_ticket = str(trade.get('ticket') or '').strip()

                            if runtime_bot and str(trade.get('status') or '').lower() == 'open' and trade_ticket:
                                runtime_position = None
                                open_positions = runtime_bot.get('open_positions') if isinstance(runtime_bot.get('open_positions'), dict) else {}
                                if trade_ticket in open_positions:
                                    runtime_position = open_positions.get(trade_ticket)
                                else:
                                    runtime_position = next(
                                        (
                                            existing for existing in (runtime_bot.get('tradeHistory') or [])
                                            if str(existing.get('ticket') or '').strip() == trade_ticket
                                            and str(existing.get('status') or '').lower() == 'open'
                                        ),
                                        None,
                                    )

                                if isinstance(runtime_position, dict):
                                    entry_price = _safe_float(
                                        runtime_position.get('entryPrice', runtime_position.get('openPrice', trade.get('price'))),
                                        _safe_float(trade.get('price'), 0.0),
                                    )
                                    current_price = _safe_float(
                                        runtime_position.get('currentPrice', runtime_position.get('marketPrice', runtime_position.get('price_current', entry_price))),
                                        entry_price,
                                    )
                                    trade.update({
                                        'entryPrice': entry_price,
                                        'openPrice': entry_price,
                                        'price': entry_price,
                                        'currentPrice': current_price,
                                        'quoteQty': _safe_float(
                                            runtime_position.get('quoteQty', runtime_position.get('quoteAmount', runtime_position.get('executedQuoteQty', 0.0))),
                                            0.0,
                                        ),
                                        'entryNotional': _safe_float(
                                            runtime_position.get('entryNotional', runtime_position.get('entryValue', 0.0)),
                                            0.0,
                                        ),
                                        'currentNotional': _safe_float(
                                            runtime_position.get('currentNotional', runtime_position.get('currentValue', runtime_position.get('positionValue', 0.0))),
                                            0.0,
                                        ),
                                        'positionValue': _safe_float(
                                            runtime_position.get('positionValue', runtime_position.get('currentNotional', runtime_position.get('currentValue', 0.0))),
                                            0.0,
                                        ),
                                        'displayCurrency': runtime_position.get('displayCurrency') or trade.get('displayCurrency') or 'USDT',
                                        'profit': _resolve_open_position_profit({
                                            **runtime_position,
                                            'entryPrice': entry_price,
                                            'currentPrice': current_price,
                                            'volume': runtime_position.get('volume', trade.get('volume')),
                                            'type': runtime_position.get('type', trade.get('order_type')),
                                        }),
                                        'openTime': runtime_position.get('entryTime') or runtime_position.get('openTime') or trade.get('time_open'),
                                        'time': runtime_position.get('entryTime') or runtime_position.get('time_open') or trade.get('time_open'),
                                    })

                            trades_list.append(trade)
                            trade_key = str(trade.get('ticket') or trade.get('trade_id') or trade.get('tradeId') or trade.get('trade_id') or '')
                            if trade_key:
                                seen_trade_keys.add(trade_key)
                        except Exception as row_error:
                            logger.warning(f"Skipping malformed DB trade row for user {user_id}: {row_error}")

                if not trades_list:
                    logger.info(f"No database trades found for user {user_id}, skipping broker fallback for fast response")
                    return trades_list
            finally:
                conn.close()

        try:
            trades_list = _run_with_sqlite_malformed_retry(
                f"/api/trades for user {user_id}",
                _load_trades_from_sources,
                retries=1,
            )
        except (sqlite3.DatabaseError, sqlite3.OperationalError) as exc:
            if not _is_sqlite_malformed_error(exc):
                raise

            logger.warning(
                f"/api/trades falling back to runtime trade cache for user {user_id}: {exc}"
            )
            trades_list = []
            seen_trade_keys = set()
            for bot_id, runtime_bot in runtime_bots_by_id.items():
                for trade in runtime_bot.get('tradeHistory') or []:
                    if not isinstance(trade, dict):
                        continue

                    runtime_trade = dict(trade)
                    runtime_trade['userId'] = user_id
                    runtime_trade['bot_id'] = runtime_trade.get('bot_id') or bot_id
                    runtime_trade['source'] = runtime_trade.get('source') or 'runtime-cache'

                    trade_key = str(
                        runtime_trade.get('ticket')
                        or runtime_trade.get('trade_id')
                        or runtime_trade.get('tradeId')
                        or runtime_trade.get('timestamp')
                        or ''
                    ).strip()
                    if trade_key and trade_key in seen_trade_keys:
                        continue

                    trades_list.append(runtime_trade)
                    if trade_key:
                        seen_trade_keys.add(trade_key)

            trades_list.sort(key=_trade_history_timestamp_key, reverse=True)
            trades_list = trades_list[:500]

        logger.info(f"Returning {len(trades_list)} trades for user {user_id}")
        return jsonify({
            'success': True,
            'trades': trades_list,
            'timestamp': datetime.now().isoformat(),
        })
    except Exception as e:
        logger.error(f"Error in get_trades_alias for user {request.user_id}: {e}")
        return jsonify({
            'success': False,
            'trades': [],
            'error': str(e),
            'timestamp': datetime.now().isoformat(),
        }), 500


# ==================== ALERTS & RISK-LIMITS ENDPOINTS ====================

def ensure_user_alerts_table(cursor):
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS user_alerts (
            id TEXT PRIMARY KEY,
            user_id TEXT NOT NULL,
            symbol TEXT,
            type TEXT,
            source TEXT,
            price REAL,
            take_profit REAL,
            stop_loss REAL,
            confidence REAL,
            message TEXT,
            priority TEXT,
            requires_action INTEGER DEFAULT 1,
            status TEXT DEFAULT 'pending',
            action_result TEXT,
            created_at TEXT,
            acknowledged_at TEXT,
            metadata TEXT
        )
    ''')


def ensure_user_risk_limits_table(cursor):
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS user_risk_limits (
            user_id TEXT PRIMARY KEY,
            max_contracts_per_symbol INTEGER DEFAULT 5,
            max_daily_loss REAL DEFAULT 500.0,
            max_open_positions INTEGER DEFAULT 10,
            max_exposure_per_symbol REAL DEFAULT 5000.0,
            min_account_equity REAL DEFAULT 100.0,
            updated_at TEXT
        )
    ''')


@app.route('/api/trades/open', methods=['GET'])
@require_session
def get_open_trades():
    """Return only open trades for the authenticated user, formatted for the Flutter Trade model."""
    user_id = request.user_id
    try:
        runtime_bots_by_id = {
            str(bot_id): bot
            for bot_id, bot in active_bots.items()
            if bot.get('user_id') == user_id
        }

        def _load_open_trades():
            trades_list = []
            conn = build_sqlite_connection(wal=False)
            cursor = conn.cursor()
            try:
                cursor.execute('''
                    SELECT bot_id FROM user_bots WHERE user_id = ?
                ''', (user_id,))
                user_bots = cursor.fetchall()

                bot_ids = [bot[0] for bot in user_bots]

                if bot_ids:
                    placeholders = ','.join(['?' for _ in bot_ids])
                    cursor.execute(f'''
                        SELECT trade_id, bot_id, user_id, symbol, order_type, volume, price,
                               profit, commission, swap, ticket, time_open, time_close,
                               status, created_at, updated_at
                        FROM trades WHERE bot_id IN ({placeholders})
                        ORDER BY time_open DESC
                    ''', bot_ids)
                    trade_columns = [desc[0] for desc in (cursor.description or [])]

                    for row in cursor.fetchall():
                        try:
                            if isinstance(row, sqlite3.Row):
                                trade = dict(row)
                            elif trade_columns:
                                trade = dict(zip(trade_columns, row))
                            else:
                                continue

                            status_lower = str(trade.get('status', '')).lower()
                            if status_lower not in ('open', 'pending'):
                                continue

                            bot_id = str(trade.get('bot_id') or '')
                            runtime_bot = runtime_bots_by_id.get(bot_id)
                            trade_ticket = str(trade.get('ticket') or '').strip()

                            if runtime_bot and trade_ticket:
                                open_positions = runtime_bot.get('open_positions') if isinstance(runtime_bot.get('open_positions'), dict) else {}
                                runtime_position = open_positions.get(trade_ticket)
                                if not runtime_position:
                                    runtime_position = next(
                                        (
                                            existing for existing in (runtime_bot.get('tradeHistory') or [])
                                            if str(existing.get('ticket') or '').strip() == trade_ticket
                                            and str(existing.get('status') or '').lower() == 'open'
                                        ),
                                        None,
                                    )

                                if isinstance(runtime_position, dict):
                                    entry_price = _safe_float(
                                        runtime_position.get('entryPrice', runtime_position.get('openPrice', trade.get('price'))),
                                        _safe_float(trade.get('price'), 0.0),
                                    )
                                    current_price = _safe_float(
                                        runtime_position.get('currentPrice', runtime_position.get('marketPrice', entry_price)),
                                        entry_price,
                                    )
                                    trade.update({
                                        'entryPrice': entry_price,
                                        'openPrice': entry_price,
                                        'price': entry_price,
                                        'entryPrice': entry_price,
                                        'currentPrice': current_price,
                                        'quantity': _safe_float(trade.get('volume', 0), 0.0),
                                        'volume': _safe_float(trade.get('volume', 0), 0.0),
                                        'symbol': runtime_position.get('symbol', trade.get('symbol', '')),
                                        'type': 'buy' if str(runtime_position.get('type', '')).lower() in ('0', 'buy', '1') else 'sell',
                                        'status': 'open',
                                        'openedAt': runtime_position.get('entryTime') or runtime_position.get('openTime') or trade.get('time_open'),
                                        'time_open': runtime_position.get('entryTime') or runtime_position.get('openTime') or trade.get('time_open'),
                                        'profit': _safe_float(runtime_position.get('profit', 0), 0.0),
                                        'profitPercentage': _safe_float(runtime_position.get('profitPercent', 0), 0.0),
                                        'currency': runtime_position.get('displayCurrency') or trade.get('displayCurrency') or 'USDT',
                                        'stopLoss': _safe_float(runtime_position.get('stopLoss', 0), 0.0),
                                        'takeProfit': _safe_float(runtime_position.get('takeProfit', 0), 0.0),
                                    })

                            trade['userId'] = user_id
                            trade['source'] = 'live-broker' if runtime_bot else 'database'
                            trades_list.append(trade)
                        except Exception:
                            continue
            finally:
                conn.close()

            if not trades_list:
                cached_positions = get_cached_mt5_positions(user_id)
                for pos in cached_positions:
                    trade_ticket = str(pos.get('ticket') or pos.get('position') or pos.get('positionId') or '').strip()
                    if not trade_ticket:
                        continue
                    trade = {
                        'trade_id': trade_ticket,
                        'bot_id': pos.get('bot_id', ''),
                        'user_id': user_id,
                        'symbol': pos.get('symbol', pos.get('instrument', '')),
                        'order_type': 'buy' if str(pos.get('type', pos.get('direction', ''))).lower() in ('0', 'buy', '1', 'long') else 'sell',
                        'volume': _safe_float(pos.get('volume', pos.get('size', 0)), 0.0),
                        'price': _safe_float(pos.get('entryPrice', pos.get('openPrice', pos.get('price', 0))), 0.0),
                        'profit': _safe_float(pos.get('profit', pos.get('pnl', pos.get('profit_loss', pos.get('unrealizedPL', 0)))), 0.0),
                        'commission': _safe_float(pos.get('commission', 0), 0.0),
                        'swap': _safe_float(pos.get('swap', 0), 0.0),
                        'ticket': trade_ticket,
                        'time_open': pos.get('openTime', pos.get('entryTime', '')),
                        'time_close': None,
                        'status': 'open',
                        'created_at': pos.get('openTime', pos.get('entryTime', datetime.now().isoformat())),
                        'updated_at': datetime.now().isoformat(),
                        'userId': user_id,
                        'source': 'mt5-cached',
                        'currentPrice': _safe_float(pos.get('currentPrice', pos.get('level', pos.get('openPrice', pos.get('price', 0)))), 0.0),
                        'currency': pos.get('displayCurrency', pos.get('currency', 'USD')),
                        'entryPrice': _safe_float(pos.get('entryPrice', pos.get('openPrice', pos.get('price', 0))), 0.0),
                        'stopLoss': _safe_float(pos.get('stopLoss', 0), 0.0),
                        'takeProfit': _safe_float(pos.get('takeProfit', 0), 0.0),
                        'profitPercentage': _safe_float(pos.get('profitPercent', pos.get('pnlPercentage', pos.get('roiPct', 0))), 0.0),
                        'accountKey': pos.get('accountKey', ''),
                    }
                    trades_list.append(trade)
            return trades_list

        try:
            trades_list = _run_with_sqlite_malformed_retry(
                f"/api/trades/open for user {user_id}",
                _load_open_trades,
                retries=1,
            )
        except (sqlite3.DatabaseError, sqlite3.OperationalError) as exc:
            if not _is_sqlite_malformed_error(exc):
                raise
            trades_list = []
            for bot_id, runtime_bot in runtime_bots_by_id.items():
                for trade in runtime_bot.get('tradeHistory') or []:
                    if not isinstance(trade, dict):
                        continue
                    status_lower = str(trade.get('status', '')).lower()
                    if status_lower not in ('open', 'pending'):
                        continue
                    runtime_trade = dict(trade)
                    runtime_trade['userId'] = user_id
                    runtime_trade['bot_id'] = runtime_trade.get('bot_id') or bot_id
                    runtime_trade['source'] = runtime_trade.get('source') or 'runtime-cache'
                    runtime_trade['symbol'] = runtime_trade.get('symbol', '')
                    runtime_trade['type'] = str(runtime_trade.get('type', '')).lower() in ('0', 'buy', '1') and 'buy' or 'sell'
                    runtime_trade['status'] = 'open'
                    runtime_trade['openedAt'] = runtime_trade.get('openedAt', runtime_trade.get('time', ''))
                    runtime_trade['quantity'] = _safe_float(runtime_trade.get('volume', runtime_trade.get('size', 0)), 0.0)
                    runtime_trade['profit'] = _safe_float(runtime_trade.get('profit', 0), 0.0)
                    runtime_trade['currency'] = runtime_trade.get('displayCurrency', 'USDT')
                    runtime_trade['stopLoss'] = _safe_float(runtime_trade.get('stopLoss', 0), 0.0)
                    runtime_trade['takeProfit'] = _safe_float(runtime_trade.get('takeProfit', 0), 0.0)
                    trades_list.append(runtime_trade)

        logger.info(f"Returning {len(trades_list)} open trades for user {user_id}")
        return jsonify({
            'success': True,
            'trades': trades_list,
            'timestamp': datetime.now().isoformat(),
        })
    except Exception as e:
        logger.error(f"Error in get_open_trades for user {user_id}: {e}")
        return jsonify({
            'success': False,
            'trades': [],
            'error': str(e),
            'timestamp': datetime.now().isoformat(),
        }), 500


@app.route('/api/alerts', methods=['POST'])
@require_session
def create_alert():
    """Receive a trading alert from the Flutter app and persist it."""
    user_id = request.user_id
    try:
        data = request.get_json(silent=True) or {}
        if not data:
            return jsonify({'success': False, 'error': 'No alert data provided'}), 400

        alert_id = data.get('id', str(uuid.uuid4()))
        signal = data.get('signal', {}) if isinstance(data.get('signal'), dict) else {}

        conn = get_db_connection()
        cursor = conn.cursor()
        ensure_user_alerts_table(cursor)

        metadata_json = json.dumps(data.get('metadata', {})) if data.get('metadata') else None

        cursor.execute('''
            INSERT OR REPLACE INTO user_alerts
            (id, user_id, symbol, type, source, price, take_profit, stop_loss,
             confidence, message, priority, requires_action, status, action_result,
             created_at, acknowledged_at, metadata)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        ''', (
            alert_id,
            user_id,
            signal.get('symbol', data.get('symbol', '')),
            signal.get('type', data.get('type', '')),
            signal.get('source', data.get('source', 'technical')),
            _safe_float(data.get('price', signal.get('price', 0)), 0.0),
            _safe_float(data.get('takeProfit', signal.get('takeProfit', 0)), 0.0) if data.get('takeProfit') or signal.get('takeProfit') else None,
            _safe_float(data.get('stopLoss', signal.get('stopLoss', 0)), 0.0) if data.get('stopLoss') or signal.get('stopLoss') else None,
            _safe_float(data.get('confidence', signal.get('confidence', 0)), 0.0) if data.get('confidence') or signal.get('confidence') else None,
            data.get('message'),
            data.get('priority', 'normal'),
            1 if data.get('requiresAction', True) else 0,
            data.get('status', 'pending'),
            json.dumps(data.get('actionResult')) if data.get('actionResult') else None,
            data.get('createdAt', data.get('timestamp', datetime.now().isoformat())),
            data.get('acknowledgedAt'),
            metadata_json,
        ))
        conn.commit()
        conn.close()

        logger.info(f"Alert {alert_id} stored for user {user_id} — {signal.get('symbol', data.get('symbol', ''))}")
        return jsonify({
            'success': True,
            'message': 'Alert stored',
            'alertId': alert_id,
        }), 200
    except Exception as e:
        logger.error(f"Error creating alert: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/alerts', methods=['GET'])
@require_session
def get_alerts():
    """Return recent alerts for the authenticated user."""
    user_id = request.user_id
    try:
        limit = request.args.get('limit', default=50, type=int)

        conn = get_db_connection()
        cursor = conn.cursor()
        ensure_user_alerts_table(cursor)

        cursor.execute('''
            SELECT id, user_id, symbol, type, source, price, take_profit, stop_loss,
                   confidence, message, priority, requires_action, status, action_result,
                   created_at, acknowledged_at, metadata
            FROM user_alerts
            WHERE user_id = ?
            ORDER BY created_at DESC
            LIMIT ?
        ''', (user_id, limit))
        rows = cursor.fetchall()
        conn.close()

        alerts = []
        for row in rows:
            if isinstance(row, sqlite3.Row):
                r = dict(row)
            else:
                cols = [desc[0] for desc in cursor.description]
                r = dict(zip(cols, row))
            signal_data = {
                'symbol': r.get('symbol', ''),
                'type': r.get('type', 'buy'),
                'source': r.get('source', 'technical'),
                'price': r.get('price', 0),
                'takeProfit': r.get('take_profit'),
                'stopLoss': r.get('stop_loss'),
                'confidence': r.get('confidence'),
            }
            if r.get('metadata'):
                try:
                    signal_data['metadata'] = json.loads(r['metadata'])
                except (json.JSONDecodeError, TypeError):
                    signal_data['metadata'] = None

            alerts.append({
                'id': r.get('id'),
                'signal': signal_data,
                'status': r.get('status', 'pending'),
                'createdAt': r.get('created_at'),
                'acknowledgedAt': r.get('acknowledged_at'),
                'message': r.get('message'),
                'priority': r.get('priority', 'normal'),
                'requiresAction': bool(r.get('requires_action', 1)),
                'actionResult': json.loads(r['action_result']) if r.get('action_result') else None,
            })

        return jsonify({
            'success': True,
            'alerts': alerts,
            'count': len(alerts),
        }), 200
    except Exception as e:
        logger.error(f"Error fetching alerts for user {user_id}: {e}")
        return jsonify({'success': False, 'error': str(e), 'alerts': []}), 500


