@app.route('/api/account/detailed', methods=['GET'])
@require_session
def get_account_detailed():
    """Get COMPREHENSIVE account data from ANY broker (Exness, Binance, FXCM, OANDA) with all metrics"""
    user_id = request.user_id
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        requested_mode = str(request.args.get('mode') or '').strip().upper()
        broker_filter = request.args.get('broker', default='', type=str).strip()
        preferred_mode = requested_mode if requested_mode in ['LIVE', 'DEMO'] else get_user_trading_mode_value(user_id)
        desired_live = 1 if preferred_mode == 'LIVE' else 0
        user_mode_preferences = _get_user_trading_mode_preferences(cursor, user_id)
        preferred_live_account = user_mode_preferences.get('live_account', '') if desired_live else ''
        preferred_live_server = user_mode_preferences.get('live_server', '') if desired_live else ''
        
        # Query all active credentials, optionally filtered by broker
        if broker_filter:
            cursor.execute('''
                SELECT credential_id, broker_name, account_number, password, server, is_live, username,
                       cached_balance, cached_equity, cached_margin_free, cached_margin,
                       cached_margin_level, cached_profit, account_currency, last_update, updated_at, api_key
                FROM broker_credentials
                WHERE user_id = ? AND is_active = 1 AND broker_name = ?
                ORDER BY broker_name, COALESCE(updated_at, last_update, '') DESC,
                         credential_id DESC
                LIMIT 10
            ''', (user_id, broker_filter))
        else:
            cursor.execute('''
                SELECT credential_id, broker_name, account_number, password, server, is_live, username,
                       cached_balance, cached_equity, cached_margin_free, cached_margin,
                       cached_margin_level, cached_profit, account_currency, last_update, updated_at, api_key
                FROM broker_credentials
                WHERE user_id = ? AND is_active = 1
                ORDER BY broker_name, COALESCE(updated_at, last_update, '') DESC,
                         credential_id DESC
                LIMIT 10
            ''', (user_id,))
        
        creds = [dict(row) for row in cursor.fetchall()]
        creds, duplicate_credential_ids = dedupe_active_broker_credentials(creds)
        if creds:
            def _credential_priority(row: Dict[str, Any]) -> Tuple[int, int, int, str, str]:
                row_broker = canonicalize_broker_name(row.get('broker_name'))
                row_account = str(row.get('account_number') or '').strip()
                row_server = str(row.get('server') or '').strip()
                row_is_live = int(normalize_mt5_is_live_flag(row_broker, row.get('is_live'), row.get('server')))
                return (
                    1 if row_is_live == desired_live else 0,
                    1 if preferred_live_account and row_account == preferred_live_account else 0,
                    1 if preferred_live_server and row_server == preferred_live_server else 0,
                    str(row.get('updated_at') or row.get('last_update') or ''),
                    str(row.get('credential_id') or ''),
                )

            creds.sort(key=_credential_priority, reverse=True)
        if duplicate_credential_ids:
            logger.info(
                f"Detected {len(duplicate_credential_ids)} duplicate/incomplete broker credential(s) for user {user_id} while loading account details; leaving database unchanged during polling."
            )
        conn.close()
        
        if not creds:
            return jsonify({
                'success': False,
                'error': f'No broker credentials found'
            }), 404

        accounts_data = []
        
        # Fetch account details from each broker
        for cred in creds:
            broker_name = canonicalize_broker_name(cred.get('broker_name'))
            account_num = cred['account_number']
            account_info = None
            skip_cached_snapshot = False
            identity_fields = _build_account_identity_fields(
                broker_name=broker_name,
                account_number=account_num,
                server=cred.get('server'),
                is_live=cred.get('is_live'),
                credential_id=cred['credential_id'],
                user_id=user_id,
            )
            
            try:
                # ==================== EXNESS / MT5 ====================
                if broker_name in ['Exness', 'MetaTrader5', 'PXBT']:
                    effective_is_live = int(normalize_mt5_is_live_flag(broker_name, cred.get('is_live'), cred.get('server')))
                    if effective_is_live == desired_live:
                        account_info = read_active_mt5_account_snapshot(
                            broker_name,
                            account_num,
                            credential_id=cred['credential_id'],
                            user_id=user_id,
                        )
                        if account_info:
                            account_info['broker'] = broker_name
                            account_info['credential_id'] = cred['credential_id']
                            logger.info(f"✅ Fetched account details from active MT5 session for {broker_name} {account_num}")
                        else:
                            logger.info(
                                f"ℹ️ Account details: skipping MT5 session switch for {broker_name} {account_num}; using cache if available"
                            )
                
                # ==================== BINANCE ====================
                elif broker_name == 'Binance':
                    cache_age_seconds = _cache_snapshot_age_seconds(cred.get('last_update') or cred.get('updated_at'))
                    cached_balance = _safe_float(cred.get('cached_balance'))
                    resolved_market = _resolve_binance_market_for_credential_usage(
                        credential_row=cred,
                        credential_id=cred.get('credential_id'),
                        user_id=user_id,
                    )
                    binance_display_currency = _resolve_binance_display_currency(
                        fallback_currency=cred.get('account_currency') or 'USDT',
                        market=resolved_market,
                    )
                    if cache_age_seconds is not None and cache_age_seconds < 90 and cached_balance > 0:
                        account_info = {
                            'account_id': account_num,
                            'accountNumber': account_num,
                            'balance': cached_balance,
                            'equity': _safe_float(cred.get('cached_equity'), cached_balance),
                            'marginFree': _safe_float(cred.get('cached_margin_free')),
                            'margin': _safe_float(cred.get('cached_margin')),
                            'margin_level': _safe_float(cred.get('cached_margin_level')),
                            'profit': _safe_float(cred.get('cached_profit')),
                            'currency': binance_display_currency,
                            'broker': 'Binance',
                            'credential_id': cred['credential_id'],
                            'dataSource': 'cached',
                            'market': resolved_market,
                        }
                        logger.info(
                            f"✅ Account details: serving cached Binance snapshot for {account_num} "
                            f"({cache_age_seconds:.0f}s old)"
                        )
                    else:
                        binance_conn = BinanceConnection({
                            'api_key': cred.get('api_key'),
                            'api_secret': cred['password'],
                            'account_number': account_num,
                            'server': resolved_market,
                            'market': resolved_market,
                            'is_live': bool(cred['is_live']),
                        })
                        if binance_conn.connect():
                            account_info = binance_conn.get_account_info()
                            if account_info:
                                resolved_currency = _resolve_binance_display_currency(
                                    fallback_currency=account_info.get('currency', binance_display_currency),
                                    market=resolved_market,
                                )
                                account_info['currency'] = resolved_currency
                                account_info['displayCurrency'] = resolved_currency
                                account_info['broker'] = 'Binance'
                                account_info['credential_id'] = cred['credential_id']
                                logger.info(f"✅ Fetched account details from Binance {account_num}")
                            binance_conn.disconnect()
                
                # ==================== FXCM ====================
                elif broker_name == 'FXCM':
                    cached_fxcm_snapshot = _get_cached_fxcm_endpoint_snapshot(cred['credential_id'])
                    if cached_fxcm_snapshot and isinstance(cached_fxcm_snapshot.get('accountInfo'), dict) and cached_fxcm_snapshot['accountInfo']:
                        account_info = dict(cached_fxcm_snapshot['accountInfo'])
                        account_info['broker'] = 'FXCM'
                        account_info['credential_id'] = cred['credential_id']
                        account_info['dataSource'] = cached_fxcm_snapshot.get('dataSource', account_info.get('dataSource', 'cached-live'))
                    else:
                        fxcm_conn = FXCMConnection({
                            'api_key': cred.get('api_key'),
                            'username': cred.get('username'),
                            'password': cred.get('password'),
                            'account_number': account_num,
                            'server': cred.get('server'),
                            'connection': 'Real' if bool(cred['is_live']) else 'Demo',
                            'is_live': bool(cred['is_live']),
                        })
                        if fxcm_conn.connect():
                            account_info = fxcm_conn.get_account_info()
                            if account_info:
                                account_info['broker'] = 'FXCM'
                                account_info['credential_id'] = cred['credential_id']
                                _store_fxcm_endpoint_snapshot(
                                    cred['credential_id'],
                                    account_info=account_info,
                                    data_source=account_info.get('dataSource', 'live') if isinstance(account_info, dict) else 'live',
                                )
                                logger.info(f"✅ Fetched account details from FXCM {account_num}")
                            fxcm_conn.disconnect()
                        else:
                            logger.warning(
                                f"⚠️ FXCM account fetch failed for {account_num}: {fxcm_conn.last_error or 'Unknown FXCM error'}"
                            )
                
                # ==================== OANDA ====================
                elif broker_name == 'OANDA':
                    oanda_conn = OANDAConnection({
                        'api_key': cred.get('api_key'),
                        'account_number': account_num,
                        'is_live': bool(cred['is_live']),
                    })
                    if oanda_conn.connect():
                        account_info = oanda_conn.get_account_info()
                        if account_info:
                            account_info['broker'] = 'OANDA'
                            account_info['credential_id'] = cred['credential_id']
                            logger.info(f"✅ Fetched account details from OANDA {account_num}")
                        oanda_conn.disconnect()
                
                # Backup to cached data if live fetch failed
                if not account_info and not skip_cached_snapshot:
                    cached_balance = float(cred.get('cached_balance') or 0)
                    if cached_balance > 0 or cred.get('cached_equity'):
                        resolved_cached_currency = (
                            _resolve_binance_display_currency(
                                fallback_currency=cred.get('account_currency') or 'USDT',
                                market=cred.get('server'),
                            )
                            if broker_name == 'Binance'
                            else str(cred.get('account_currency') or 'USD').upper()
                        )
                        account_info = {
                            'account_id': account_num,
                            'accountNumber': account_num,
                            'balance': cached_balance,
                            'equity': float(cred.get('cached_equity') or cached_balance),
                            'marginFree': float(cred.get('cached_margin_free') or 0),
                            'margin': float(cred.get('cached_margin') or 0),
                            'margin_level': float(cred.get('cached_margin_level') or 0),
                            'profit': float(cred.get('cached_profit') or 0),
                            'currency': resolved_cached_currency,
                            'broker': broker_name,
                            'credential_id': cred['credential_id'],
                            'dataSource': 'cached',
                        }
                
                if account_info and account_info.get('dataSource') != 'cached':
                    persist_account_snapshot(
                        broker_name,
                        account_num,
                        account_info,
                        credential_id=cred.get('credential_id'),
                        user_id=user_id,
                    )
                if account_info:
                    account_info['accountNumber'] = str(
                        account_info.get('accountNumber') or account_info.get('account_id') or account_num
                    ).strip()
                    account_info['credentialId'] = cred['credential_id']
                    account_info.update(identity_fields)
                    accounts_data.append(account_info)
                    
            except Exception as e:
                logger.warning(f"⚠️ Could not fetch account details from {broker_name} {account_num}: {e}")
                continue

        if not accounts_data:
            # Return first cached option
            if creds:
                cred = creds[0]
                cached_balance = float(cred.get('cached_balance') or 0)
                identity_fields = _build_account_identity_fields(
                    broker_name=cred['broker_name'],
                    account_number=cred['account_number'],
                    server=cred.get('server'),
                    is_live=cred.get('is_live'),
                    credential_id=cred['credential_id'],
                    user_id=user_id,
                )
                return jsonify({
                    'success': True,
                    'accountNumber': cred['account_number'],
                    'balance': cached_balance,
                    'equity': float(cred.get('cached_equity') or cached_balance),
                    'marginFree': float(cred.get('cached_margin_free') or 0),
                    'margin': float(cred.get('cached_margin') or 0),
                    'margin_level': float(cred.get('cached_margin_level') or 0),
                    'profit': float(cred.get('cached_profit') or 0),
                    'currency': (
                        _resolve_binance_display_currency(
                            fallback_currency=cred.get('account_currency') or 'USDT',
                            market=cred.get('server'),
                        )
                        if canonicalize_broker_name(cred['broker_name']) == 'Binance'
                        else str(cred.get('account_currency') or 'USD').upper()
                    ),
                    'broker': cred['broker_name'],
                    'dataSource': 'cached',
                    'credentialId': cred['credential_id'],
                    **identity_fields,
                }), 200
            else:
                return jsonify({'success': False, 'error': 'No account data available'}), 404

        accounts_data.sort(
            key=lambda account: (
                1 if int(normalize_mt5_is_live_flag(
                    canonicalize_broker_name(account.get('broker') or account.get('brokerName') or ''),
                    account.get('isLive', account.get('is_live')),
                    account.get('server'),
                )) == desired_live else 0,
                1 if preferred_live_account and str(account.get('accountNumber') or account.get('account_id') or '').strip() == preferred_live_account else 0,
                1 if preferred_live_server and str(account.get('server') or '').strip() == preferred_live_server else 0,
            ),
            reverse=True,
        )

        # Return all accounts or the first one depending on usage
        primary_account = accounts_data[0]
        return jsonify({
            'success': True,
            'accountNumber': primary_account.get('accountNumber', primary_account.get('account_id')),
            'balance': primary_account.get('balance', 0),
            'equity': primary_account.get('equity', 0),
            'marginFree': primary_account.get('marginFree', 0),
            'margin': primary_account.get('margin', 0),
            'margin_level': primary_account.get('margin_level', 0),
            'profit': primary_account.get('profit', 0),
            'currency': primary_account.get('currency', 'USD'),
            'broker': primary_account.get('broker'),
            'dataSource': primary_account.get('dataSource', 'live'),
            'credentialId': primary_account.get('credentialId', primary_account.get('credential_id')),
            'market': primary_account.get('market', ''),
            'server': primary_account.get('server', ''),
            'brokerDisplay': primary_account.get('brokerDisplay', primary_account.get('broker')),
            'accountDisplay': primary_account.get('accountDisplay', primary_account.get('accountNumber', primary_account.get('account_id'))),
            'accountKey': primary_account.get('accountKey', ''),
            'modeLabel': primary_account.get('modeLabel', ''),
            'allAccounts': accounts_data,  # Include all accounts for dashboard display
        }), 200
        
    except Exception as e:
        logger.error(f"Error getting account detailed: {e}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


# Last-known open positions per credential. Populated whenever a live broker
# connection successfully returns positions, and served as a fallback when the
# live connection is unavailable (e.g. the MT5 terminal is not running on the
# VPS). This keeps manually-opened positions visible in the app instead of them
# vanishing the moment the terminal session drops.
_MT5_POSITIONS_CACHE: Dict[str, Dict[str, Any]] = {}
_MT5_POSITIONS_CACHE_LOCK = threading.Lock()


def _cache_positions_for_credential(credential_id: str, broker_positions: List[Dict[str, Any]]) -> None:
    try:
        normalized = [
            {
                'symbol': p.get('symbol') or p.get('instrument'),
                'type': p.get('type') or p.get('direction'),
                'volume': p.get('volume') or p.get('size'),
                'openPrice': p.get('openPrice') or p.get('level'),
                'price_current': p.get('price_current') or p.get('currentPrice'),
                'profit': p.get('profit') or p.get('pnl') or p.get('profit_loss') or p.get('unrealizedPL'),
                'ticket': p.get('ticket') or p.get('deal_id') or p.get('trade_id'),
                'time': p.get('time') or p.get('openTime'),
            }
            for p in (broker_positions or [])
        ]
        with _MT5_POSITIONS_CACHE_LOCK:
            _MT5_POSITIONS_CACHE[str(credential_id)] = {
                'positions': normalized,
                'ts': time.time(),
            }
    except Exception as exc:
        logger.warning(f"Could not cache positions for {credential_id}: {exc}")


def _cached_positions_for_credential(credential_id: str) -> List[Dict[str, Any]]:
    with _MT5_POSITIONS_CACHE_LOCK:
        entry = _MT5_POSITIONS_CACHE.get(str(credential_id))
    if not entry:
        return []
    return list(entry.get('positions') or [])


def _append_cached_positions(positions: List[Dict[str, Any]], cred: Dict[str, Any],
                              broker_name: str, identity_fields: Dict[str, Any]) -> None:
    """Append last-known positions from cache when the live connection is down."""
    cached = _cached_positions_for_credential(cred['credential_id'])
    if not cached:
        return
    logger.info(
        f"Serving {len(cached)} cached position(s) for {broker_name} "
        f"{cred['account_number']} (live terminal unavailable)"
    )
    for position in cached:
        pnl = position.get('profit') or position.get('pnl') or position.get('unrealizedPL') or 0
        positions.append({
            'credentialId': cred['credential_id'],
            'broker': broker_name,
            'accountNumber': cred['account_number'],
            'market': identity_fields.get('market', ''),
            'server': identity_fields.get('server', ''),
            'brokerDisplay': identity_fields.get('brokerDisplay', broker_name),
            'accountDisplay': identity_fields.get('accountDisplay', cred['account_number']),
            'accountKey': identity_fields.get('accountKey', ''),
            'modeLabel': identity_fields.get('modeLabel', ''),
            'positionId': str(position.get('ticket') or position.get('deal_id') or position.get('trade_id') or ''),
            'instrument': position.get('symbol') or position.get('instrument') or '',
            'direction': position.get('type') or position.get('direction') or '',
            'size': float(position.get('volume', position.get('size', 0)) or 0),
            'level': float(position.get('openPrice', position.get('level', 0)) or 0),
            'unrealizedPL': float(pnl or 0),
            'dataSource': 'cached',
            'raw': position,
        })


@app.route('/api/positions/detailed', methods=['GET'])
@require_session
def get_positions_detailed():
    """Get ALL open positions with DETAILED metrics"""
    user_id = request.user_id
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        requested_mode = str(request.args.get('mode') or '').strip().upper()
        preferred_mode = requested_mode if requested_mode in ['LIVE', 'DEMO'] else get_user_trading_mode_value(user_id)
        desired_live = 1 if preferred_mode == 'LIVE' else 0
        requested_credential_id = str(request.args.get('credential_id') or '').strip()
        requested_account_number = str(request.args.get('account_number') or request.args.get('account') or '').strip()

        broker_filter = canonicalize_broker_name(request.args.get('broker', default='', type=str).strip())
        query = '''
            SELECT credential_id, broker_name, account_number, password, server, is_live, api_key, username
            FROM broker_credentials 
            WHERE user_id = ? AND is_active = 1
        '''
        params = [user_id]
        if broker_filter:
            query += ' AND UPPER(broker_name) = ?'
            params.append(broker_filter)
        query += '''
            ORDER BY broker_name, credential_id DESC
        '''
        cursor.execute(query, params)

        rows = [dict(row) for row in cursor.fetchall()]
        rows, duplicate_credential_ids = dedupe_active_broker_credentials(rows)
        rows = filter_mt5_credentials_for_active_session(
            rows,
            requested_credential_id=requested_credential_id,
            requested_account_number=requested_account_number,
        )
        if duplicate_credential_ids:
            logger.info(
                f"Detected {len(duplicate_credential_ids)} duplicate/incomplete broker credential(s) for user {user_id} while loading detailed positions; leaving database unchanged during polling."
            )
        conn.close()

        if not rows:
            return jsonify({
                'success': False,
                'positions': [],
                'totalCount': 0,
            })

        positions = []
        warnings_list = []

        for cred in rows:
            broker_name = canonicalize_broker_name(cred.get('broker_name'))
            effective_is_live = int(normalize_mt5_is_live_flag(broker_name, cred.get('is_live'), cred.get('server')))
            # NOTE: Previously this skipped credentials whose is_live flag did not
            # match the requested mode. That hid real open positions (e.g. a LIVE
            # Binance account when the app trading_mode pref was DEMO), so the
            # Trades screen disagreed with the broker terminal. Each credential is
            # connected to its own account individually, so we now include all
            # active credentials and only use the mode as a soft preference.
            if effective_is_live != desired_live:
                logger.info(
                    f"Mode mismatch for {broker_name} {cred['account_number']} "
                    f"(credential is_live={effective_is_live}, requested mode={desired_live}); "
                    f"still including its open positions in the detailed view"
                )

            identity_fields = _build_account_identity_fields(
                broker_name=broker_name,
                account_number=cred['account_number'],
                server=cred.get('server'),
                is_live=cred.get('is_live'),
                credential_id=cred['credential_id'],
                user_id=user_id,
                bot_id=f'positions-detailed:{cred["credential_id"]}',
            )

            conn_label, broker_conn = get_broker_connection(
                cred['credential_id'],
                user_id,
                bot_id=f'positions-detailed:{cred["credential_id"]}',
            )
            if not broker_conn:
                warnings_list.append(f"{broker_name} {cred['account_number']}: {conn_label}")
                # Fall back to last-known positions so manually-opened trades
                # remain visible when the live terminal session is down.
                _append_cached_positions(positions, cred, broker_name, identity_fields)
                continue

            try:
                broker_positions = broker_conn.get_positions() or []
                if broker_positions:
                    _cache_positions_for_credential(cred['credential_id'], broker_positions)
                for position in broker_positions:
                    pnl = position.get('pnl', position.get('profit_loss', position.get('unrealizedPL', 0)))
                    positions.append({
                        'credentialId': cred['credential_id'],
                        'broker': broker_name,
                        'accountNumber': cred['account_number'],
                        'market': identity_fields.get('market', ''),
                        'server': identity_fields.get('server', ''),
                        'brokerDisplay': identity_fields.get('brokerDisplay', broker_name),
                        'accountDisplay': identity_fields.get('accountDisplay', cred['account_number']),
                        'accountKey': identity_fields.get('accountKey', ''),
                        'modeLabel': identity_fields.get('modeLabel', ''),
                        'positionId': str(position.get('deal_id') or position.get('trade_id') or position.get('ticket') or ''),
                        'instrument': position.get('symbol') or position.get('instrument') or '',
                        'direction': position.get('type') or position.get('direction') or '',
                        'size': float(position.get('size', position.get('volume', 0)) or 0),
                        'level': float(position.get('level', position.get('openPrice', 0)) or 0),
                        'unrealizedPL': float(pnl or 0),
                        'raw': position,
                    })
            except Exception as e:
                warnings_list.append(f"{broker_name} {cred['account_number']}: {e}")
                _append_cached_positions(positions, cred, broker_name, identity_fields)
            finally:
                if hasattr(broker_conn, 'disconnect'):
                    try:
                        broker_conn.disconnect()
                    except Exception:
                        pass

        total_pl = sum(float(p.get('unrealizedPL', 0) or 0) for p in positions)

        return jsonify({
            'success': True,
            'positions': positions,
            'totalCount': len(positions),
            'totalPL': total_pl,
            'dataSource': 'multi-broker',
            'warnings': warnings_list,
        })
            
    except Exception as e:
        logger.error(f"Error getting detailed positions: {e}")
        return jsonify({
            'success': False,
            'error': str(e),
            'positions': []
        }), 500


@app.route('/api/unified/portfolio', methods=['GET'])
@require_session
def get_unified_portfolio():
    """Return unified portfolio totals and per-broker cards for the authenticated user."""
    user_id = request.user_id

    try:
        requested_mode = str(request.args.get('mode') or '').strip().upper()
        preferred_mode = requested_mode if requested_mode in ['LIVE', 'DEMO'] else get_user_trading_mode_value(user_id)
        desired_live = 1 if preferred_mode == 'LIVE' else 0
        requested_credential_id = str(request.args.get('credential_id') or '').strip()
        requested_account_number = str(request.args.get('account_number') or request.args.get('account') or '').strip()

        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('''
            SELECT credential_id, broker_name, account_number, is_live, server,
                   cached_balance, cached_equity, cached_margin_free, cached_profit
            FROM broker_credentials
            WHERE user_id = ? AND is_active = 1
            ORDER BY broker_name, credential_id DESC
        ''', (user_id,))
        credentials = [dict(row) for row in cursor.fetchall()]
        credentials, duplicate_credential_ids = dedupe_active_broker_credentials(credentials)
        credentials = filter_mt5_credentials_for_active_session(
            credentials,
            requested_credential_id=requested_credential_id,
            requested_account_number=requested_account_number,
        )
        conn.close()

        if duplicate_credential_ids:
            logger.info(
                f"Detected {len(duplicate_credential_ids)} duplicate/incomplete broker credential(s) for user {user_id} while building unified portfolio; leaving database unchanged during polling."
            )

        portfolio = {
            'total_balance': 0.0,
            'total_available': 0.0,
            'total_pnl': 0.0,
            'total_positions': 0,
            'connected_brokers': 0,
            'total_brokers': 0,
            'mode': preferred_mode,
        }
        brokers = {}

        for cred in credentials:
            broker_name = canonicalize_broker_name(cred.get('broker_name'))
            effective_is_live = int(normalize_mt5_is_live_flag(broker_name, cred.get('is_live'), cred.get('server')))
            if effective_is_live != desired_live:
                continue

            broker_card = {
                'connected': False,
                'balance': float(cred.get('cached_balance') or 0),
                'available': float(cred.get('cached_margin_free') or 0),
                'pnl': float(cred.get('cached_profit') or 0),
                'positions': 0,
                'accountNumber': cred.get('account_number'),
                'mode': 'Live' if effective_is_live else 'Demo',
            }

            conn_label, broker_conn = get_broker_connection(
                cred['credential_id'],
                user_id,
                bot_id=f'unified-portfolio:{cred["credential_id"]}',
            )
            if broker_conn:
                try:
                    account_info = broker_conn.get_account_info() or {}
                    positions = broker_conn.get_positions() or []
                    broker_card.update({
                        'connected': True,
                        'balance': float(account_info.get('balance', broker_card['balance']) or broker_card['balance']),
                        'available': float(account_info.get('marginFree', account_info.get('margin_free', broker_card['available'])) or broker_card['available']),
                        'pnl': float(account_info.get('profit', account_info.get('total_pl', broker_card['pnl'])) or broker_card['pnl']),
                        'positions': len(positions),
                    })
                except Exception as e:
                    broker_card['error'] = str(e)
                finally:
                    if hasattr(broker_conn, 'disconnect'):
                        try:
                            broker_conn.disconnect()
                        except Exception:
                            pass
            else:
                broker_card['error'] = conn_label or 'Connection unavailable'

            aggregate_card = brokers.setdefault(broker_name, {
                'connected': False,
                'balance': 0.0,
                'available': 0.0,
                'pnl': 0.0,
                'positions': 0,
                'accountNumber': '',
                'accountNumbers': [],
                'accounts': [],
                'mode': 'Live' if effective_is_live else 'Demo',
            })
            account_number = str(broker_card.get('accountNumber') or '')
            aggregate_card['connected'] = bool(aggregate_card['connected'] or broker_card['connected'])
            aggregate_card['balance'] += float(broker_card.get('balance') or 0)
            aggregate_card['available'] += float(broker_card.get('available') or 0)
            aggregate_card['pnl'] += float(broker_card.get('pnl') or 0)
            aggregate_card['positions'] += int(broker_card.get('positions') or 0)
            if account_number and account_number not in aggregate_card['accountNumbers']:
                aggregate_card['accountNumbers'].append(account_number)

            account_summary = {
                'credentialId': cred['credential_id'],
                'accountNumber': account_number,
                'connected': bool(broker_card.get('connected')),
                'balance': float(broker_card.get('balance') or 0),
                'available': float(broker_card.get('available') or 0),
                'pnl': float(broker_card.get('pnl') or 0),
                'positions': int(broker_card.get('positions') or 0),
                'mode': broker_card.get('mode'),
            }
            if broker_card.get('error'):
                account_summary['error'] = broker_card['error']
            aggregate_card['accounts'].append(account_summary)

            current_primary = next(
                (
                    account for account in aggregate_card['accounts']
                    if account.get('accountNumber') == aggregate_card.get('accountNumber')
                ),
                None,
            )
            if current_primary is None or (
                (account_summary['connected'], account_summary['balance'], account_summary['positions'])
                > (
                    bool(current_primary.get('connected')),
                    float(current_primary.get('balance') or 0),
                    int(current_primary.get('positions') or 0),
                )
            ):
                aggregate_card['accountNumber'] = account_number

        portfolio['total_brokers'] = len(brokers)
        portfolio['connected_brokers'] = sum(1 for broker_card in brokers.values() if broker_card.get('connected'))
        portfolio['total_balance'] = sum(float(broker_card.get('balance') or 0) for broker_card in brokers.values())
        portfolio['total_available'] = sum(float(broker_card.get('available') or 0) for broker_card in brokers.values())
        portfolio['total_pnl'] = sum(float(broker_card.get('pnl') or 0) for broker_card in brokers.values())
        portfolio['total_positions'] = sum(int(broker_card.get('positions') or 0) for broker_card in brokers.values())

        return jsonify({'success': True, 'portfolio': portfolio, 'brokers': brokers}), 200
    except Exception as e:
        logger.error(f"Error building unified portfolio: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


