@app.route('/api/unified/close-all', methods=['POST'])
@require_session
def close_all_unified_positions():
    """Close all open positions across supported brokers for the authenticated user."""
    user_id = request.user_id

    try:
        requested_mode = str((request.json or {}).get('mode') or '').strip().upper()
        preferred_mode = requested_mode if requested_mode in ['LIVE', 'DEMO'] else get_user_trading_mode_value(user_id)
        desired_live = 1 if preferred_mode == 'LIVE' else 0
        requested_credential_id = str((request.json or {}).get('credential_id') or '').strip()
        requested_account_number = str((request.json or {}).get('account_number') or (request.json or {}).get('account') or '').strip()

        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('''
            SELECT credential_id, broker_name, account_number, is_live, server
            FROM broker_credentials
            WHERE user_id = ? AND is_active = 1
            ORDER BY broker_name, credential_id DESC
        ''', (user_id,))
        credentials = [dict(row) for row in cursor.fetchall()]
        credentials = filter_mt5_credentials_for_active_session(
            credentials,
            requested_credential_id=requested_credential_id,
            requested_account_number=requested_account_number,
        )
        conn.close()

        total_closed = 0
        results = []

        for cred in credentials:
            broker_name = canonicalize_broker_name(cred.get('broker_name'))
            effective_is_live = int(normalize_mt5_is_live_flag(broker_name, cred.get('is_live'), cred.get('server')))
            if effective_is_live != desired_live:
                continue

            conn_label, broker_conn = get_broker_connection(
                cred['credential_id'],
                user_id,
                bot_id=f'unified-close-all:{cred["credential_id"]}',
            )
            if not broker_conn:
                results.append({
                    'broker': broker_name,
                    'accountNumber': cred['account_number'],
                    'success': False,
                    'error': conn_label or 'Connection unavailable',
                })
                continue

            try:
                broker_positions = broker_conn.get_positions() or []
                for position in broker_positions:
                    position_id = position.get('deal_id') or position.get('trade_id') or position.get('ticket')
                    if position_id in [None, '']:
                        continue
                    close_result = broker_conn.close_position(str(position_id))
                    success = bool(close_result.get('success'))
                    if success:
                        total_closed += 1
                    results.append({
                        'broker': broker_name,
                        'accountNumber': cred['account_number'],
                        'positionId': str(position_id),
                        'success': success,
                        'error': close_result.get('error'),
                    })
            finally:
                if hasattr(broker_conn, 'disconnect'):
                    try:
                        broker_conn.disconnect()
                    except Exception:
                        pass

        return jsonify({'success': True, 'total_closed': total_closed, 'results': results}), 200
    except Exception as e:
        logger.error(f"Error closing unified positions: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/trades/history', methods=['GET'])
@require_session
def get_trades_history():
    """Get TRADE HISTORY (closed trades) from the last N days - supports all brokers"""
    user_id = request.user_id
    days = request.args.get('days', default=30, type=int)
    broker_filter = request.args.get('broker', default='', type=str).strip()  # Optional: filter by broker
    requested_mode = str(request.args.get('mode') or '').strip().upper()
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        preferred_mode = requested_mode if requested_mode in ['LIVE', 'DEMO'] else get_user_trading_mode_value(user_id)
        desired_live = 1 if preferred_mode == 'LIVE' else 0
        
        # Query all active credentials for user, optionally filtered by broker
        if broker_filter:
            cursor.execute('''
                SELECT credential_id, broker_name, account_number, password, server, is_live, api_key, username
                FROM broker_credentials
                WHERE user_id = ? AND is_active = 1 AND broker_name = ?
                ORDER BY broker_name, credential_id DESC
            ''', (user_id, broker_filter))
        else:
            cursor.execute('''
                SELECT credential_id, broker_name, account_number, password, server, is_live, api_key, username
                FROM broker_credentials
                WHERE user_id = ? AND is_active = 1
                ORDER BY broker_name, credential_id DESC
            ''', (user_id,))
        
        creds = [dict(row) for row in cursor.fetchall()]
        creds, duplicate_credential_ids = dedupe_active_broker_credentials(creds)
        if duplicate_credential_ids:
            logger.info(
                f"Detected {len(duplicate_credential_ids)} duplicate/incomplete broker credential(s) for user {user_id} while loading trade history; leaving database unchanged during polling."
            )
        conn.close()

        if not creds:
            return jsonify({
                'success': False,
                'trades': [],
                'totalCount': 0,
                'message': f'No broker credentials found for user'
            }), 200

        all_trades = []
        
        # Fetch trades from each broker
        for cred in creds:
            broker_name = canonicalize_broker_name(cred.get('broker_name'))
            account_num = cred['account_number']
            
            try:
                # ==================== EXNESS ====================
                if broker_name in ['Exness', 'MetaTrader5']:
                    effective_is_live = int(normalize_mt5_is_live_flag(broker_name, cred.get('is_live'), cred.get('server')))
                    if effective_is_live == desired_live:
                        active_snapshot = read_active_mt5_account_snapshot(
                            broker_name,
                            account_num,
                            credential_id=cred['credential_id'],
                            user_id=user_id,
                        )
                        if active_snapshot:
                            mt5_conn = MT5Connection({
                                'account': int(account_num),
                                'password': cred['password'],
                                'server': cred.get('server', 'Exness-MT5Trial9'),
                                'broker': broker_name,
                                'is_live': bool(cred['is_live']),
                            })
                            mt5_conn.connected = True
                            broker_trades = mt5_conn.get_trade_history(days=days)
                            all_trades.extend(broker_trades or [])
                            logger.info(f"✅ Fetched {len(broker_trades or [])} trades from active MT5 session for {broker_name} {account_num}")
                        else:
                            logger.info(
                                f"ℹ️ Trade history: skipping MT5 session switch for {broker_name} {account_num}; requested account is not active"
                            )
                
                # ==================== BINANCE ====================
                elif broker_name == 'Binance':
                    # Prefer locally tracked closed trades for dashboard/history views.
                    # Re-authing to Binance on every poll adds latency and SSL churn, while
                    # the bot runtime already persists meaningful closed trades into SQLite.
                    db_hist_trades = []
                    try:
                        hist_conn = build_sqlite_connection(timeout=10.0, row_factory=True)
                        hist_cursor = hist_conn.cursor()
                        since_ts = (datetime.now() - timedelta(days=days)).isoformat()
                        hist_cursor.execute(
                            '''SELECT trade_id, bot_id, user_id, symbol, order_type, volume, price, profit,
                                      ticket, time_open, time_close, status, created_at
                               FROM trades WHERE user_id = ? AND status = 'closed' AND created_at >= ?
                               ORDER BY time_close DESC LIMIT 500''',
                            (user_id, since_ts)
                        )
                        db_hist_cols = [d[0] for d in hist_cursor.description]
                        for db_row in hist_cursor.fetchall():
                            db_trade = dict(zip(db_hist_cols, db_row))
                            db_trade['broker'] = 'Binance'
                            db_trade['account_number'] = account_num
                            db_trade['source'] = 'db'
                            db_trade['type'] = db_trade.pop('order_type', 'BUY')
                            entry_p = db_trade.pop('price', 0) or 0
                            db_trade['entryPrice'] = entry_p
                            db_trade['openPrice'] = entry_p
                            db_trade['openTime'] = db_trade.pop('time_open', None)
                            db_trade['closeTime'] = db_trade.pop('time_close', None)
                            db_hist_trades.append(db_trade)
                        db_hist_trades = _dedupe_trade_records(db_hist_trades)
                        hist_conn.close()
                    except Exception as hist_err:
                        logger.warning(f"Could not load DB history for Binance {user_id}: {hist_err}")

                    if db_hist_trades:
                        all_trades.extend(db_hist_trades)
                        logger.info(
                            f"Loaded {len(db_hist_trades)} Binance trades from SQLite for {account_num}"
                        )

                    resolved_market = _resolve_binance_market_for_credential_usage(
                        credential_row=cred,
                        credential_id=cred.get('credential_id'),
                        user_id=user_id,
                    )
                    binance_conn = BinanceConnection({
                        'api_key': cred.get('api_key'),
                        'api_secret': cred['password'],
                        'account_number': account_num,
                        'server': resolved_market,
                        'market': resolved_market,
                        'is_live': bool(cred['is_live']),
                    })
                    if binance_conn.connect():
                        # Always fetch the live exchange fills and merge them against the
                        # DB record so externally-closed Binance spot trades that the bot
                        # never persisted (e.g. SL/TP fills the bot missed between polls,
                        # or closes the bot restarted through) are backfilled into the
                        # dashboard/history view. The previous logic short-circuited the
                        # live fetch whenever the DB had ANY closed trades, which silently
                        # dropped missing closes (DB has 2 / exchange has 15).
                        exchange_symbols = set()
                        for _dt in db_hist_trades:
                            _dsym = str(_dt.get('symbol') or '').strip().upper()
                            if _dsym:
                                exchange_symbols.add(_dsym)
                        for _pos_sym in (getattr(binance_conn, '_active_symbols', []) or []):
                            _psym = str(_pos_sym).strip().upper()
                            if _psym:
                                exchange_symbols.add(_psym)
                        # Fall back to the canonical watch list so we still surface closes
                        # for symbols the bot traded before its runtime state was lost.
                        for _fb in ['BTCUSDT', 'ETHUSDT', 'BNBUSDT', 'ADAUSDT', 'ATOMUSDT', 'ARBUSDT', 'APTUSDT', 'UNIUSDT', 'TIAUSDT', 'ETCUSDT', 'XRPUSDT', 'SOLUSDT', 'DOGEUSDT', 'AVAXUSDT', 'LINKUSDT', 'DOTUSDT', 'MATICUSDT', 'LTCUSDT', 'BCHUSDT', 'ALGOUSDT', 'XLMUSDT']:
                            exchange_symbols.add(_fb)
                        raw_fills = binance_conn.get_trades(symbols=list(exchange_symbols) or None) or []
                        db_tickets = {str(t.get('ticket', '')) for t in db_hist_trades}
                        meaningful_fills = []
                        for t in raw_fills:
                            # Map raw fill into the DB trade shape used by the dashboard.
                            profit = _safe_float(t.get('profit', 0.0), 0.0)
                            # Realized fills with zero reconstructed profit are still
                            # meaningful if we have a symbol + timestamp + side, so
                            # include them only when they represent an actual closing
                            # fill (i.e. a SELL into a prior position).
                            if not str(t.get('symbol', '')).strip():
                                continue
                            meaningful_fills.append(t)
                        for trade in meaningful_fills:
                            trade['broker'] = 'Binance'
                            trade['account_number'] = account_num
                            trade['source'] = 'exchange_fill'
                        combined_binance = db_hist_trades + meaningful_fills
                        # De-duplicate fills against already-recorded DB closes by ticket.
                        if db_tickets:
                            combined_binance = [
                                t for t in combined_binance
                                if str(t.get('ticket', '')) not in db_tickets or t.get('source') == 'db'
                            ]
                        all_trades.extend(combined_binance)
                        logger.info(
                            f"Fetched {len(combined_binance)} trades from Binance {account_num} "
                            f"({len(db_hist_trades)} DB closed, {len(meaningful_fills)} exchange fills "
                            f"from {len(raw_fills)} raw)"
                        )
                        binance_conn.disconnect()
                
                # ==================== FXCM ====================
                elif broker_name == 'FXCM':
                    fxcm_conn = FXCMConnection({
                        'api_key': cred.get('api_key'),
                        'username': cred.get('username'),
                        'password': cred.get('password'),
                        'account_number': account_num,
                        'server': cred.get('server'),
                        'connection': 'Real' if bool(cred['is_live']) else 'Demo',
                        'is_live': bool(cred['is_live']),
                    })
                    if fxcm_conn.connect():
                        broker_trades = fxcm_conn.get_trades() or []
                        # Add broker info to each trade
                        for trade in broker_trades:
                            trade['broker'] = 'FXCM'
                            trade['account_number'] = account_num
                        all_trades.extend(broker_trades)
                        logger.info(f"✅ Fetched {len(broker_trades)} trades from FXCM {account_num}")
                        fxcm_conn.disconnect()
                    else:
                        logger.warning(
                            f"⚠️ FXCM trade fetch failed for {account_num}: {fxcm_conn.last_error or 'Unknown FXCM error'}"
                        )
                
                # ==================== OANDA ====================
                elif broker_name == 'OANDA':
                    oanda_conn = OANDAConnection({
                        'api_key': cred.get('api_key'),
                        'account_number': account_num,
                        'is_live': bool(cred['is_live']),
                    })
                    if oanda_conn.connect():
                        broker_trades = oanda_conn.get_trades() or []
                        # Add broker info to each trade
                        for trade in broker_trades:
                            trade['broker'] = 'OANDA'
                            trade['account_number'] = account_num
                        all_trades.extend(broker_trades)
                        logger.info(f"✅ Fetched {len(broker_trades)} trades from OANDA {account_num}")
                        oanda_conn.disconnect()
                        
            except Exception as e:
                logger.warning(f"⚠️ Could not fetch trades from {broker_name} {account_num}: {e}")
                continue

        def _trade_history_sort_key(trade: Dict) -> Tuple[int, str]:
            raw_value = trade.get('closeTime') or trade.get('closedAt') or trade.get('time') or 0
            if isinstance(raw_value, datetime):
                return (int(raw_value.timestamp()), '')
            if isinstance(raw_value, (int, float)):
                return (int(raw_value), '')

            raw_text = str(raw_value).strip()
            if not raw_text:
                return (0, '')

            if raw_text.isdigit():
                return (int(raw_text), '')

            normalized_text = raw_text.replace('Z', '+00:00') if raw_text.endswith('Z') else raw_text
            try:
                parsed = datetime.fromisoformat(normalized_text)
                return (int(parsed.timestamp()), '')
            except ValueError:
                return (0, raw_text)

        normalized_trades = []
        for trade in all_trades:
            if not isinstance(trade, dict):
                continue

            normalized_trade = dict(trade)
            sort_ts, sort_text = _trade_history_sort_key(normalized_trade)
            normalized_trade['_historySortTs'] = int(sort_ts)
            normalized_trade['_historySortText'] = str(sort_text or '')
            normalized_trade['broker'] = str(normalized_trade.get('broker', 'unknown') or 'unknown')
            normalized_trades.append(normalized_trade)

        # Sort trades by timestamp (most recent first) while tolerating mixed broker payload types.
        try:
            normalized_trades.sort(
                key=lambda trade: (trade.get('_historySortTs', 0), trade.get('_historySortText', '')),
                reverse=True,
            )
        except TypeError as sort_error:
            logger.warning(f"Trade history mixed timestamp sort fallback triggered: {sort_error}")
            normalized_trades.sort(
                key=lambda trade: str(
                    trade.get('closeTime') or trade.get('closedAt') or trade.get('time') or ''
                ),
                reverse=True,
            )

        for trade in normalized_trades:
            trade.pop('_historySortTs', None)
            trade.pop('_historySortText', None)

        return jsonify({
            'success': True,
            'trades': normalized_trades,
            'totalCount': len(normalized_trades),
            'period': f'Last {days} days',
            'dataSource': 'multi-broker',
            'brokers': list(set([t.get('broker', 'unknown') for t in normalized_trades]))
        }), 200
            
    except Exception as e:
        logger.error(f"Error getting trade history: {e}")
        return jsonify({
            'success': False,
            'error': str(e),
            'trades': []
        }), 500


@app.route('/api/account/performance', methods=['GET'])
@require_session
def get_account_performance():
    """Get account PERFORMANCE METRICS and statistics"""
    user_id = request.user_id
    
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        preferred_mode = get_user_trading_mode_value(user_id)
        desired_live = 1 if preferred_mode == 'LIVE' else 0
        
        cursor.execute('''
            SELECT credential_id, broker_name, account_number, password, server, is_live
            FROM broker_credentials 
            WHERE user_id = ? AND is_active = 1 AND broker_name = 'Exness' AND is_live = ?
            ORDER BY credential_id
            LIMIT 1
        ''', (user_id, desired_live))
        
        cred = cursor.fetchone()
        conn.close()
        
        if not cred:
            return jsonify({
                'success': False,
                'metrics': None
            })

        active_snapshot = read_active_mt5_account_snapshot('Exness', cred[2], credential_id=cred[0], user_id=user_id)
        if active_snapshot:
            mt5_conn = MT5Connection({
                'account': int(cred[2]),
                'password': cred[3],
                'server': cred[4],
                'broker': 'Exness',
                'is_live': bool(cred[5]),
            })
            mt5_conn.connected = True
            metrics = mt5_conn.get_performance_metrics()
            return jsonify({
                'success': True,
                'metrics': metrics,
                'dataSource': 'active_mt5_session',
            })

        return jsonify({
            'success': False,
            'metrics': None,
            'error': 'Requested Exness account is not the active MT5 session; refusing to switch MT5 automatically'
        })
            
    except Exception as e:
        logger.error(f"Error getting performance metrics: {e}")
        return jsonify({
            'success': False,
            'error': str(e)
        }), 500


