# ==================== INTELLIGENT STRATEGY SWITCHING & POSITION SIZING ====================

class StrategyPerformanceTracker:
    """Tracks performance of each strategy to enable intelligent switching"""
    
    def __init__(self):
        self.strategy_stats = {}
        self.reset_stats()
    
    def reset_stats(self):
        """Initialize stats for all strategies"""
        self.strategy_stats = {
            'Scalping': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Momentum Trading': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Trend Following': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Mean Reversion': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Range Trading': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Breakout Trading': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Swing Trend DCA': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Bitcoin Liquidity Sweep': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Ethereum Relative Strength': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Funding Rate Exhaustion': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Solana Trend Continuation': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Session Range Reversal': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'Gold Volatility Expansion': {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
            'EMA Pullback ML':        {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0},
        }
    
    def record_trade(self, strategy, profit, symbol=''):
        """Record a trade result for a strategy"""
        if strategy not in self.strategy_stats:
            self.strategy_stats[strategy] = {'trades': 0, 'wins': 0, 'losses': 0, 'profit': 0.0, 'wins_streak': 0, 'losses_streak': 0}
        
        stats = self.strategy_stats[strategy]
        stats['trades'] += 1
        stats['profit'] += profit
        
        if profit > 0:
            stats['wins'] += 1
            stats['wins_streak'] += 1
            stats['losses_streak'] = 0
        else:
            stats['losses'] += 1
            stats['losses_streak'] += 1
            stats['wins_streak'] = 0
        
        logger.debug(f"Recorded {strategy} trade on {symbol}: profit={profit}, total_stats={stats}")
    
    def get_win_rate(self, strategy):
        """Get win rate for strategy"""
        stats = self.strategy_stats.get(strategy, {})
        trades = stats.get('trades', 0)
        if trades == 0:
            return 0
        return (stats.get('wins', 0) / trades) * 100
    
    def get_profit_factor(self, strategy):
        """Calculate profit factor (total wins / abs(total losses))"""
        stats = self.strategy_stats.get(strategy, {})
        profit = stats.get('profit', 0)
        trades = stats.get('trades', 0)
        wins = stats.get('wins', 0)
        losses = stats.get('losses', 0)
        
        if losses == 0 or trades < 3:
            return 1.0  # Insufficient data
        
        avg_win = profit / wins if wins > 0 else 0
        avg_loss = -profit / losses if losses > 0 else 0
        
        if avg_loss == 0:
            return 99.99
        
        return avg_win / abs(avg_loss) if avg_loss != 0 else 1.0
    
    def get_best_strategy(self):
        """Get best performing strategy based on profit factor and win rate"""
        best_strategy = 'Trend Following'  # Default
        best_score = 0
        
        for strategy, stats in self.strategy_stats.items():
            if stats['trades'] < 3:  # Need at least 3 trades for evaluation
                continue
            
            win_rate = self.get_win_rate(strategy)
            profit_factor = self.get_profit_factor(strategy)
            total_profit = stats['profit']
            
            # Composite score: 40% profit_factor + 40% win_rate + 20% total_profit (normalized)
            score = (profit_factor * 0.4) + (win_rate / 100 * 0.4) + min(total_profit / 1000, 1.0) * 0.2
            
            if score > best_score:
                best_score = score
                best_strategy = strategy
        
        return best_strategy
    
    def get_all_stats(self):
        """Get all strategy statistics"""
        return {
            strategy: {
                **stats,
                'win_rate': self.get_win_rate(strategy),
                'profit_factor': round(self.get_profit_factor(strategy), 2),
            }
            for strategy, stats in self.strategy_stats.items()
        }


AUTO_STRATEGY_SWITCH_COOLDOWN_MINUTES = 20


def _get_recent_strategy_trade_stats(bot_config: Dict[str, Any], strategy_name: str, limit: int = 12) -> Dict[str, float]:
    closed_trades = [
        trade for trade in (bot_config.get('tradeHistory') or [])
        if isinstance(trade, dict)
        and _is_bot_managed_closed_trade(trade)
        and str(trade.get('strategy') or '').strip() == strategy_name
    ]
    if limit > 0:
        closed_trades = closed_trades[-limit:]

    trade_count = len(closed_trades)
    wins = sum(1 for trade in closed_trades if _safe_float(trade.get('profit'), 0.0) > 0)
    total_profit = sum(_safe_float(trade.get('profit'), 0.0) for trade in closed_trades)
    return {
        'trades': trade_count,
        'wins': wins,
        'win_rate': (wins / trade_count * 100.0) if trade_count else 0.0,
        'profit': total_profit,
    }


def _choose_strategy_for_cycle(
    bot_id: str,
    bot_config: Dict[str, Any],
    configured_symbols: List[str],
    signal_threshold: int,
) -> str:
    current_strategy = str(bot_config.get('strategy') or 'Trend Following')
    configured_base_symbols = {
        _normalize_symbol_base(symbol)
        for symbol in (configured_symbols or [])
        if _normalize_symbol_base(symbol)
    }
    if configured_base_symbols and configured_base_symbols.issubset(SMALL_LIVE_ACCOUNT_OPTIONAL_CRYPTO_BASE_SYMBOLS):
        allowed_crypto_strategies = {
            'Swing Trend DCA',
            'Trend Following',
            'Bitcoin Liquidity Sweep',
            'Ethereum Relative Strength',
            'Funding Rate Exhaustion',
            'Solana Trend Continuation',
        }
        return current_strategy if current_strategy in allowed_crypto_strategies else 'Swing Trend DCA'

    if not _coerce_bool(bot_config.get('autoSwitch', True), True):
        return current_strategy

    if bot_config.get('open_positions'):
        return current_strategy

    last_switch_raw = bot_config.get('lastStrategySwitch')
    if last_switch_raw:
        try:
            last_switch_at = datetime.fromisoformat(str(last_switch_raw))
            if (datetime.now() - last_switch_at).total_seconds() < (AUTO_STRATEGY_SWITCH_COOLDOWN_MINUTES * 60):
                return current_strategy
        except Exception:
            pass

    idle_cycles = int(bot_config.get('adaptiveSignalMissCount') or 0)
    should_expand_symbol_universe = _coerce_bool(bot_config.get('intelligentScanner', False), False) or idle_cycles >= ADAPTIVE_SCANNER_TRIGGER_MISSES
    candidate_symbols = build_scanner_symbol_universe(bot_config) if should_expand_symbol_universe else list(configured_symbols)
    candidate_symbols = list(dict.fromkeys([symbol for symbol in candidate_symbols if str(symbol).strip()]))
    if not candidate_symbols:
        return current_strategy

    account_id = bot_config.get('accountId', '')
    risk_per_trade = _safe_float(bot_config.get('riskPerTrade'), 10.0)
    scored_candidates = []

    _regime_cache: Dict[str, Dict[str, Any]] = {}

    for strategy_name, strategy_func in STRATEGY_MAP.items():
        strategy_cache: Dict[str, Optional[Dict[str, Any]]] = {}
        strengths: List[float] = []
        qualifying_hits = 0
        best_symbol = None
        best_signal_label = 'NEUTRAL'

        for symbol in candidate_symbols:
            market_data = _enrich_market_data_with_bot_context(bot_config, symbol)
            trade_params = _get_cached_strategy_params(
                strategy_cache,
                strategy_func,
                symbol,
                account_id,
                risk_per_trade,
                market_data,
                bot_config=bot_config,
            )
            if not trade_params:
                continue

            signal_info = trade_params.get('signal', {}) or {}
            strength = _safe_float(signal_info.get('strength'), 0.0)
            # Regime-aware bias: nudge the raw signal strength by how well this
            # strategy fits the symbol's current regime. Only applied when the
            # classifier is reasonably confident, otherwise it is left neutral.
            if strength > 0:
                _regime = _regime_cache.get(symbol)
                if _regime is None:
                    _regime = _classify_market_regime(symbol, market_data)
                    _regime_cache[symbol] = _regime
                _fit = _regime.get('strategy_fit', {}).get(strategy_name, 1.0)
                if _regime.get('confidence', 0.0) >= 0.5 and _fit != 1.0:
                    strength = strength * _fit
            strengths.append(strength)
            if strength >= signal_threshold:
                qualifying_hits += 1
            if best_symbol is None or strength > max(strengths[:-1], default=-1.0):
                best_symbol = symbol
                best_signal_label = str(signal_info.get('signal') or 'NEUTRAL')

        if not strengths:
            continue

        top_strengths = sorted(strengths, reverse=True)[:3]
        average_top_strength = sum(top_strengths) / len(top_strengths)
        global_stats = strategy_tracker.strategy_stats.get(strategy_name, {})
        global_trade_count = int(global_stats.get('trades', 0) or 0)
        global_perf_bonus = 0.0
        if global_trade_count >= 3:
            global_perf_bonus += min(strategy_tracker.get_win_rate(strategy_name) / 10.0, 10.0)
            global_perf_bonus += min(strategy_tracker.get_profit_factor(strategy_name) * 2.0, 10.0)
            global_perf_bonus += max(-5.0, min(_safe_float(global_stats.get('profit'), 0.0) / 50.0, 5.0))

        recent_stats = _get_recent_strategy_trade_stats(bot_config, strategy_name)
        recent_perf_bonus = 0.0
        if recent_stats['trades'] > 0:
            recent_perf_bonus += min(recent_stats['win_rate'] / 12.5, 8.0)
            recent_perf_bonus += max(-6.0, min(recent_stats['profit'] / 40.0, 6.0))

        stickiness_bonus = 4.0 if strategy_name == current_strategy else 0.0
        score = (
            qualifying_hits * 100.0
            + average_top_strength * 1.2
            + max(top_strengths)
            + global_perf_bonus
            + recent_perf_bonus
            + stickiness_bonus
        )

        scored_candidates.append({
            'strategy': strategy_name,
            'score': score,
            'hits': qualifying_hits,
            'bestStrength': max(top_strengths),
            'bestSymbol': best_symbol,
            'bestSignal': best_signal_label,
            'globalTrades': global_trade_count,
            'recentTrades': int(recent_stats['trades']),
        })

    if not scored_candidates:
        return current_strategy

    scored_candidates.sort(key=lambda item: (item['score'], item['hits'], item['bestStrength']), reverse=True)
    chosen = scored_candidates[0]
    chosen_strategy = chosen['strategy']
    bot_config['lastStrategySelection'] = {
        'timestamp': datetime.now().isoformat(),
        'strategy': chosen_strategy,
        'score': round(chosen['score'], 2),
        'hits': chosen['hits'],
        'bestSymbol': chosen['bestSymbol'],
        'bestSignal': chosen['bestSignal'],
    }

    if chosen_strategy == current_strategy:
        return current_strategy

    switch_reason = (
        f"scanner selected {chosen_strategy} on {chosen['bestSymbol']} "
        f"({chosen['bestSignal']} {chosen['bestStrength']:.0f}/100, {chosen['hits']} qualifying setup(s))"
    )
    logger.info(f"🧠 Bot {bot_id}: Strategy switch {current_strategy} -> {chosen_strategy} | {switch_reason}")
    bot_config['strategy'] = chosen_strategy
    bot_config['lastStrategySwitch'] = datetime.now().isoformat()
    bot_config.setdefault('strategyHistory', []).append({
        'timestamp': bot_config['lastStrategySwitch'],
        'fromStrategy': current_strategy,
        'toStrategy': chosen_strategy,
        'reason': switch_reason,
    })
    bot_config['strategyHistory'] = bot_config['strategyHistory'][-50:]
    persist_bot_runtime_state(bot_id, force=True)
    return chosen_strategy


def _get_recent_symbol_strategy_trade_stats(
    bot_config: Dict[str, Any],
    symbol: str,
    strategy_name: str,
    limit: int = 18,
) -> Dict[str, float]:
    target_symbol = _normalize_symbol_base(symbol)
    closed_trades = []
    for trade in (bot_config.get('tradeHistory') or []):
        if not isinstance(trade, dict):
            continue
        if not _is_bot_managed_closed_trade(trade):
            continue
        if str(trade.get('strategy') or '').strip() != strategy_name:
            continue
        trade_symbol = _normalize_symbol_base(trade.get('symbol'))
        if target_symbol and trade_symbol and trade_symbol != target_symbol:
            continue
        closed_trades.append(trade)

    if limit > 0:
        closed_trades = closed_trades[-limit:]

    trade_count = len(closed_trades)
    wins = sum(1 for trade in closed_trades if _safe_float(trade.get('profit'), 0.0) > 0)
    total_profit = sum(_safe_float(trade.get('profit'), 0.0) for trade in closed_trades)
    return {
        'trades': trade_count,
        'wins': wins,
        'win_rate': (wins / trade_count * 100.0) if trade_count else 0.0,
        'profit': total_profit,
    }


def _strategy_candidates_for_symbol(symbol: str, broker_name: str) -> List[str]:
    normalized_symbol = _normalize_symbol_base(symbol)
    normalized_broker = canonicalize_broker_name(broker_name)

    if normalized_broker == 'Binance':
        if normalized_symbol.startswith('BTC'):
            return ['Bitcoin Liquidity Sweep', 'Momentum Trading', 'Swing Trend DCA', 'Trend Following']
        if normalized_symbol.startswith('ETH'):
            return ['Ethereum Relative Strength', 'Momentum Trading', 'Swing Trend DCA', 'Trend Following']
        if normalized_symbol.startswith('SOL'):
            return ['Solana Trend Continuation', 'Momentum Trading', 'Swing Trend DCA', 'Trend Following']
        if normalized_symbol.startswith(('DOGE', 'SHIB', 'PEPE', 'WIF', 'BONK')):
            return ['Momentum Trading', 'Breakout Trading', 'Scalping', 'Swing Trend DCA']
        return ['Momentum Trading', 'Swing Trend DCA', 'Breakout Trading', 'Trend Following']

    if normalized_symbol.startswith(('XAU', 'XAG', 'XPT', 'XPD')):
        return ['Gold Volatility Expansion', 'Breakout Trading', 'Trend Following', 'Mean Reversion']
    if normalized_symbol.startswith(('US30', 'US500', 'USTEC')):
        return ['Session Range Reversal', 'Breakout Trading', 'Momentum Trading', 'Trend Following']
    if _is_exness_forex_symbol(normalized_symbol):
        return ['Trend Following', 'Range Trading', 'Mean Reversion', 'Breakout Trading']
    return ['Trend Following', 'Momentum Trading', 'Breakout Trading', 'Range Trading']


def _choose_strategy_for_symbol(
    bot_config: Dict[str, Any],
    symbol: str,
    default_strategy: str,
) -> str:
    default_choice = str(default_strategy or 'Trend Following').strip() or 'Trend Following'
    if not _coerce_bool(bot_config.get('autoSwitch', True), True):
        return default_choice

    broker_name = canonicalize_broker_name(
        bot_config.get('brokerName') or bot_config.get('broker_type') or bot_config.get('broker') or ''
    )
    candidates = _strategy_candidates_for_symbol(symbol, broker_name)
    if default_choice not in candidates:
        candidates.append(default_choice)

    symbol_performance = None
    if isinstance(bot_config, dict):
        try:
            symbol_performance = _evaluate_symbol_performance(bot_config, symbol)
        except Exception:
            symbol_performance = None

    best_strategy = default_choice
    best_score = float('-inf')
    for rank, strategy_name in enumerate(candidates):
        if strategy_name not in STRATEGY_MAP:
            continue

        # Deterministic baseline keeps beginner behavior stable even with sparse history.
        baseline_score = float(max(0, len(candidates) - rank)) * 3.0
        if strategy_name == default_choice:
            baseline_score += 2.5

        symbol_stats = _get_recent_symbol_strategy_trade_stats(bot_config, symbol, strategy_name)
        symbol_bonus = 0.0
        if symbol_stats['trades'] > 0:
            symbol_bonus += min(symbol_stats['win_rate'] / 8.0, 10.0)
            symbol_bonus += max(-8.0, min(symbol_stats['profit'] / 25.0, 8.0))
            symbol_bonus += min(symbol_stats['trades'], 10) * 0.4

        global_stats = strategy_tracker.strategy_stats.get(strategy_name, {})
        global_trades = int(global_stats.get('trades', 0) or 0)
        global_bonus = 0.0
        if global_trades >= 3:
            global_bonus += min(strategy_tracker.get_win_rate(strategy_name) / 12.0, 6.0)
            global_bonus += min(strategy_tracker.get_profit_factor(strategy_name) * 1.5, 6.0)

        performance_bonus = 0.0
        if symbol_performance:
            verdict = str(symbol_performance.get('verdict') or 'normal')
            performance_multiplier = _safe_float(symbol_performance.get('multiplier'), 1.0)
            if verdict == 'favored':
                performance_bonus += 2.0
            elif verdict == 'demoted':
                performance_bonus -= 1.5
            elif verdict == 'blacklisted':
                performance_bonus -= 4.0
            performance_bonus += max(-1.0, min((performance_multiplier - 1.0) * 6.0, 1.5))

        score = baseline_score + symbol_bonus + global_bonus + performance_bonus
        if score > best_score:
            best_score = score
            best_strategy = strategy_name

    return best_strategy


class DynamicPositionSizer:
    """Intelligently adjusts position sizes based on account performance"""
    
    def __init__(self, base_size=1.0, min_size=0.01, max_size=5.0):
        self.base_size = base_size
        self.min_size = min_size
        self.max_size = max_size
    
    def calculate_position_size(self, bot_config, volatility_level='Medium'):
        """
        Calculate optimal position size based on:
        - Account equity changes (scaling)
        - Win/loss streaks (confidence)
        - Volatility (risk adjustment)
        - Drawdown (protection)
        """
        import random
        
        size = max(_safe_float(bot_config.get('basePositionSize'), self.base_size), self.min_size)
        
        # Get account performance metrics
        total_trades = bot_config.get('totalTrades', 0)
        winning_trades = bot_config.get('winningTrades', 0)
        total_profit = bot_config.get('totalProfit', 0)
        max_drawdown = bot_config.get('maxDrawdown', 0)
        peak_profit = bot_config.get('peakProfit', 0)
        
        # 1. EQUITY SCALING - Scale by cumulative profit
        if total_trades > 0 and total_profit > 0:
            equity_multiplier = 1.0 + (total_profit / 1000)  # +10% size per $1000 profit
            size *= min(equity_multiplier, 1.5)  # Cap at 1.5x
        
        # 2. WIN STREAK SCALING - Increase after winning trades
        if total_trades > 0:
            recent_trades = _recent_closed_trades(bot_config, limit=5)
            win_streak = 0
            loss_streak = 0
            for trade in reversed(recent_trades):
                if trade.get('profit', 0) > 0:
                    win_streak += 1
                    break
                else:
                    loss_streak += 1
                    if win_streak > 0:
                        break
            
            if win_streak > 2:
                size *= (1.0 + (win_streak * 0.1))  # +10% per win in streak
            elif loss_streak >= 2:
                size *= max(0.45, 1.0 - (loss_streak * 0.15))

        performance_state = _build_performance_sizing_state(bot_config, volatility_level)
        performance_multiplier = _safe_float(performance_state.get('multiplier'), 1.0)
        size *= performance_multiplier
        bot_config['effectivePositionSizeMultiplier'] = round(performance_multiplier, 3)
        bot_config['effectiveScannerCapitalMultiplier'] = round(_safe_float(performance_state.get('scannerCapitalMultiplier'), 1.0), 3)
        bot_config['lastSizingAdjustment'] = performance_state
        
        # 3. VOLATILITY ADJUSTMENT
        volatility_multiplier = {
            'Very Low': 1.15,  # Slightly increase in very low volatility
            'Low': 1.1,      # Increase size in low volatility
            'Medium': 1.0,   # Normal size
            'High': 0.8,     # Reduce in high volatility
            'Very High': 0.6 # Significantly reduce in extreme volatility
        }
        size *= volatility_multiplier.get(volatility_level, 1.0)
        
        # 4. DRAWDOWN PROTECTION - Reduce size during drawdowns
        if peak_profit > 0 and max_drawdown > 0:
            drawdown_percent = (max_drawdown / peak_profit) * 100
            if drawdown_percent > 20:  # If drawdown > 20%
                size *= 0.5  # Reduce to 50%
            elif drawdown_percent > 10:  # If drawdown > 10%
                size *= 0.7  # Reduce to 70%

        account_balance = max(
            float(bot_config.get('accountEquity') or 0.0),
            float(bot_config.get('accountBalance') or 0.0),
        )
        if _normalize_management_profile(bot_config.get('managementProfile')) == 'small_account':
            if account_balance > 0:
                balance_scale = max(0.25, min(account_balance / 250.0, 0.75))
                size *= balance_scale
            self_max = min(self.max_size, 0.5)
        else:
            self_max = self.max_size
        
        # 5. APPLY MIN/MAX CONSTRAINTS
        final_size = max(self.min_size, min(size, self_max))
        
        return round(final_size, 2)


def infer_symbol_quote_currency(symbol: str) -> Optional[str]:
    normalized = ''.join(ch for ch in str(symbol or '').upper() if ch.isalpha())
    if not normalized:
        return None

    for suffix in ('USDT', 'USDC', 'USD', 'EUR', 'GBP', 'ZAR', 'JPY', 'CHF', 'CAD', 'AUD', 'NZD'):
        if normalized.endswith(suffix):
            return suffix

    if len(normalized) >= 6:
        return normalized[3:6]

    return None


RECENT_PROFIT_RISK_GUARD_DEFAULT_LOOKBACK_TRADES = 10
RECENT_PROFIT_RISK_GUARD_MIN_LOOKBACK_TRADES = 3
RECENT_PROFIT_RISK_GUARD_MAX_LOOKBACK_TRADES = 20
RECENT_PROFIT_RISK_GUARD_DEFAULT_SHARE = 0.05
RECENT_PROFIT_RISK_GUARD_MIN_SHARE = 0.01
RECENT_PROFIT_RISK_GUARD_MAX_SHARE = 0.25
RECENT_PROFIT_RISK_GUARD_MIN_ELIGIBLE_TRADES = 3
RECENT_PROFIT_RISK_GUARD_MIN_PROFIT_POOL = 10.0


def _default_recent_profit_risk_guard_enabled(broker_name: str, is_live: bool) -> bool:
    # Enable for all Exness and Binance accounts (live and demo) so a recent profit
    # run cannot be given back by escalating risk on the next trades.
    return canonicalize_broker_name(broker_name) in {'Exness', 'Binance'}


def _default_top_movers_direct_trading(bot_config: Dict[str, Any]) -> bool:
    """Default top-movers DIRECT trading ON for Binance/Exness bots.

    The 'topMoversEnabled' scan already adds movers to the universe, but without
    direct trading the bot just spins on them and never places the trade. Users
    expect 'top movers direct trading' to actually trade the movers, so default it
    ON for crypto brokers. Other brokers keep it off unless explicitly enabled.
    """
    broker_name = canonicalize_broker_name(
        bot_config.get('brokerName') or bot_config.get('broker_type') or bot_config.get('broker') or ''
    )
    return broker_name in {'Binance', 'Exness'}


def infer_volatility_regime(price_history: List[float], window: int = 20) -> str:
    """Detect current market volatility regime.
    
    Returns: 'Low', 'Medium', 'High', or 'Very High'
    """
    if len(price_history) < window:
        return 'Medium'
    
    recent = price_history[-window:]
    returns = [(recent[i] - recent[i-1]) / recent[i-1] for i in range(1, len(recent))]
    
    if not returns:
        return 'Medium'
    
    avg_return = sum(returns) / len(returns)
    variance = sum((r - avg_return) ** 2 for r in returns) / len(returns)
    std_dev = variance ** 0.5
    
    # Normalize to ATR-like measure
    price_range = max(recent) - min(recent)
    price_level = sum(recent) / len(recent)
    atr_ratio = price_range / price_level if price_level > 0 else 0.01
    
    if atr_ratio < 0.005:
        return 'Low'
    elif atr_ratio < 0.015:
        return 'Medium'
    elif atr_ratio < 0.03:
        return 'High'
    else:
        return 'Very High'


def get_optimal_strategies_for_regime(volatility_regime: str) -> List[str]:
    """Get list of optimal strategies for a given volatility regime.
    
    Returns strategies in order of preference for the regime.
    """
    regime_strategy_map = {
        'Low': ['Range Trading', 'Mean Reversion', 'Scalping', 'Trend Following'],
        'Medium': ['Scalping', 'Momentum Trading', 'Trend Following', 'Breakout Trading'],
        'High': ['Trend Following', 'Momentum Trading', 'Breakout Trading', 'Scalping'],
        'Very High': ['Trend Following', 'Breakout Trading', 'Scalping', 'Mean Reversion'],
    }
    return regime_strategy_map.get(volatility_regime, ['Trend Following', 'Momentum Trading', 'Scalping'])


def _resolve_recent_profit_risk_guard_settings(
    raw_config: Dict[str, Any],
    broker_name: str = '',
    is_live: bool = False,
) -> Tuple[Dict[str, Any], List[str]]:
    warnings: List[str] = []
    raw_config = raw_config if isinstance(raw_config, dict) else {}
    enabled_default = _default_recent_profit_risk_guard_enabled(broker_name, is_live)
    enabled = _coerce_bool(raw_config.get('recentProfitRiskGuardEnabled', enabled_default), enabled_default)

    raw_lookback = raw_config.get('recentProfitRiskGuardLookbackTrades')
    if raw_lookback in (None, ''):
        lookback_trades = RECENT_PROFIT_RISK_GUARD_DEFAULT_LOOKBACK_TRADES
    else:
        try:
            lookback_trades = int(round(float(raw_lookback)))
        except (TypeError, ValueError):
            lookback_trades = RECENT_PROFIT_RISK_GUARD_DEFAULT_LOOKBACK_TRADES
            warnings.append('recentProfitRiskGuardLookbackTrades defaulted to 10')
    lookback_trades = max(
        RECENT_PROFIT_RISK_GUARD_MIN_LOOKBACK_TRADES,
        min(RECENT_PROFIT_RISK_GUARD_MAX_LOOKBACK_TRADES, lookback_trades),
    )

    raw_share = raw_config.get('recentProfitRiskGuardMaxRiskShare')
    if raw_share in (None, ''):
        max_risk_share = RECENT_PROFIT_RISK_GUARD_DEFAULT_SHARE
    else:
        normalized_share = _normalize_drawdown_share_value(raw_share)
        if normalized_share is None:
            max_risk_share = RECENT_PROFIT_RISK_GUARD_DEFAULT_SHARE
            warnings.append('recentProfitRiskGuardMaxRiskShare defaulted to 5%')
        else:
            max_risk_share = normalized_share
    max_risk_share = max(
        RECENT_PROFIT_RISK_GUARD_MIN_SHARE,
        min(RECENT_PROFIT_RISK_GUARD_MAX_SHARE, max_risk_share),
    )

    return {
        'recentProfitRiskGuardEnabled': enabled,
        'recentProfitRiskGuardLookbackTrades': lookback_trades,
        'recentProfitRiskGuardMaxRiskShare': round(max_risk_share, 4),
    }, warnings


def _resolve_effective_drawdown_amount(bot_config: Dict[str, Any]) -> float:
    """Return the most conservative configured drawdown budget in account currency."""
    if not isinstance(bot_config, dict):
        return 0.0

    candidates = []

    max_daily_loss = max(_safe_float(bot_config.get('maxDailyLoss'), 0.0), 0.0)
    if max_daily_loss > 0:
        candidates.append(max_daily_loss)

    balance_basis = max(
        _safe_float(bot_config.get('accountEquity'), 0.0),
        _safe_float(bot_config.get('accountBalance'), 0.0),
    )
    drawdown_pause_percent = max(_safe_float(bot_config.get('drawdownPausePercent'), 0.0), 0.0)
    if balance_basis > 0 and drawdown_pause_percent > 0:
        candidates.append(balance_basis * (drawdown_pause_percent / 100.0))

    configured_drawdown_amount = max(_safe_float(bot_config.get('maxDrawdownAmount'), 0.0), 0.0)
    if configured_drawdown_amount > 0:
        candidates.append(configured_drawdown_amount)

    if not candidates:
        return 0.0

    return round(min(candidates), 2)


def _normalize_drawdown_share_value(raw_value: Any) -> Optional[float]:
    try:
        share_value = float(raw_value)
    except (TypeError, ValueError):
        return None

    if share_value <= 0:
        return None

    if share_value > 1.0:
        share_value /= 100.0

    return round(min(1.0, max(0.01, share_value)), 4)


def _normalize_symbol_drawdown_share_overrides(
    raw_overrides: Any,
    broker_name: str = '',
) -> tuple[Dict[str, float], List[str]]:
    normalized: Dict[str, float] = {}
    warnings: List[str] = []

    if not isinstance(raw_overrides, dict):
        return normalized, warnings

    canonical_broker = canonicalize_broker_name(broker_name)
    for raw_symbol, raw_value in raw_overrides.items():
        symbol_key = str(raw_symbol or '').strip()
        if not symbol_key:
            continue

        override_value = raw_value
        if isinstance(raw_value, dict):
            override_value = (
                raw_value.get('drawdownShare')
                or raw_value.get('share')
                or raw_value.get('drawdownPercent')
                or raw_value.get('percent')
            )

        normalized_share = _normalize_drawdown_share_value(override_value)
        if normalized_share is None:
            warnings.append(f"symbolDrawdownShareOverrides ignored invalid value for {symbol_key}")
            continue

        normalized_symbol = normalize_symbol_for_broker(symbol_key, canonical_broker) or symbol_key
        normalized[str(normalized_symbol).upper()] = normalized_share

    return normalized, warnings


EXNESS_DEFAULT_SYMBOL_DRAWDOWN_SHARES = {
    'BTCUSDM': 1.0,
    'ETHUSDM': 1.0,
    'US30M': 0.75,
    'XAUUSDM': 0.5,
    'XAGUSDM': 0.4,
}


def _seed_symbol_drawdown_share_defaults(
    current_overrides: Any,
    symbols: Any,
    broker_name: str = '',
) -> tuple[Dict[str, float], List[str]]:
    normalized_overrides, warnings = _normalize_symbol_drawdown_share_overrides(current_overrides, broker_name)
    normalized_broker = canonicalize_broker_name(broker_name)
    if normalized_broker != 'Exness':
        return normalized_overrides, warnings

    if isinstance(symbols, str):
        symbols = [symbols]
    normalized_symbols = validate_and_correct_symbols(symbols or [], normalized_broker)
    seeded_symbols: List[str] = []
    for symbol in normalized_symbols:
        symbol_key = str(symbol or '').strip().upper()
        if not symbol_key or symbol_key in normalized_overrides:
            continue
        default_share = EXNESS_DEFAULT_SYMBOL_DRAWDOWN_SHARES.get(symbol_key)
        if default_share is None:
            continue
        normalized_overrides[symbol_key] = default_share
        seeded_symbols.append(f"{symbol}={int(default_share * 100)}%")

    if seeded_symbols:
        warnings.append(
            'Applied Exness minimum-lot drawdown defaults for ' + ', '.join(seeded_symbols)
        )

    return normalized_overrides, warnings


def _resolve_symbol_trade_amount_cap(
    bot_config: Dict[str, Any],
    symbol: Optional[str] = None,
    share: float = 0.25,
) -> float:
    """Cap one symbol's trade amount to a fraction of the configured drawdown budget."""
    drawdown_amount = _resolve_effective_drawdown_amount(bot_config)
    resolved_share = _normalize_drawdown_share_value(share) or 0.25

    if symbol and isinstance(bot_config, dict):
        raw_overrides = bot_config.get('symbolDrawdownShareOverrides') or {}
        if isinstance(raw_overrides, dict):
            broker_name = canonicalize_broker_name(bot_config.get('brokerName') or bot_config.get('broker_type') or '')
            normalized_symbol = normalize_symbol_for_broker(str(symbol), broker_name) or str(symbol)
            override_share = raw_overrides.get(str(normalized_symbol).upper()) or raw_overrides.get(str(symbol).upper())
            if override_share is not None:
                resolved_share = _normalize_drawdown_share_value(override_share) or resolved_share

    if drawdown_amount <= 0 or resolved_share <= 0:
        return 0.0

    return round(max(1.0, drawdown_amount * float(resolved_share)), 2)


def _resolve_binance_futures_min_margin_budget(
    broker_conn: Any,
    symbol: str,
    desired_leverage: float,
) -> float:
    if broker_conn is None or not symbol:
        return 0.0

    try:
        market_name = str(getattr(broker_conn, 'market', '') or '').strip().lower()
        if market_name != 'futures':
            return 0.0

        normalize_symbol = getattr(broker_conn, '_normalize_symbol', None)
        instrument = normalize_symbol(symbol) if callable(normalize_symbol) else str(symbol or '').strip().upper()
        if not instrument:
            return 0.0

        get_filters = getattr(broker_conn, '_get_futures_symbol_filters', None)
        if not callable(get_filters):
            return 0.0

        futures_filters = get_filters(instrument)
        if not isinstance(futures_filters, dict):
            return 0.0

        min_notional = _resolve_effective_binance_futures_min_notional(instrument, futures_filters)
        if min_notional <= 0:
            return 0.0

        from decimal import Decimal, ROUND_CEILING

        leverage = max(1.0, float(desired_leverage or 1.0))
        min_margin_budget = min_notional / leverage

        get_price = getattr(broker_conn, '_get_futures_symbol_price', None)
        normalize_quantity = getattr(broker_conn, '_normalize_spot_quantity', None)
        if callable(get_price) and callable(normalize_quantity):
            market_price = _safe_float(get_price(instrument), 0.0)
            if market_price > 0:
                futures_market_lot = futures_filters.get('MARKET_LOT_SIZE', {})
                futures_lot = futures_market_lot or futures_filters.get('LOT_SIZE', {})
                futures_step = _safe_float(futures_lot.get('stepSize'), 0.0)
                futures_min = _safe_float(futures_lot.get('minQty'), 0.0)
                if futures_step <= 0:
                    futures_step = 0.001
                if futures_min <= 0:
                    futures_min = futures_step

                min_quantity = normalize_quantity(
                    min_notional / market_price,
                    futures_step,
                    futures_min,
                    round_up=True,
                )
                if min_quantity > 0:
                    min_margin_budget = max(min_margin_budget, (min_quantity * market_price) / leverage)

        return float(Decimal(str(min_margin_budget)).quantize(Decimal('0.01'), rounding=ROUND_CEILING))
    except Exception as exc:
        logger.debug(f"Could not resolve Binance futures minimum margin budget for {symbol}: {exc}")
        return 0.0


def _resolve_effective_binance_futures_min_notional(
    instrument: Optional[str],
    futures_filters: Optional[Dict[str, Any]],
) -> float:
    if not isinstance(futures_filters, dict):
        return 0.0

    min_notional_filter = futures_filters.get('MIN_NOTIONAL', {})
    notional_filter = futures_filters.get('NOTIONAL', {})
    min_notional = max(
        _safe_float(min_notional_filter.get('notional'), 0.0),
        _safe_float(min_notional_filter.get('minNotional'), 0.0),
        _safe_float(notional_filter.get('notional'), 0.0),
        _safe_float(notional_filter.get('minNotional'), 0.0),
    )

    normalized_instrument = str(instrument or '').strip().upper()
    if normalized_instrument in {'ETHUSDT', 'SOLUSDT'} and min_notional > 20.0:
        # Binance futures exchangeInfo can overstate these symbols at 50 while the
        # order endpoint enforces a 20 USDT floor (-4164).
        return 20.0

    return min_notional


def _resolve_exness_final_symbol_volume_cap(
    bot_config: Dict[str, Any],
    symbol: Optional[str],
    proposed_volume: float = 0.0,
) -> float:
    """Return a capital-aware final MT5 volume cap for Exness orders.

    The last-mile cap should stop runaway sizing, but static micro-caps make
    configured trade capital largely irrelevant on medium and larger accounts.
    This helper scales symbol caps with the bot's effective trade amount while
    preserving tighter ceilings for naturally high-beta instruments.
    """
    normalized_symbol = _normalize_symbol_base(symbol or '')
    symbol_group = _classify_pyramid_symbol_group(normalized_symbol)
    trade_amount_basis = max(
        _safe_float(bot_config.get('effectiveTradeAmount'), 0.0),
        _safe_float(bot_config.get('tradeAmount'), 0.0),
    )
    account_balance_basis = max(
        _safe_float(bot_config.get('accountEquity'), 0.0),
        _safe_float(bot_config.get('accountBalance'), 0.0),
    )

    scale = 1.0
    if trade_amount_basis > 0:
        scale = max(scale, min(4.0, max(1.0, trade_amount_basis / 500.0)))
    if account_balance_basis > 0:
        scale = max(scale, min(3.0, max(1.0, account_balance_basis / 5000.0)))

    group_base_caps = {
        'forex': 0.03,
        'commodities': 0.015,
        'indices': 0.05,
        'crypto': 0.03,
        'stocks': 0.05,
    }
    group_max_caps = {
        'forex': 0.12,
        'commodities': 0.06,
        'indices': 0.20,
        'crypto': 0.15,
        'stocks': 0.20,
    }
    symbol_base_caps = {
        'USDJPY': 0.02,
        'USDCAD': 0.03,
        'USDCHF': 0.03,
        'EURGBP': 0.02,
        'XAUUSD': 0.008,
        'XAGUSD': 0.01,
        'USOIL': 0.01,
        'UKOIL': 0.01,
        'BTCUSD': 0.008,
        'ETHUSD': 0.08,
    }
    symbol_max_caps = {
        'USDJPY': 0.08,
        'USDCAD': 0.10,
        'USDCHF': 0.10,
        'EURGBP': 0.08,
        'XAUUSD': 0.02,
        'XAGUSD': 0.03,
        'USOIL': 0.05,
        'UKOIL': 0.05,
        'BTCUSD': 0.04,
        'ETHUSD': 0.30,
    }

    base_cap = symbol_base_caps.get(normalized_symbol, group_base_caps.get(symbol_group, 0.05))
    hard_cap = symbol_max_caps.get(normalized_symbol, group_max_caps.get(symbol_group, 0.20))
    resolved_cap = min(hard_cap, max(base_cap, base_cap * scale))
    if proposed_volume > 0:
        resolved_cap = max(base_cap, resolved_cap)
    return round(resolved_cap, 4)


def _get_mt5_mid_rate(mt5_api, broker_name: str, symbol_name: str) -> Optional[float]:
    candidates = []
    normalized_symbol = normalize_symbol_for_broker(symbol_name, broker_name)
    if normalized_symbol:
        candidates.append(normalized_symbol)
    if symbol_name not in candidates:
        candidates.append(symbol_name)

    for candidate in candidates:
        try:
            mt5_api.symbol_select(candidate, True)
            tick = mt5_api.symbol_info_tick(candidate)
            if tick is None:
                continue

            bid = float(getattr(tick, 'bid', 0.0) or 0.0)
            ask = float(getattr(tick, 'ask', 0.0) or 0.0)
            if bid > 0 and ask > 0:
                return (bid + ask) / 2.0
            if bid > 0:
                return bid
            if ask > 0:
                return ask
        except Exception:
            continue

    return None


def convert_amount_between_currencies(
    amount: float,
    from_currency: str,
    to_currency: str,
    broker_name: str,
    mt5_api=None,
) -> tuple[float, Optional[str]]:
    from_currency = str(from_currency or '').upper()
    to_currency = str(to_currency or '').upper()

    if amount <= 0 or not from_currency or not to_currency or from_currency == to_currency:
        return amount, None

    if mt5_api is None:
        return amount, None

    direct_symbol = f"{to_currency}{from_currency}"
    direct_rate = _get_mt5_mid_rate(mt5_api, broker_name, direct_symbol)
    if direct_rate and direct_rate > 0:
        converted = amount / direct_rate
        return converted, f"{amount:.2f} {from_currency} -> {converted:.2f} {to_currency} via {direct_symbol}"

    reverse_symbol = f"{from_currency}{to_currency}"
    reverse_rate = _get_mt5_mid_rate(mt5_api, broker_name, reverse_symbol)
    if reverse_rate and reverse_rate > 0:
        converted = amount * reverse_rate
        return converted, f"{amount:.2f} {from_currency} -> {converted:.2f} {to_currency} via {reverse_symbol}"

    return amount, None


def estimate_fixed_trade_volume(
    trade_amount: float,
    symbol: str,
    account_currency: str,
    broker_name: str,
    mt5_api=None,
    market_price: float = 0.0,
    market_name: str = 'spot',
    exchange_leverage: float = 1.0,
) -> tuple[float, Dict[str, Any]]:
    details: Dict[str, Any] = {
        'account_currency': str(account_currency or 'USD').upper(),
        'quote_currency': infer_symbol_quote_currency(symbol),
        'contract_size': None,
        'price': None,
        'method': 'fallback',
        'conversion_note': None,
    }

    if not trade_amount or trade_amount <= 0:
        return 0.0, details

    margin_budget = float(trade_amount)
    quote_amount = margin_budget
    if details['quote_currency']:
        quote_amount, conversion_note = convert_amount_between_currencies(
            margin_budget,
            details['account_currency'],
            details['quote_currency'],
            broker_name,
            mt5_api=mt5_api,
        )
        details['conversion_note'] = conversion_note

    contract_size = 0.0
    current_price = float(market_price or 0.0)
    min_volume = 0.0
    volume_step = 0.0

    if mt5_api is not None:
        try:
            mt5_api.symbol_select(symbol, True)
            sym_info = mt5_api.symbol_info(symbol)
            tick = mt5_api.symbol_info_tick(symbol)
            if sym_info is not None:
                contract_size = float(getattr(sym_info, 'trade_contract_size', 0.0) or 0.0)
                min_volume = float(getattr(sym_info, 'volume_min', 0.0) or 0.0)
                volume_step = float(getattr(sym_info, 'volume_step', 0.0) or 0.0)
            if tick is not None:
                bid = float(getattr(tick, 'bid', 0.0) or 0.0)
                ask = float(getattr(tick, 'ask', 0.0) or 0.0)
                current_price = ask if ask > 0 else bid if bid > 0 else current_price
        except Exception:
            pass

    if mt5_api is not None and current_price > 0:
        probe_volume = max(min_volume, volume_step, 0.01)
        if probe_volume > 0:
            try:
                margin_probe = mt5_api.order_calc_margin(
                    getattr(mt5_api, 'ORDER_TYPE_BUY', 0),
                    symbol,
                    float(probe_volume),
                    current_price,
                )
                margin_probe = float(margin_probe or 0.0)
                if margin_probe > 0:
                    details['contract_size'] = contract_size or None
                    details['price'] = current_price
                    details['method'] = 'mt5-margin-estimate'
                    details['margin_probe_volume'] = probe_volume
                    details['margin_probe_required'] = margin_probe
                    estimated_volume = margin_budget / (margin_probe / probe_volume)
                    return max(estimated_volume, 0.0), details
            except Exception:
                pass

    if contract_size > 0 and current_price > 0:
        details['contract_size'] = contract_size
        details['price'] = current_price
        details['method'] = 'symbol-metadata'
        estimated_volume = quote_amount / (current_price * contract_size)
        return max(estimated_volume, 0.0), details

    normalized_broker = canonicalize_broker_name(broker_name)
    normalized_market = str(market_name or 'spot').strip().lower()
    if normalized_broker == 'Binance' and current_price > 0:
        # NOTE (2026-07-23 profit-erosion fix): quote_amount/trade_amount is sized by
        # _resolve_adaptive_trade_amount() as a small-notional "spot-scale" risk budget
        # (e.g. ~$500 on a multi-thousand-dollar balance) tuned for the bot's tiny
        # $0.80-$1.20 flat profit targets. Previously this branch multiplied that budget
        # by exchange_leverage (10x-25x) to compute the futures order quantity, which
        # inflated the ACTUAL notional exposure by the same factor (e.g. $500 -> $10k+).
        # That let ordinary crypto price moves swing P&L by tens of dollars per trade,
        # blowing straight through HARD_LOSS_PER_TRADE_LIMIT and erasing banked profit in
        # 1-2 trades (observed: bot lost -$31.94 then -$15.88 on ETHUSDT right after
        # peaking at +$5.23). Leverage still reduces the margin required to open the
        # position (see _resolve_binance_futures_min_margin_budget), it must NOT inflate
        # the notional/quantity — so effective_notional stays equal to the budgeted
        # quote_amount regardless of leverage tier.
        effective_notional = quote_amount
        if normalized_market == 'futures':
            details['method'] = 'binance-futures-price-notional'
        else:
            details['method'] = 'binance-price-notional'
        details['contract_size'] = 1.0
        details['price'] = current_price
        estimated_volume = effective_notional / current_price
        return max(estimated_volume, 0.0), details

    estimated_volume = quote_amount / 100000.0
    details['method'] = 'fallback-100000'
    details['price'] = current_price if current_price > 0 else None
    return max(estimated_volume, 0.0), details


def estimate_mt5_stop_loss_risk_volume(
    risk_amount: float,
    symbol: str,
    account_currency: str,
    order_type: str,
    stop_loss_pips: float,
    broker_name: str,
    mt5_api,
    spread_multiplier: float = 2.0,
) -> tuple[float, Dict[str, Any]]:
    details: Dict[str, Any] = {
        'account_currency': str(account_currency or 'USD').upper(),
        'broker_account_currency': str(account_currency or 'USD').upper(),
        'method': 'mt5-stop-loss-risk',
        'conversion_note': None,
        'entry_price': None,
        'stop_price': None,
        'stop_distance': None,
        'probe_volume': None,
        'loss_per_probe_volume': None,
    }

    if not mt5_api or risk_amount <= 0 or stop_loss_pips <= 0:
        return 0.0, details

    side = str(order_type or '').strip().upper()
    if side not in {'BUY', 'SELL'}:
        return 0.0, details

    try:
        mt5_api.symbol_select(symbol, True)
        symbol_info = mt5_api.symbol_info(symbol)
        tick = mt5_api.symbol_info_tick(symbol)
        account_info = mt5_api.account_info()
    except Exception:
        return 0.0, details

    if symbol_info is None or tick is None:
        return 0.0, details

    point = float(getattr(symbol_info, 'point', 0.0) or 0.0)
    if point <= 0:
        return 0.0, details

    bid = float(getattr(tick, 'bid', 0.0) or 0.0)
    ask = float(getattr(tick, 'ask', 0.0) or 0.0)
    spread = max(ask - bid, 0.0)
    entry_price = ask if side == 'BUY' else bid
    if entry_price <= 0:
        entry_price = ask if ask > 0 else bid
    if entry_price <= 0:
        return 0.0, details

    stop_distance = max(float(stop_loss_pips) * point, spread * max(float(spread_multiplier or 0.0), 0.0))
    if stop_distance <= 0:
        return 0.0, details

    digits = int(getattr(symbol_info, 'digits', 5) or 5)
    stop_price = (
        round(entry_price - stop_distance, digits)
        if side == 'BUY'
        else round(entry_price + stop_distance, digits)
    )

    broker_account_currency = str(getattr(account_info, 'currency', '') or details['account_currency']).upper()
    details['broker_account_currency'] = broker_account_currency
    risk_budget = float(risk_amount)
    if broker_account_currency and broker_account_currency != details['account_currency']:
        risk_budget, conversion_note = convert_amount_between_currencies(
            risk_budget,
            details['account_currency'],
            broker_account_currency,
            broker_name,
            mt5_api=mt5_api,
        )
        details['conversion_note'] = conversion_note

    probe_volume = max(
        float(getattr(symbol_info, 'volume_min', 0.0) or 0.0),
        float(getattr(symbol_info, 'volume_step', 0.0) or 0.0),
        0.01,
    )
    mt5_order_type = getattr(mt5_api, f'ORDER_TYPE_{side}', 0 if side == 'BUY' else 1)

    try:
        risk_probe = mt5_api.order_calc_profit(
            mt5_order_type,
            symbol,
            float(probe_volume),
            float(entry_price),
            float(stop_price),
        )
    except Exception:
        return 0.0, details

    loss_per_probe_volume = abs(float(risk_probe or 0.0))
    if loss_per_probe_volume <= 0:
        return 0.0, details

    details['entry_price'] = entry_price
    details['stop_price'] = stop_price
    details['stop_distance'] = stop_distance
    details['probe_volume'] = probe_volume
    details['loss_per_probe_volume'] = loss_per_probe_volume

    estimated_volume = risk_budget * (float(probe_volume) / loss_per_probe_volume)
    return max(estimated_volume, 0.0), details


def estimate_mt5_stop_loss_risk_amount(
    volume: float,
    symbol: str,
    account_currency: str,
    order_type: str,
    stop_loss_pips: float,
    broker_name: str,
    mt5_api,
    spread_multiplier: float = 2.0,
) -> tuple[float, Dict[str, Any]]:
    details: Dict[str, Any] = {
        'account_currency': str(account_currency or 'USD').upper(),
        'broker_account_currency': str(account_currency or 'USD').upper(),
        'method': 'mt5-stop-loss-amount',
        'conversion_note': None,
        'entry_price': None,
        'stop_price': None,
        'stop_distance': None,
        'volume': float(volume or 0.0),
        'risk_amount_broker_currency': None,
    }

    if not mt5_api or volume <= 0 or stop_loss_pips <= 0:
        return 0.0, details

    side = str(order_type or '').strip().upper()
    if side not in {'BUY', 'SELL'}:
        return 0.0, details

    try:
        mt5_api.symbol_select(symbol, True)
        symbol_info = mt5_api.symbol_info(symbol)
        tick = mt5_api.symbol_info_tick(symbol)
        account_info = mt5_api.account_info()
    except Exception:
        return 0.0, details

    if symbol_info is None or tick is None:
        return 0.0, details

    point = float(getattr(symbol_info, 'point', 0.0) or 0.0)
    if point <= 0:
        return 0.0, details

    bid = float(getattr(tick, 'bid', 0.0) or 0.0)
    ask = float(getattr(tick, 'ask', 0.0) or 0.0)
    spread = max(ask - bid, 0.0)
    entry_price = ask if side == 'BUY' else bid
    if entry_price <= 0:
        entry_price = ask if ask > 0 else bid
    if entry_price <= 0:
        return 0.0, details

    stop_distance = max(float(stop_loss_pips) * point, spread * max(float(spread_multiplier or 0.0), 0.0))
    if stop_distance <= 0:
        return 0.0, details

    digits = int(getattr(symbol_info, 'digits', 5) or 5)
    stop_price = (
        round(entry_price - stop_distance, digits)
        if side == 'BUY'
        else round(entry_price + stop_distance, digits)
    )

    broker_account_currency = str(getattr(account_info, 'currency', '') or details['account_currency']).upper()
    details['broker_account_currency'] = broker_account_currency
    mt5_order_type = getattr(mt5_api, f'ORDER_TYPE_{side}', 0 if side == 'BUY' else 1)

    try:
        risk_amount_broker_currency = abs(float(mt5_api.order_calc_profit(
            mt5_order_type,
            symbol,
            float(volume),
            float(entry_price),
            float(stop_price),
        ) or 0.0))
    except Exception:
        return 0.0, details

    if risk_amount_broker_currency <= 0:
        return 0.0, details

    resolved_risk_amount = risk_amount_broker_currency
    if broker_account_currency and broker_account_currency != details['account_currency']:
        resolved_risk_amount, conversion_note = convert_amount_between_currencies(
            risk_amount_broker_currency,
            broker_account_currency,
            details['account_currency'],
            broker_name,
            mt5_api=mt5_api,
        )
        details['conversion_note'] = conversion_note

    details['entry_price'] = entry_price
    details['stop_price'] = stop_price
    details['stop_distance'] = stop_distance
    details['risk_amount_broker_currency'] = round(risk_amount_broker_currency, 2)
    return max(round(float(resolved_risk_amount), 2), 0.0), details


# Initialize trackers
strategy_tracker = StrategyPerformanceTracker()
position_sizer = DynamicPositionSizer(base_size=1.0, min_size=0.1, max_size=5.0)


# ==================== INTELLIGENT OPPORTUNITY SCANNER & REALLOCATION ====================

def scan_all_opportunities(strategy_func, account_id, risk_per_trade, signal_threshold, strategy_cache=None,
                          symbol_universe=None, fallback_slack=20, bot_config=None,
                          allow_raw_signal_fallback=False, symbol_strategy_map: Optional[Dict[str, str]] = None):
    """Scan ALL valid symbols across every asset class for the best trade opportunities.

    Returns a ranked list of (symbol, signal_strength, signal_eval, trade_params) sorted
    by signal strength descending.  The caller decides how many to act on.
    """
    opportunities = []
    near_misses = []
    strategy_cache = strategy_cache if strategy_cache is not None else {}
    symbols_to_scan = list(symbol_universe or sorted(VALID_SYMBOLS))
    total_symbols = len(symbols_to_scan)
    adaptive_floor = _adaptive_signal_threshold_floor(bot_config or {}) if bot_config else 20
    normalized_broker = canonicalize_broker_name(
        (bot_config or {}).get('brokerName') or (bot_config or {}).get('broker_type') or (bot_config or {}).get('broker') or ''
    )
    mode_value = str((bot_config or {}).get('mode') or (bot_config or {}).get('botMode') or 'demo').strip().lower()
    exness_demo_relaxed_fallback = normalized_broker == 'Exness' and mode_value != 'live' and not bool((bot_config or {}).get('is_live'))
    if total_symbols > 0:
        logger.info(
            f"[SCANNER] Starting opportunity scan across {total_symbols} symbol(s) "
            f"at threshold {signal_threshold}"
        )
    for symbol in symbols_to_scan:
        symbol_index = len(opportunities) + len(near_misses) + 1
        try:
            logger.debug(f"[SCANNER] Evaluating symbol {symbol_index}/{total_symbols}: {symbol}")
            symbol_strategy_name = str((symbol_strategy_map or {}).get(symbol) or '').strip()
            strategy_func_for_symbol = STRATEGY_MAP.get(symbol_strategy_name, strategy_func)
            market_data = _enrich_market_data_with_bot_context(bot_config, symbol)

            symbol_performance = None
            if bot_config:
                try:
                    symbol_performance = _evaluate_symbol_performance(bot_config, symbol)
                except Exception:
                    symbol_performance = None
            if symbol_performance:
                verdict = str(symbol_performance.get('verdict') or 'normal')
                if verdict == 'blacklisted' or _is_symbol_blacklist_cooldown_active(bot_config or {}, symbol):
                    logger.debug(
                        f"[SCANNER] Skipping {symbol} due to symbol performance verdict={verdict}"
                    )
                    continue

            trade_params = _get_cached_strategy_params(
                strategy_cache,
                strategy_func_for_symbol,
                symbol,
                account_id,
                risk_per_trade,
                market_data,
                bot_config=bot_config,
            )
            raw_signal = evaluate_real_trade_signal(symbol, market_data)
            raw_strength = raw_signal.get('strength', 0)

            # ─── ML PIPELINE: Full evaluation (regime + score + size + SL/TP) ───
            try:
                from ml_pipeline import get_ml_pipeline
                ml_pipeline = get_ml_pipeline()
                if ml_pipeline:
                    existing_pos = [p.get('symbol', '') for p in _get_open_positions_for_bot(bot_config)] if bot_config else []
                    ml_eval = ml_pipeline.evaluate_entry(symbol, market_data, raw_signal, existing_pos)
                    if ml_eval['should_trade']:
                        raw_signal['ml_pipeline'] = ml_eval
                        raw_signal['entry_reason'] = raw_signal.get('entry_reason', '') + f" | [ML: {ml_eval['reason']}]"
                        logger.debug(f"[MLPipeline] {symbol}: APPROVED — {ml_eval['reason']}")
                    else:
                        raw_signal['ml_pipeline'] = ml_eval
                        if raw_strength >= signal_threshold:
                            logger.debug(f"[MLPipeline] {symbol}: BLOCKED — {ml_eval['reason']}")
            except ImportError:
                pass
            except Exception as e:
                logger.debug(f"[MLPipeline] Error for {symbol}: {e}")
            # ─── END ML PIPELINE ───
            if trade_params is None:
                trade_params = _try_ml_auto_execute_override(
                    symbol,
                    market_data,
                    raw_signal,
                    bot_config=bot_config,
                    existing_trade_params=trade_params,
                )
                if trade_params is not None:
                    strategy_cache[_strategy_cache_key(strategy_func_for_symbol, symbol)] = trade_params
                    opportunities.append({
                        'symbol': symbol,
                        'strength': trade_params.get('signal', {}).get('strength', 100.0),
                        'setupScore': _safe_float(trade_params.get('setupScore'), 0.0),
                        'rr': _safe_float((trade_params.get('signal') or {}).get('rr'), 0.0),
                        'rankingScore': _safe_float(trade_params.get('rankingScore'), 0.0),
                        'signal': trade_params['signal']['signal'],
                        'trend': raw_signal.get('trend', 'UNKNOWN'),
                        'rsi': raw_signal.get('rsi', 50),
                        'trade_params': trade_params,
                        'source': 'ml_auto_execute',
                    })
                    continue
            if trade_params is None:
                if raw_strength >= max(60, signal_threshold):
                    logger.info(
                        f"[SCANNER] {symbol}: raw signal {raw_strength:.0f}/100 "
                        f"({raw_signal.get('signal', 'NEUTRAL')}) met visibility threshold, "
                        f"but the active strategy rejected execution: "
                        f"{raw_signal.get('entry_reason', 'Rejected by strategy')}"
                    )
                raw_fallback_min_strength = max(adaptive_floor, min(signal_threshold, ADAPTIVE_FALLBACK_MIN_STRENGTH))
                raw_setup_eval = _score_signal_setup(
                    symbol,
                    market_data,
                    raw_signal,
                    bot_config=bot_config,
                    strategy_name='Adaptive Scanner Fallback',
                )
                raw_setup_score = _safe_float(raw_setup_eval.get('score'), 0.0)
                exness_raw_override = (
                    exness_demo_relaxed_fallback
                    and raw_strength >= max(signal_threshold + 12.0, 78.0)
                    and raw_setup_score >= 4.5
                )
                fallback_trade_params = None
                if (
                    allow_raw_signal_fallback
                    and raw_strength >= raw_fallback_min_strength
                    and (raw_setup_eval.get('takeTrade', False) or exness_raw_override)
                ):
                    fallback_trade_params = _build_adaptive_raw_trade_params(symbol, market_data, raw_signal, bot_config)
                    fallback_trade_params = _apply_setup_quality_to_trade_params(
                        fallback_trade_params,
                        symbol,
                        market_data,
                        bot_config=bot_config,
                    )
                    if fallback_trade_params is not None and exness_raw_override:
                        logger.info(
                            f"[SCANNER] {symbol}: Exness relaxed raw fallback armed "
                            f"(raw={raw_strength:.0f}/100, setup={raw_setup_score:.1f}/10)"
                        )
                if fallback_trade_params is not None:
                    strategy_cache[_strategy_cache_key(strategy_func_for_symbol, symbol)] = fallback_trade_params
                    opportunities.append({
                        'symbol': symbol,
                        'strength': raw_strength,
                        'setupScore': _safe_float(fallback_trade_params.get('setupScore'), 0.0),
                        'rr': _safe_float((fallback_trade_params.get('signal') or {}).get('rr'), 0.0),
                        'rankingScore': _safe_float(fallback_trade_params.get('rankingScore'), 0.0),
                        'signal': fallback_trade_params['signal']['signal'],
                        'trend': raw_signal.get('trend', 'UNKNOWN'),
                        'rsi': raw_signal.get('rsi', 50),
                        'trade_params': fallback_trade_params,
                        'source': 'adaptive_raw_fallback',
                    })
                    continue
                if raw_strength > 0:
                    near_misses.append({
                        'symbol': symbol,
                        'strength': raw_strength,
                        'signal': raw_signal.get('signal', 'NEUTRAL'),
                        'reason': ', '.join(raw_setup_eval.get('reasons') or []) or raw_signal.get('entry_reason', 'Rejected by strategy'),
                    })
                continue
            strength = trade_params.get('signal', {}).get('strength', 0)
            if strength >= signal_threshold:
                adjusted_ranking = _safe_float(trade_params.get('rankingScore'), 0.0)
                if symbol_performance:
                    adjusted_ranking *= max(0.7, min(_safe_float(symbol_performance.get('multiplier'), 1.0), 1.25))
                opportunities.append({
                    'symbol': symbol,
                    'strength': strength,
                    'setupScore': _safe_float(trade_params.get('setupScore'), 0.0),
                    'rr': _safe_float((trade_params.get('signal') or {}).get('rr'), 0.0),
                    'rankingScore': adjusted_ranking,
                    'signal': trade_params['signal']['signal'],
                    'trend': trade_params['signal'].get('trend', 'UNKNOWN'),
                    'rsi': trade_params['signal'].get('rsi', 50),
                    'trade_params': trade_params,
                    'source': trade_params.get('execution_source', 'strategy'),
                })
            else:
                near_misses.append({
                    'symbol': symbol,
                    'strength': strength,
                    'signal': trade_params['signal'].get('signal', 'NEUTRAL'),
                    'reason': trade_params['signal'].get('entry_reason', 'Below threshold'),
                })
        except Exception as e:
            logger.debug(f"[SCANNER] Error scanning {symbol}: {e}")

        if total_symbols > 25 and symbol_index % 25 == 0:
            logger.info(
                f"[SCANNER] Progress: scanned {symbol_index}/{total_symbols} symbols | "
                f"qualifying={len(opportunities)} | near_misses={len(near_misses)}"
            )
    
    opportunities.sort(
        key=lambda x: (
            _safe_float(x.get('rankingScore'), 0.0),
            _safe_float(x.get('setupScore'), 0.0),
            _safe_float(x.get('strength'), 0.0),
            _safe_float(x.get('rr'), 0.0),
        ),
        reverse=True,
    )
    if not opportunities and signal_threshold > adaptive_floor and fallback_slack > 0:
        fallback_threshold = max(adaptive_floor, signal_threshold - fallback_slack)
        logger.debug(f"[SCANNER] No opportunities above {signal_threshold}. Falling back to {fallback_threshold}.")
        for symbol in symbols_to_scan:
            try:
                symbol_strategy_name = str((symbol_strategy_map or {}).get(symbol) or '').strip()
                strategy_func_for_symbol = STRATEGY_MAP.get(symbol_strategy_name, strategy_func)
                market_data = _enrich_market_data_with_bot_context(bot_config, symbol)
                trade_params = _get_cached_strategy_params(
                    strategy_cache,
                    strategy_func_for_symbol,
                    symbol,
                    account_id,
                    risk_per_trade,
                    market_data,
                    bot_config=bot_config,
                )
                if trade_params is None:
                    continue
                strength = trade_params.get('signal', {}).get('strength', 0)
                if strength >= fallback_threshold:
                    opportunities.append({
                        'symbol': symbol,
                        'strength': strength,
                        'setupScore': _safe_float(trade_params.get('setupScore'), 0.0),
                        'rr': _safe_float((trade_params.get('signal') or {}).get('rr'), 0.0),
                        'rankingScore': _safe_float(trade_params.get('rankingScore'), 0.0),
                        'signal': trade_params['signal']['signal'],
                        'trend': trade_params['signal'].get('trend', 'UNKNOWN'),
                        'rsi': trade_params['signal'].get('rsi', 50),
                        'trade_params': trade_params,
                    })
            except Exception as e:
                logger.debug(f"[SCANNER] Fallback error scanning {symbol}: {e}")
        opportunities.sort(
            key=lambda x: (
                _safe_float(x.get('rankingScore'), 0.0),
                _safe_float(x.get('setupScore'), 0.0),
                _safe_float(x.get('strength'), 0.0),
                _safe_float(x.get('rr'), 0.0),
            ),
            reverse=True,
        )

    if not opportunities and near_misses:
        near_misses.sort(key=lambda x: x['strength'], reverse=True)
        top_near_misses = ', '.join(
            [f"{item['symbol']}:{item['strength']:.0f} {item['signal']} ({item['reason']})" for item in near_misses[:3]]
        )
        logger.info(
            f"[SCANNER] No symbols met threshold {signal_threshold}. Closest setups: {top_near_misses}"
        )

    logger.info(
        f"[SCANNER] ✅ Scan complete: {len(opportunities)} opportunities found, "
        f"{len(near_misses)} near-misses"
    )
    return opportunities

def evaluate_open_positions_for_reallocation(bot_config, opportunities, active_conn, is_mt5, signal_threshold):
    """Evaluate open positions and decide which to close in favour of better opportunities.
    
    Logic:
    - A position is a "close candidate" if its current profit is negative AND
      its symbol's CURRENT signal has reversed or weakened below threshold.
    - We only close if there's a genuinely better opportunity waiting (higher strength).
    - Never close a position that is in profit (let winners run).
    - Respects maxOpenPositions: only close to free a slot if we're at the limit.
    
    Returns list of tickets to close and the replacement symbols.
    """
    tracked = bot_config.get('open_positions', {})
    if not tracked:
        return [], []
    
    max_positions = bot_config.get('effectiveMaxOpenPositions') or bot_config.get('maxOpenPositions', 2)
    open_count = len(tracked)
    
    # If we have room for more positions, no need to close anything
    if open_count < max_positions:
        return [], []
    
    # Build set of symbols we already have open
    open_symbols = set()
    close_candidates = []
    
    for ticket_str, pos in tracked.items():
        pos_symbol = pos.get('symbol', '')
        open_symbols.add(pos_symbol)
        profit = pos.get('profit', 0)
        position_age_minutes = _position_age_minutes(pos.get('entryTime'))
        min_hold_minutes = _minimum_position_hold_minutes(bot_config)
        
        # Never close a winning position
        if profit > 0:
            continue

        # Don't churn scanner-managed positions before they've had time to develop.
        if position_age_minutes < min_hold_minutes:
            continue
        
        # Check if the CURRENT signal for this symbol has weakened
        market_data = commodity_market_data.get(pos_symbol, {})
        current_eval = evaluate_real_trade_signal(pos_symbol, market_data)
        current_strength = current_eval.get('strength', 0)
        current_signal = current_eval.get('signal', 'NEUTRAL')
        
        # Position direction
        pos_type = (pos.get('type', '') or '').upper()
        
        # Signal reversal: we're long but signal says sell, or vice versa
        signal_reversed = (
            (pos_type == 'BUY' and 'SELL' in current_signal) or
            (pos_type == 'SELL' and 'BUY' in current_signal)
        )
        
        # Signal weakened below threshold
        signal_weak = current_strength < signal_threshold * 0.6  # Below 60% of threshold
        
        if signal_reversed or signal_weak:
            close_candidates.append({
                'ticket': ticket_str,
                'symbol': pos_symbol,
                'profit': profit,
                'strength': current_strength,
                'reason': 'SIGNAL_REVERSED' if signal_reversed else 'SIGNAL_WEAKENED',
            })
    
    if not close_candidates:
        return [], []
    
    # Sort by worst profit first (close the biggest losers first)
    close_candidates.sort(key=lambda x: x['profit'])
    
    # Only close if there's a better opportunity not already open
    tickets_to_close = []
    replacement_symbols = []
    
    for candidate in close_candidates:
        # Find the best opportunity that isn't already open
        for opp in opportunities:
            if opp['symbol'] not in open_symbols and opp['symbol'] != candidate['symbol']:
                if opp['strength'] > candidate['strength'] + 15:  # Must be significantly better
                    tickets_to_close.append(candidate['ticket'])
                    replacement_symbols.append(opp['symbol'])
                    open_symbols.add(opp['symbol'])  # Mark as taken
                    break
        
        # Close up to 2 positions per cycle to avoid whipsaw while allowing faster reallocation
        if len(tickets_to_close) >= 2:
            break
    
    return tickets_to_close, replacement_symbols


def execute_intelligent_reallocation(bot_id, bot_config, active_conn, is_mt5, mt5_conn, 
                                       strategy_func, signal_threshold, broker_type, strategy_cache=None,
                                       force_scan=False, symbol_strategy_map: Optional[Dict[str, str]] = None):
    """Main intelligence loop: scan, evaluate, close weak, reallocate to strong.
    
    Called once per trading cycle when intelligentScanner is enabled.
    Returns the list of symbols to trade THIS cycle (may differ from bot's original list).
    """
    if not bot_config.get('intelligentScanner', False) and not force_scan:
        return bot_config.get('symbols', ['EURUSDm'])
    
    account_id = bot_config.get('accountId', '')
    risk_per_trade = bot_config.get('riskPerTrade', 10)
    max_positions = bot_config.get('effectiveMaxOpenPositions') or bot_config.get('maxOpenPositions', 2)
    try:
        cycle_symbol_cap = max(1, int(max_positions or 2))
    except Exception:
        cycle_symbol_cap = 2
    if bot_config.get('managementMode', 'assisted') != 'manual':
        cycle_symbol_cap = min(cycle_symbol_cap, _resolve_assisted_cycle_symbol_cap(bot_config))
    symbol_universe = []
    profile = _normalize_management_profile(bot_config.get('managementProfile'))
    adaptive_offset = int(bot_config.get('adaptiveSignalThresholdOffset') or 0)
    idle_cycles = int(bot_config.get('adaptiveSignalMissCount') or 0)
    mode_value = str(bot_config.get('mode') or bot_config.get('botMode') or 'demo').strip().lower()
    is_live = mode_value == 'live' or bool(bot_config.get('is_live'))
    conservative_entry_mode = (
        profile == 'small_account'
        or bot_config.get('managementState') == 'recovery'
        or is_live
        or int(bot_config.get('consecutiveLosses') or 0) > 0
    )
    fallback_slack = 0 if conservative_entry_mode else min(8, max(5, adaptive_offset))
    normalized_broker_type = canonicalize_broker_name(broker_type)
    fxcm_tradable_symbol_keys: Optional[Set[str]] = None
    fxcm_tradable_lookup_attempted = False

    if normalized_broker_type == 'FXCM':
        fxcm_tradable_symbol_keys = _get_fxcm_tradable_symbol_keys(broker_conn=active_conn)
        fxcm_tradable_lookup_attempted = True

    symbol_universe = build_scanner_symbol_universe(bot_config, fxcm_tradable_symbol_keys)
    
    def _is_symbol_tradeable_now(symbol_to_test: str) -> bool:
        """Best-effort tradability check to avoid selecting closed/illiquid symbols."""
        nonlocal fxcm_tradable_symbol_keys, fxcm_tradable_lookup_attempted
        if normalized_broker_type == 'FXCM':
            if not fxcm_tradable_lookup_attempted:
                fxcm_tradable_symbol_keys = _get_fxcm_tradable_symbol_keys(broker_conn=active_conn)
                fxcm_tradable_lookup_attempted = True
            candidate_keys = _get_fxcm_symbol_candidate_keys(symbol_to_test)
            return fxcm_tradable_symbol_keys is None or bool(candidate_keys & fxcm_tradable_symbol_keys)
        if normalized_broker_type in {'Exness', 'MT5', 'XM', 'XM Global'}:
            if not _is_exness_stock_market_open(symbol_to_test):
                return False
        if not (is_mt5 and mt5_conn and getattr(mt5_conn, 'mt5', None)):
            return True
        try:
            mt5_api = mt5_conn.mt5
            if not mt5_conn.is_symbol_available(symbol_to_test):
                return False
            mt5_api.symbol_select(symbol_to_test, True)
            info = mt5_api.symbol_info(symbol_to_test)
            if info is None:
                return False
            if int(getattr(info, 'trade_mode', 1) or 1) == 0:
                return False
            tick = mt5_api.symbol_info_tick(symbol_to_test)
            if tick is None:
                return normalized_broker_type == 'Exness'
            bid = float(getattr(tick, 'bid', 0.0) or 0.0)
            ask = float(getattr(tick, 'ask', 0.0) or 0.0)
            if bid <= 0 or ask <= 0 or ask <= bid:
                return normalized_broker_type == 'Exness'
            tick_ts = int(getattr(tick, 'time', 0) or 0)
            stale_tick_limit_seconds = 300 if normalized_broker_type == 'Exness' else 180
            if tick_ts > 0 and (time.time() - tick_ts) > stale_tick_limit_seconds:
                return normalized_broker_type == 'Exness'
            return True
        except Exception:
            return True

    # 1. SCAN all symbols for opportunities
    explicit_adaptive_raw_fallback = 'allowAdaptiveRawFallback' in bot_config
    allow_adaptive_raw_fallback = _coerce_bool(
        bot_config.get('allowAdaptiveRawFallback', bot_config.get('intelligentScanner', False)),
        bool(bot_config.get('intelligentScanner', False)),
    )
    if normalized_broker_type == 'Exness' and is_live:
        allow_adaptive_raw_fallback = False
    elif normalized_broker_type == 'Exness' and not is_live and not explicit_adaptive_raw_fallback:
        allow_adaptive_raw_fallback = True
    elif normalized_broker_type == 'Binance' and is_live and not explicit_adaptive_raw_fallback:
        allow_adaptive_raw_fallback = False
    # MANUAL MODE GUARD: do not auto-enable raw-signal fallback when threshold mode is manual
    _raw_fb_manual = str(bot_config.get('signalThresholdMode') or '').strip().lower() == 'manual'
    auto_enable_raw_fallback = (
        not bot_config.get('open_positions')
        and bot_config.get('managementMode', 'assisted') != 'manual'
        and not _raw_fb_manual
        and (
            force_scan
            or bot_config.get('intelligentScanner', False)
            or idle_cycles >= ADAPTIVE_SCANNER_TRIGGER_MISSES
        )
    )
    use_raw_signal_fallback = allow_adaptive_raw_fallback or auto_enable_raw_fallback
    if auto_enable_raw_fallback and not allow_adaptive_raw_fallback:
        logger.info(
            f"🧠 Bot {bot_id}: Auto-enabling conservative raw-signal fallback while idle "
            f"to avoid stale cycles without strategy-approved entries"
        )
    opportunities = scan_all_opportunities(
        strategy_func,
        account_id,
        risk_per_trade,
        signal_threshold,
        strategy_cache,
        symbol_universe=symbol_universe,
        fallback_slack=fallback_slack,
        bot_config=bot_config,
        allow_raw_signal_fallback=use_raw_signal_fallback,
        symbol_strategy_map=symbol_strategy_map,
    )

    tradeable_opportunities = [opp for opp in opportunities if _is_symbol_tradeable_now(opp.get('symbol', ''))]
    if normalized_broker_type == 'Exness' and opportunities and not tradeable_opportunities:
        # Keep scanner-selected Exness candidates in play when MT5 pre-checks are transiently noisy.
        tradeable_opportunities = list(opportunities)
        logger.info(
            f"🧠 Bot {bot_id}: Exness scanner retained {len(tradeable_opportunities)} opportunity/opportunities "
            f"despite transient tradability pre-filter rejection"
        )
    spot_inventory_symbols: Set[str] = set()
    tracked_spot_inventory_symbols: Set[str] = set()
    if normalized_broker_type == 'Binance' and active_conn and getattr(active_conn, 'market', 'spot') != 'futures':
        try:
            tracked_open_positions = bot_config.get('open_positions', {}) if isinstance(bot_config.get('open_positions'), dict) else {}
            tracked_spot_inventory_symbols = {
                str(position.get('symbol') or '').upper()
                for position in tracked_open_positions.values()
                if isinstance(position, dict) and str(position.get('symbol') or '').strip()
            }
            configured_symbols = [str(sym).upper() for sym in (bot_config.get('symbols') or []) if sym]
            candidate_symbols = list(dict.fromkeys(
                configured_symbols + [str(opp.get('symbol') or '').upper() for opp in tradeable_opportunities if opp.get('symbol')]
            ))
            for position_symbol in candidate_symbols:
                inventory_snapshot = _get_binance_spot_inventory_snapshot(active_conn, position_symbol)
                if inventory_snapshot['isSellable']:
                    spot_inventory_symbols.add(inventory_snapshot['symbol'])
        except Exception as inventory_error:
            logger.debug(f"🧠 Bot {bot_id}: Could not inspect Binance spot inventory: {inventory_error}")

        if not spot_inventory_symbols:
            preferred_buy_opportunities = [
                opp for opp in tradeable_opportunities
                if 'BUY' in str(opp.get('signal', '')).upper()
            ]
            if not preferred_buy_opportunities:
                relaxed_buy_threshold = max(
                    _adaptive_signal_threshold_floor(bot_config),
                    min(signal_threshold - 10, ADAPTIVE_FALLBACK_MIN_STRENGTH),
                )
                if relaxed_buy_threshold < signal_threshold:
                    relaxed_buy_scan = scan_all_opportunities(
                        strategy_func,
                        account_id,
                        risk_per_trade,
                        relaxed_buy_threshold,
                        strategy_cache,
                        symbol_universe=symbol_universe,
                        fallback_slack=0,
                        bot_config=bot_config,
                        allow_raw_signal_fallback=use_raw_signal_fallback,
                        symbol_strategy_map=symbol_strategy_map,
                    )
                    preferred_buy_opportunities = [
                        opp for opp in relaxed_buy_scan
                        if 'BUY' in str(opp.get('signal', '')).upper() and _is_symbol_tradeable_now(opp.get('symbol', ''))
                    ]
                    if preferred_buy_opportunities:
                        logger.info(
                            f"🧠 Bot {bot_id}: Binance spot is flat - using relaxed BUY-only scan "
                            f"threshold {signal_threshold} -> {relaxed_buy_threshold}"
                        )
            tradeable_opportunities = preferred_buy_opportunities
        else:
            tradeable_opportunities = [
                opp for opp in tradeable_opportunities
                if 'BUY' in str(opp.get('signal', '')).upper() or str(opp.get('symbol') or '').upper() in tracked_spot_inventory_symbols
            ]
    
    if tradeable_opportunities:
        top_3 = ', '.join([f"{o['symbol']}:{o['strength']:.0f} [{o.get('source', 'strategy')}]" for o in tradeable_opportunities[:3]])
        scanner_mode = 'adaptive' if force_scan and not bot_config.get('intelligentScanner', False) else 'configured'
        logger.info(f"🧠 Bot {bot_id} SCANNER[{scanner_mode}]: Top tradeable opportunities: {top_3} (of {len(tradeable_opportunities)} qualifying)")
    else:
        scanner_mode = 'adaptive' if force_scan and not bot_config.get('intelligentScanner', False) else 'configured'
        if opportunities:
            logger.info(
                f"🧠 Bot {bot_id} SCANNER[{scanner_mode}]: {len(opportunities)} raw opportunities found, "
                f"but none currently tradeable"
            )
        else:
            logger.info(f"🧠 Bot {bot_id} SCANNER[{scanner_mode}]: No qualifying opportunities across {len(symbol_universe)} symbols")
        bot_config['lastScanResults'] = {
            'timestamp': datetime.now().isoformat(),
            'totalScanned': len(symbol_universe),
            'qualifyingOpportunities': 0,
            'scannerMode': 'adaptive' if force_scan and not bot_config.get('intelligentScanner', False) else ('always_on' if bot_config.get('intelligentScanner', False) else 'disabled'),
            'topOpportunities': [],
            'closedForReallocation': 0,
            'cycleSymbols': [],
        }
        return []
    
    # 2. EVALUATE open positions for potential reallocation
    tickets_to_close, replacement_symbols = evaluate_open_positions_for_reallocation(
        bot_config, tradeable_opportunities, active_conn, is_mt5, signal_threshold
    )
    
    # 3. CLOSE underperformers
    for ticket in tickets_to_close:
        tracked_pos = bot_config.get('open_positions', {}).get(ticket, {})
        symbol = tracked_pos.get('symbol', '?')
        profit = tracked_pos.get('profit', 0)
        
        display_currency = str(bot_config.get('displayCurrency') or 'USD').upper()
        logger.info(f"🧠 Bot {bot_id}: CLOSING underperformer {symbol} (ticket {ticket}, P&L: {profit:.2f} {display_currency}) — better opportunity found")
        
        try:
            if is_mt5 and mt5_conn:
                result = mt5_conn.close_position(ticket)
            elif active_conn:
                result = active_conn.close_position(ticket)
            else:
                result = {'success': False, 'error': 'No connection'}
            
            if result.get('success'):
                logger.info(f"🧠 Bot {bot_id}: ✅ Closed {symbol} (ticket {ticket}) for reallocation")
                # Update trade in database
                try:
                    realloc_conn = build_sqlite_connection(timeout=30.0)
                    realloc_cursor = realloc_conn.cursor()
                    realloc_cursor.execute('''
                        UPDATE trades SET profit = ?, status = 'closed', time_close = ?,
                        trade_data = json_set(COALESCE(trade_data, '{}'), '$.closeReason', 'INTELLIGENT_REALLOCATION'),
                        updated_at = ?
                        WHERE ticket = ? AND bot_id = ? AND status = 'open'
                    ''', (profit, datetime.now().isoformat(), datetime.now().isoformat(), str(ticket), bot_id))
                    realloc_conn.commit()
                    realloc_conn.close()
                except Exception as db_e:
                    logger.warning(f"Bot {bot_id}: DB update after realloc close: {db_e}")
                
                # Remove from tracked positions
                if ticket in bot_config.get('open_positions', {}):
                    del bot_config['open_positions'][ticket]
            else:
                logger.warning(f"🧠 Bot {bot_id}: Failed to close {symbol}: {result.get('error')}")
        except Exception as e:
            logger.error(f"🧠 Bot {bot_id}: Exception closing {symbol}: {e}")
    
    # 4. BUILD optimal symbol list for this cycle
    # Start with existing open positions (don't duplicate), then add best new opportunities.
    # NOTE: For Binance SPOT, "positions" are synthesized from token balances by
    # get_positions(). Counting these toward max_positions starves the scanner
    # of slots for new BUYs (every held coin permanently consumes a slot until
    # sold). We therefore DO NOT count spot_inventory_symbols toward the cap;
    # we still retain configured inventory symbols in cycle_symbols so the bot can manage/SELL them.
    current_open_symbols = set(p.get('symbol', '') for p in bot_config.get('open_positions', {}).values())
    configured_symbols = [str(s).upper() for s in (bot_config.get('symbols') or []) if s]
    configured_symbol_set = set(configured_symbols)
    managed_spot_inventory_symbols = [
        sym for sym in spot_inventory_symbols
        if sym in configured_symbol_set and sym in tracked_spot_inventory_symbols
    ]

    # Symbols already tracked (open_positions only) — used for de-duplication.
    # Spot-inventory symbols are NOT pre-seeded into dedup_symbols so that scanner
    # opportunities can fill new-trade slots first; inventory symbols are appended
    # afterward so they remain managed but don't starve the scanner.
    dedup_symbols = set(current_open_symbols)

    # STEP 1: Keep real tracked open positions first.
    cycle_symbols = list(current_open_symbols)

    # Compute remaining new-trade slots based on REAL tracked positions only,
    # so accumulated SPOT inventory cannot block new entries.
    new_trade_slots_used = len(current_open_symbols)

    # STEP 2: Add top scanner opportunities (highest priority, up to cap).
    for opp in tradeable_opportunities:
        if new_trade_slots_used >= cycle_symbol_cap:
            break
        if opp['symbol'] not in dedup_symbols and _is_symbol_tradeable_now(opp['symbol']):
            cycle_symbols.append(opp['symbol'])
            dedup_symbols.add(opp['symbol'])
            new_trade_slots_used += 1

    # STEP 3: Append managed spot-inventory symbols (cap-exempt for SELL management).
    # These come AFTER scanner picks so they don't push scanner results out when sliced.
    for sym in managed_spot_inventory_symbols:
        if sym and sym not in dedup_symbols:
            cycle_symbols.append(sym)
            dedup_symbols.add(sym)
    
    # If we still have slots, add fallback symbols from the active scanner universe.
    fallback_symbols = symbol_universe or bot_config.get('symbols', ['EURUSDm'])
    for s in fallback_symbols:
        if new_trade_slots_used >= cycle_symbol_cap:
            break
        fallback_eval = evaluate_real_trade_signal(s, _enrich_market_data_with_bot_context(bot_config, s))
        fallback_strength = _safe_float(fallback_eval.get('strength'), 0.0)
        adaptive_floor = _adaptive_signal_threshold_floor(bot_config)
        fallback_min_strength = max(adaptive_floor, min(signal_threshold, ADAPTIVE_FALLBACK_MIN_STRENGTH))
        if (
            s not in dedup_symbols
            and _is_symbol_tradeable_now(s)
            and fallback_strength >= fallback_min_strength
        ):
            cycle_symbols.append(s)
            dedup_symbols.add(s)
            new_trade_slots_used += 1

    assisted_cycle_symbol_cap = _resolve_assisted_cycle_symbol_cap(bot_config)
    if bot_config.get('managementMode', 'assisted') != 'manual' and len(cycle_symbols) > assisted_cycle_symbol_cap:
        uncapped_count = len(cycle_symbols)
        cycle_symbols = list(cycle_symbols[:assisted_cycle_symbol_cap])
        logger.info(
            f"🧭 Bot {bot_id}: Reallocation capped cycle symbols to top "
            f"{assisted_cycle_symbol_cap} for risk control: {cycle_symbols} "
            f"(from {uncapped_count})"
        )

    if set(cycle_symbols) != set(bot_config.get('symbols', [])):
        logger.info(f"🧠 Bot {bot_id}: Cycle symbols REALLOCATED: {cycle_symbols} (was: {bot_config.get('symbols', [])})")

    # Store scanner state for the API / UI
    bot_config['lastScanResults'] = {
        'timestamp': datetime.now().isoformat(),
        'totalScanned': len(symbol_universe),
        'qualifyingOpportunities': len(tradeable_opportunities),
        'scannerMode': 'adaptive' if force_scan and not bot_config.get('intelligentScanner', False) else ('always_on' if bot_config.get('intelligentScanner', False) else 'disabled'),
        'topOpportunities': [
            {
                'symbol': o['symbol'],
                'strength': o['strength'],
                'signalStrength': round(_safe_float(o.get('strength'), 0.0), 1),
                'signalPercentage': round(_safe_float(o.get('strength'), 0.0), 1),
                'signal': o['signal'],
                'trend': o['trend'],
            }
            for o in tradeable_opportunities[:5]
        ],
        'closedForReallocation': len(tickets_to_close),
        'cycleSymbols': cycle_symbols,
    }
    
    return cycle_symbols

