_live_mt5_position_cache_time = {}  # {user_id: datetime}

# User-level emergency kill switch. When active, every bot owned by the user
# halts at the next loop iteration and start_bot rejects new starts until cleared.
_user_kill_switches: set = set()
_user_kill_switches_lock = threading.Lock()


def _load_user_kill_switches_from_db() -> None:
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS user_kill_switches (
                user_id TEXT PRIMARY KEY,
                activated_at TEXT,
                reason TEXT
            )
        ''')
        conn.commit()
        cursor.execute('SELECT user_id FROM user_kill_switches')
        rows = cursor.fetchall()
        conn.close()
        with _user_kill_switches_lock:
            _user_kill_switches.clear()
            for row in rows:
                uid = row[0] if not isinstance(row, dict) else row.get('user_id')
                if uid:
                    _user_kill_switches.add(str(uid))
    except Exception as exc:
        try:
            logger.warning(f"Could not load user kill switches: {exc}")
        except Exception:
            pass


def is_user_kill_switch_active(user_id: Optional[str]) -> bool:
    if not user_id:
        return False
    with _user_kill_switches_lock:
        return str(user_id) in _user_kill_switches


def set_user_kill_switch(user_id: str, active: bool, reason: str = '') -> None:
    user_id = str(user_id or '').strip()
    if not user_id:
        return
    with _user_kill_switches_lock:
        if active:
            _user_kill_switches.add(user_id)
        else:
            _user_kill_switches.discard(user_id)
    try:
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS user_kill_switches (
                user_id TEXT PRIMARY KEY,
                activated_at TEXT,
                reason TEXT
            )
        ''')
        if active:
            cursor.execute(
                'INSERT OR REPLACE INTO user_kill_switches (user_id, activated_at, reason) VALUES (?, ?, ?)',
                (user_id, datetime.now().isoformat(), reason or ''),
            )
        else:
            cursor.execute('DELETE FROM user_kill_switches WHERE user_id = ?', (user_id,))
        conn.commit()
        conn.close()
    except Exception as exc:
        try:
            logger.warning(f"Could not persist user kill switch ({user_id}={active}): {exc}")
        except Exception:
            pass

# Per-account MT5 connection locks — allows different accounts on different terminals to connect in parallel
# Key: canonical terminal path string, Value: threading.Lock()
mt5_per_terminal_locks = {}  # {terminal_path: threading.Lock()}
mt5_per_terminal_locks_lock = threading.Lock()  # protects access to mt5_per_terminal_locks dict

def get_mt5_terminal_lock(terminal_path: str) -> 'threading.Lock':
    """Return (or create) a lock for the given MT5 terminal path."""
    key = str(terminal_path or 'default').lower().strip()
    with mt5_per_terminal_locks_lock:
        if key not in mt5_per_terminal_locks:
            mt5_per_terminal_locks[key] = threading.Lock()
        return mt5_per_terminal_locks[key]

def get_bot_start_lock(bot_id: str) -> 'threading.Lock':
    """Return (or create) a per-bot mutex to prevent concurrent /start handling."""
    with bot_start_locks_lock:
        if bot_id not in bot_start_locks:
            bot_start_locks[bot_id] = threading.Lock()
        return bot_start_locks[bot_id]


def mark_bot_start_pending(bot_id: str) -> None:
    """Mark a bot as being started before its background thread becomes alive."""
    bot_start_pending[str(bot_id)] = time.time()


def clear_bot_start_pending(bot_id: str) -> None:
    """Clear pending-start state once the trading loop is alive or startup fails."""
    bot_start_pending.pop(str(bot_id), None)


def is_bot_start_pending(bot_id: str, max_age_seconds: float = 45.0) -> bool:
    """Return True when a bot was just marked for startup and should not be started again."""
    started_at = bot_start_pending.get(str(bot_id))
    if started_at is None:
        return False
    if (time.time() - float(started_at)) > float(max_age_seconds):
        clear_bot_start_pending(bot_id)
        return False
    return True

def get_running_bot_count(exclude_bot_id: str = None, broker_name: Optional[str] = None) -> int:
    """Count currently active bot loops using runtime flags and thread liveness."""
    active_count = 0
    normalized_broker_name = canonicalize_broker_name(broker_name) if broker_name else None
    for current_bot_id, is_running in list(running_bots.items()):
        if exclude_bot_id and current_bot_id == exclude_bot_id:
            continue
        if not is_running:
            thread_obj = bot_threads.get(current_bot_id)
            if not (thread_obj and thread_obj.is_alive()):
                continue
        if normalized_broker_name:
            current_bot = active_bots.get(current_bot_id) or {}
            current_broker_name = canonicalize_broker_name(
                current_bot.get('brokerName') or current_bot.get('broker_type') or ''
            )
            if current_broker_name != normalized_broker_name:
                continue
            active_count += 1
            continue
        active_count += 1
    return active_count

