def _default_strategy_trading_cadence(strategy_name: str, management_profile: str, intelligent_scanner: bool = False) -> Dict[str, int]:
    normalized_strategy = str(strategy_name or 'Trend Following').strip().lower()
    normalized_profile = _normalize_management_profile(management_profile)

    if normalized_strategy == 'scalping':
        return {'tradingMode': 'signal-driven', 'tradingInterval': 30, 'pollInterval': 2}

    if normalized_strategy in {'momentum trading', 'breakout trading', 'bitcoin liquidity sweep', 'funding rate exhaustion', 'session range reversal', 'gold volatility expansion', 'ema pullback ml'}:
        return {'tradingMode': 'signal-driven', 'tradingInterval': 90, 'pollInterval': 8}

    if normalized_strategy in {'swing trend dca', 'ethereum relative strength', 'solana trend continuation'}:
        return {'tradingMode': 'signal-driven', 'tradingInterval': 180, 'pollInterval': 15}

    if normalized_strategy == 'trend following':
        # Lowered from 600s -> 90s: 600s starved Binance bots (10 min between cycles)
        return {'tradingMode': 'signal-driven', 'tradingInterval': 90, 'pollInterval': 8}

    if intelligent_scanner:
        return {'tradingMode': 'signal-driven', 'tradingInterval': 90, 'pollInterval': 8}

    base_interval = 120 if normalized_profile == 'beginner' else 90 if normalized_profile == 'balanced' else 60
    base_poll = 12 if normalized_profile == 'beginner' else 10 if normalized_profile == 'balanced' else 5
    return {'tradingMode': 'signal-driven', 'tradingInterval': base_interval, 'pollInterval': base_poll}


def _minimum_saved_bot_trade_cadence(
    strategy_name: str,
    management_profile: str,
    intelligent_scanner: bool = False,
) -> Dict[str, int]:
    normalized_strategy = str(strategy_name or '').strip().lower()
    normalized_profile = _normalize_management_profile(management_profile)

    if normalized_strategy == 'scalping':
        return {'tradingMode': 'signal-driven', 'tradingInterval': 30, 'pollInterval': 2}

    if normalized_strategy in {'momentum trading', 'breakout trading', 'bitcoin liquidity sweep', 'funding rate exhaustion', 'session range reversal', 'gold volatility expansion', 'ema pullback ml'}:
        if normalized_profile in {'advanced', 'fast_growth'}:
            return {'tradingMode': 'signal-driven', 'tradingInterval': 60, 'pollInterval': 5}
        return {'tradingMode': 'signal-driven', 'tradingInterval': 90, 'pollInterval': 8}

    if normalized_strategy in {'swing trend dca', 'ethereum relative strength', 'solana trend continuation'}:
        return {'tradingMode': 'signal-driven', 'tradingInterval': 300, 'pollInterval': 30}

    if intelligent_scanner:
        if normalized_profile in {'advanced', 'fast_growth'}:
            return {'tradingMode': 'signal-driven', 'tradingInterval': 60, 'pollInterval': 5}
        return {'tradingMode': 'signal-driven', 'tradingInterval': 120, 'pollInterval': 10}

    if normalized_profile in {'advanced', 'fast_growth'}:
        return {'tradingMode': 'signal-driven', 'tradingInterval': 60, 'pollInterval': 5}
    if normalized_profile == 'balanced':
        return {'tradingMode': 'signal-driven', 'tradingInterval': 90, 'pollInterval': 8}
    return {'tradingMode': 'signal-driven', 'tradingInterval': 120, 'pollInterval': 12}


def _adaptive_signal_threshold_floor(bot_config: Dict[str, Any]) -> int:
    broker_name = canonicalize_broker_name(
        bot_config.get('brokerName') or bot_config.get('broker_type') or bot_config.get('broker') or ''
    )
    mode_value = str(bot_config.get('mode') or bot_config.get('botMode') or 'demo').strip().lower()
    is_live = mode_value == 'live' or bool(bot_config.get('is_live'))
    normalized_profile = _normalize_management_profile(bot_config.get('managementProfile'))
    if broker_name == 'FXCM':
        return 10
    if broker_name == 'Binance':
        # Lower the Binance floor so the scanner can still surface moderate setups
        # instead of starving the bot on a narrow set of high-quality only signals.
        return 20

    if broker_name == 'Exness':
        if is_live:
            if normalized_profile == 'small_account' or _is_guarded_small_live_account(bot_config, 2.0):
                return 66
            if normalized_profile in {'advanced', 'fast_growth'}:
                return 60
            return 65
        if normalized_profile == 'small_account':
            return 40
        if normalized_profile in {'advanced', 'fast_growth'}:
            return 35
        # Balanced/beginner: raise floor from 35-40 to 45 to filter out
        # low-quality signals that lose more than they win (per trade history analysis)
        return 45

    strategy_name = str(bot_config.get('strategy') or '').strip().lower()
    configured_symbols = bot_config.get('symbols') or []
    base_symbols = {
        _normalize_symbol_base(symbol)
        for symbol in configured_symbols
        if _normalize_symbol_base(symbol)
    }

    if base_symbols and base_symbols.issubset(SMALL_LIVE_ACCOUNT_OPTIONAL_CRYPTO_BASE_SYMBOLS):
        return 1
    if strategy_name in {'scalping', 'momentum trading'}:
        return 1   # AGGRESSIVE: Lower floor for faster trading
    if strategy_name in {'trend following', 'swing trend dca'}:
        return 1   # AGGRESSIVE: Lower floor for faster trading
    if _normalize_management_profile(bot_config.get('managementProfile')) == 'small_account':
        return 1   # AGGRESSIVE: Lower floor for faster trading
    return 1       # AGGRESSIVE: Global floor 1 for all strategies


def _effective_signal_threshold_for_display(bot_config: Dict[str, Any]) -> int:
    floor = _adaptive_signal_threshold_floor(bot_config or {})
    broker_name = canonicalize_broker_name(
        bot_config.get('brokerName') or bot_config.get('broker_type') or bot_config.get('broker') or ''
    )
    mode_value = str(bot_config.get('mode') or bot_config.get('botMode') or 'demo').strip().lower()
    is_demo = mode_value != 'live' and not bool(bot_config.get('is_live'))

    # Runtime trade loop hard-clamps Binance demo to floor; mirror that in every API payload.
    if broker_name == 'Binance' and is_demo:
        return floor

    raw_effective = int(
        _safe_float(
            bot_config.get('effectiveSignalThreshold', bot_config.get('signalThreshold', floor)),
            floor,
        )
    )
    if raw_effective <= 0 or raw_effective > 100:
        return floor
    return max(floor, raw_effective)


def _crypto_only_signal_threshold(
    symbols: List[Any],
    broker_name: Any = None,
    market_name: Any = None,
) -> Optional[int]:
    base_symbols = {
        _normalize_symbol_base(symbol)
        for symbol in (symbols or [])
        if _normalize_symbol_base(symbol)
    }
    if not base_symbols or not base_symbols.issubset(SMALL_LIVE_ACCOUNT_OPTIONAL_CRYPTO_BASE_SYMBOLS):
        return None

    normalized_broker = canonicalize_broker_name(broker_name)
    normalized_market = str(market_name or 'spot').strip().lower()
    if normalized_broker == 'Binance':
        return 18 if normalized_market == 'futures' else 24
    return 55


def _resolve_runtime_trade_cadence(
    bot_config: Dict[str, Any],
    strategy_name: str,
    signal_symbol: Optional[str],
    signal_strength: float,
) -> Dict[str, int]:
    base_interval = int(bot_config.get('tradingInterval') or 300)
    base_poll = int(bot_config.get('pollInterval') or 15)
    strategy_label = str(strategy_name or '').strip().lower()
    base_symbol = _normalize_symbol_base(signal_symbol or '')
    market_data = _get_market_data_for_symbol(signal_symbol or '') if signal_symbol else {}
    volatility = str(market_data.get('volatility') or 'Medium').title()

    target_interval = base_interval
    target_poll = base_poll

    if base_symbol in {'BTCUSD', 'BTCUSDT', 'ETHUSD', 'ETHUSDT', 'SOLUSD', 'SOLUSDT'}:
        if signal_strength >= 80:
            target_interval, target_poll = 120, 3
        elif signal_strength >= 70:
            target_interval, target_poll = 180, 5
        else:
            target_interval, target_poll = 240, 8
    elif strategy_label in {'trend following', 'swing trend dca', 'ethereum relative strength', 'solana trend continuation'}:
        if signal_strength >= 75:
            target_interval, target_poll = 180, 10
        elif signal_strength >= 65:
            target_interval, target_poll = 240, 15
        else:
            target_interval, target_poll = 300, 20
    elif strategy_label == 'scalping':
        if signal_strength >= 75:
            target_interval, target_poll = 120, 3
        else:
            target_interval, target_poll = 180, 5
    else:
        if signal_strength >= 75:
            target_interval, target_poll = 180, 8
        elif signal_strength >= 65:
            target_interval, target_poll = 240, 12

    if volatility == 'Very High':
        target_interval = min(target_interval, 120 if base_symbol in {'BTCUSD', 'BTCUSDT', 'ETHUSD', 'ETHUSDT', 'SOLUSD', 'SOLUSDT'} else 180)
        target_poll = min(target_poll, 4 if base_symbol in {'BTCUSD', 'BTCUSDT', 'ETHUSD', 'ETHUSDT', 'SOLUSD', 'SOLUSDT'} else 8)
    elif volatility == 'High':
        target_interval = min(target_interval, 180 if base_symbol in {'BTCUSD', 'BTCUSDT', 'ETHUSD', 'ETHUSDT', 'SOLUSD', 'SOLUSDT'} else 240)
        target_poll = min(target_poll, 6 if base_symbol in {'BTCUSD', 'BTCUSDT', 'ETHUSD', 'ETHUSDT', 'SOLUSD', 'SOLUSDT'} else 10)

    # Treat the saved cadence as the maximum wait between scans so migrated
    # high-frequency bots are not slowed back down by adaptive runtime logic.
    target_interval = min(target_interval, base_interval)
    target_poll = min(target_poll, base_poll)

    target_interval = max(60, min(target_interval, 600))
    target_poll = max(2, min(target_poll, max(2, target_interval // 2)))
    return {
        'tradingInterval': target_interval,
        'pollInterval': target_poll,
    }


def _max_trades_per_30_minutes(bot_config: Dict[str, Any], strategy_name: str) -> int:
    profile = _normalize_management_profile(bot_config.get('managementProfile'))
    normalized_strategy = str(strategy_name or '').strip().lower()
    broker_name = canonicalize_broker_name(
        bot_config.get('brokerName') or bot_config.get('broker_type') or bot_config.get('broker') or ''
    )

    if broker_name == 'Exness':
        if normalized_strategy == 'scalping':
            return 6
        if profile in {'advanced', 'fast_growth'}:
            return 5
        if profile == 'balanced':
            return 4
        return 4

    if normalized_strategy == 'scalping':
        return 10
    if profile in {'advanced', 'fast_growth'}:
        return 8
    if profile == 'balanced':
        return 7
    return 6


def _normalize_profit_protection_config(config: Optional[Dict[str, Any]]) -> Dict[str, Any]:
    raw = dict(config) if isinstance(config, dict) else {}
    normalized = dict(DEFAULT_PROFIT_PROTECTION_CONFIG)
    normalized['enabled'] = _coerce_bool(raw.get('enabled', normalized['enabled']), normalized['enabled'])
    normalized['activationPercent'] = max(0.5, min(50.0, _safe_float(raw.get('activationPercent', raw.get('activation_percent', normalized['activationPercent'])), normalized['activationPercent'])))
    normalized['activationMinProfit'] = max(0.0, _safe_float(raw.get('activationMinProfit', raw.get('activation_min_profit', normalized['activationMinProfit'])), normalized['activationMinProfit']))
    normalized['portfolioActivationMinProfit'] = max(0.0, _safe_float(raw.get('portfolioActivationMinProfit', raw.get('portfolio_activation_min_profit', normalized['portfolioActivationMinProfit'])), normalized['portfolioActivationMinProfit']))
    normalized['closeLosingPositionsWithProfitablePeers'] = _coerce_bool(
        raw.get(
            'closeLosingPositionsWithProfitablePeers',
            raw.get('close_losing_positions_with_profitable_peers', normalized.get('closeLosingPositionsWithProfitablePeers', True)),
        ),
        normalized.get('closeLosingPositionsWithProfitablePeers', True),
    )
    normalized['peakProfitHardLockShare'] = max(
        0.90,
        min(
            0.99,
            _safe_float(
                raw.get(
                    'peakProfitHardLockShare',
                    raw.get('peak_profit_hard_lock_share', normalized.get('peakProfitHardLockShare', 0.95)),
                ),
                normalized.get('peakProfitHardLockShare', 0.95),
            ),
        ),
    )
    # minLockedProfit: floor = DEFAULT (user may raise it, never lower it)
    normalized['minLockedProfit'] = max(
        normalized['minLockedProfit'],
        _safe_float(raw.get('minLockedProfit', raw.get('min_locked_profit', normalized['minLockedProfit'])), normalized['minLockedProfit']),
    )
    normalized['marginTakeProfitPercent'] = max(0.0, min(200.0, _safe_float(raw.get('marginTakeProfitPercent', raw.get('margin_take_profit_percent', normalized['marginTakeProfitPercent'])), normalized['marginTakeProfitPercent'])))
    # retraceClosePercent: ceiling = DEFAULT (user may tighten it below DEFAULT, never loosen above it)
    normalized['retraceClosePercent'] = min(
        normalized['retraceClosePercent'],
        max(
            5.0,
            min(
                MAX_PEAK_PROFIT_RETRACE_PERCENT,
                _safe_float(
                    raw.get('retraceClosePercent', raw.get('retrace_close_percent', normalized['retraceClosePercent'])),
                    normalized['retraceClosePercent'],
                ),
            ),
        ),
    )
    normalized['switchOnReversal'] = _coerce_bool(raw.get('switchOnReversal', raw.get('switch_on_reversal', normalized['switchOnReversal'])), normalized['switchOnReversal'])
    normalized['adaptiveByVolatility'] = _coerce_bool(raw.get('adaptiveByVolatility', raw.get('adaptive_by_volatility', normalized['adaptiveByVolatility'])), normalized['adaptiveByVolatility'])
    normalized['breakEvenLockEnabled'] = _coerce_bool(raw.get('breakEvenLockEnabled', raw.get('break_even_lock_enabled', normalized['breakEvenLockEnabled'])), normalized['breakEvenLockEnabled'])
    # breakEvenBufferProfit: floor = DEFAULT (must earn at least DEFAULT before a break-even close)
    normalized['breakEvenBufferProfit'] = max(
        normalized['breakEvenBufferProfit'],
        _safe_float(raw.get('breakEvenBufferProfit', raw.get('break_even_buffer_profit', normalized['breakEvenBufferProfit'])), normalized['breakEvenBufferProfit']),
    )
    # breakEvenActivationShare: ceiling = DEFAULT (arms protection sooner; user may arm even sooner, never later)
    normalized['breakEvenActivationShare'] = min(
        normalized['breakEvenActivationShare'],
        max(0.1, _safe_float(raw.get('breakEvenActivationShare', raw.get('break_even_activation_share', normalized['breakEvenActivationShare'])), normalized['breakEvenActivationShare'])),
    )
    normalized['protectedSymbolCooldownMinutes'] = max(0.0, min(30.0, _safe_float(raw.get('protectedSymbolCooldownMinutes', raw.get('protected_symbol_cooldown_minutes', normalized['protectedSymbolCooldownMinutes'])), normalized['protectedSymbolCooldownMinutes'])))
    normalized['loserRotationMinLoss'] = max(0.0, min(100.0, _safe_float(raw.get('loserRotationMinLoss', raw.get('loser_rotation_min_loss', normalized.get('loserRotationMinLoss', 0.0))), normalized.get('loserRotationMinLoss', 0.0))))
    normalized['zeroLossLockEnabled'] = _coerce_bool(raw.get('zeroLossLockEnabled', raw.get('zero_loss_lock_enabled', normalized.get('zeroLossLockEnabled', True))), normalized.get('zeroLossLockEnabled', True))
    normalized['neverNegativeAfterProfitEnabled'] = _coerce_bool(
        raw.get(
            'neverNegativeAfterProfitEnabled',
            raw.get('never_negative_after_profit_enabled', normalized.get('neverNegativeAfterProfitEnabled', True)),
        ),
        normalized.get('neverNegativeAfterProfitEnabled', True),
    )
    normalized['neverNegativeActivationProfit'] = max(
        0.25,
        min(
            25.0,
            _safe_float(
                raw.get(
                    'neverNegativeActivationProfit',
                    raw.get('never_negative_activation_profit', normalized.get('neverNegativeActivationProfit', 1.0)),
                ),
                normalized.get('neverNegativeActivationProfit', 1.0),
            ),
        ),
    )
    normalized['neverNegativeFloorProfit'] = max(
        0.0,
        min(
            10.0,
            _safe_float(
                raw.get(
                    'neverNegativeFloorProfit',
                    raw.get('never_negative_floor_profit', normalized.get('neverNegativeFloorProfit', 0.25)),
                ),
                normalized.get('neverNegativeFloorProfit', 0.25),
            ),
        ),
    )
    normalized['stallProfitGivebackPercent'] = max(
        10.0,
        min(
            MAX_PEAK_PROFIT_RETRACE_PERCENT,
            _safe_float(
                raw.get(
                    'stallProfitGivebackPercent',
                    raw.get('stall_profit_giveback_percent', normalized.get('stallProfitGivebackPercent', 30.0)),
                ),
                normalized.get('stallProfitGivebackPercent', 30.0),
            ),
        ),
    )
    normalized['stallSignalStrengthFloor'] = max(
        30.0,
        min(
            90.0,
            _safe_float(
                raw.get(
                    'stallSignalStrengthFloor',
                    raw.get('stall_signal_strength_floor', normalized.get('stallSignalStrengthFloor', 55.0)),
                ),
                normalized.get('stallSignalStrengthFloor', 55.0),
            ),
        ),
    )
    normalized['stallMinTpProgress'] = max(
        0.30,
        min(
            0.95,
            _safe_float(
                raw.get(
                    'stallMinTpProgress',
                    raw.get('stall_min_tp_progress', normalized.get('stallMinTpProgress', 0.70)),
                ),
                normalized.get('stallMinTpProgress', 0.70),
            ),
        ),
    )
    normalized['minimumHoldMinutes'] = max(0.0, min(60.0, _safe_float(raw.get('minimumHoldMinutes', raw.get('minimum_hold_minutes', normalized.get('minimumHoldMinutes', 1.0))), normalized.get('minimumHoldMinutes', 1.0))))
    normalized['peakProfitHardLockShare'] = max(
        MIN_PEAK_PROFIT_LOCK_SHARE,
        _safe_float(normalized.get('peakProfitHardLockShare'), MIN_PEAK_PROFIT_LOCK_SHARE),
    )
    normalized['minTimeInPositionSeconds'] = max(
        0.0,
        _safe_float(
            raw.get('minTimeInPositionSeconds', raw.get('min_time_in_position_seconds', MIN_TIME_IN_POSITION_SECONDS)),
            MIN_TIME_IN_POSITION_SECONDS,
        ),
    )
    return normalized


def _estimate_take_profit_progress_ratio(
    tracked: Dict[str, Any],
    current_position: Dict[str, Any],
) -> Optional[float]:
    entry_price = _safe_float(
        tracked.get('entryPrice', tracked.get('openPrice', tracked.get('price', 0.0))),
        0.0,
    )
    current_price = _safe_float(
        current_position.get('currentPrice', current_position.get('marketPrice', current_position.get('price_current', tracked.get('currentPrice', 0.0)))),
        0.0,
    )
    take_profit_price = _safe_float(
        current_position.get('tp', tracked.get('takeProfitPrice', tracked.get('tp', tracked.get('take_profit_price', 0.0)))),
        0.0,
    )
    position_type = str(current_position.get('type') or tracked.get('type') or '').upper()

    if entry_price <= 0 or current_price <= 0 or take_profit_price <= 0 or not position_type:
        return None

    if 'BUY' in position_type:
        target_distance = take_profit_price - entry_price
        progress_distance = current_price - entry_price
    else:
        target_distance = entry_price - take_profit_price
        progress_distance = entry_price - current_price

    if target_distance <= 0:
        return None

    return max(0.0, min(1.5, progress_distance / target_distance))


def _promote_profit_protection_bucket(bucket: str) -> str:
    order = ['very_low', 'low', 'medium', 'high', 'very_high']
    try:
        return order[min(order.index(bucket) + 1, len(order) - 1)]
    except ValueError:
        return bucket


def _demote_profit_protection_bucket(bucket: str) -> str:
    order = ['very_low', 'low', 'medium', 'high', 'very_high']
    try:
        return order[max(order.index(bucket) - 1, 0)]
    except ValueError:
        return bucket


MAJOR_CRYPTO_RUNNER_TARGET_PCTS = {
    'BTCUSDT': 0.0040,
    'ETHUSDT': 0.0045,
    'SOLUSDT': 0.0055,
    'BTCUSD': 0.0040,
    'ETHUSD': 0.0045,
    'SOLUSD': 0.0055,
}


def _resolve_major_crypto_runner_profile(
    bot_config: Dict[str, Any],
    symbol: Optional[str],
    *,
    estimated_notional: float = 0.0,
) -> Optional[Dict[str, float]]:
    base_symbol = _normalize_symbol_base(symbol or '')
    target_pct = MAJOR_CRYPTO_RUNNER_TARGET_PCTS.get(base_symbol)
    if target_pct is None:
        return None

    trade_amount_basis = max(
        _safe_float(estimated_notional, 0.0),
        _safe_float(bot_config.get('effectiveTradeAmount'), 0.0),
        _safe_float(bot_config.get('tradeAmount'), 0.0),
    )
    account_balance_basis = max(
        _safe_float(bot_config.get('accountEquity'), 0.0),
        _safe_float(bot_config.get('accountBalance'), 0.0),
    )
    if trade_amount_basis <= 0 and account_balance_basis > 0:
        trade_amount_basis = max(40.0, account_balance_basis * 0.16)
    if trade_amount_basis <= 0:
        return None

    runner_profit_floor = round(max(0.4, min(60.0, trade_amount_basis * target_pct)), 2)
    locked_profit_floor = round(max(0.2, min(runner_profit_floor, runner_profit_floor * 0.45)), 2)
    break_even_buffer = round(max(0.2, runner_profit_floor * 0.4), 2)

    if base_symbol in {'BTCUSDT', 'BTCUSD'}:
        minimum_hold_minutes = 7.0
        retrace_close_percent = 18.0
        protected_cooldown_minutes = 8.0
    elif base_symbol in {'ETHUSDT', 'ETHUSD'}:
        minimum_hold_minutes = 6.0
        retrace_close_percent = 20.0
        protected_cooldown_minutes = 7.0
    else:
        minimum_hold_minutes = 5.0
        retrace_close_percent = 22.0
        protected_cooldown_minutes = 6.0

    return {
        'activationMinProfit': runner_profit_floor,
        'minLockedProfit': locked_profit_floor,
        'breakEvenBufferProfit': break_even_buffer,
        'breakEvenActivationShare': 0.7,
        'minimumHoldMinutes': minimum_hold_minutes,
        'retraceClosePercent': retrace_close_percent,
        'protectedSymbolCooldownMinutes': protected_cooldown_minutes,
        'peakProfitHardLockShare': 0.96,
        'spotMinNetExitAmount': runner_profit_floor,
    }


def _classify_profit_protection_bucket(symbol: str, market_data: Optional[Dict[str, Any]] = None) -> str:
    base_symbol = _normalize_symbol_base(symbol)
    params = _get_effective_symbol_params(base_symbol, market_data)
    volatility_high = max(_safe_float(params.get('volatility_high'), 1.0), 0.01)
    volatility_low = max(_safe_float(params.get('volatility_low'), 0.1), 0.0)
    atr_multiplier = _safe_float(params.get('atr_multiplier'), 1.5)
    live_volatility = max(_safe_float((market_data or {}).get('volatility_pct'), volatility_low), 0.0)

    if base_symbol in {'BTCUSD', 'ETHUSD', 'TSLA', 'NVDA', 'AMD'}:
        bucket = 'very_high'
    elif atr_multiplier >= 1.7 or volatility_high >= 2.0:
        bucket = 'high'
    elif atr_multiplier >= 1.45 or volatility_high >= 0.8:
        bucket = 'medium'
    elif atr_multiplier <= 1.15 and volatility_high <= 0.15:
        bucket = 'very_low'
    else:
        bucket = 'low'

    if live_volatility >= volatility_high * 1.1:
        bucket = _promote_profit_protection_bucket(bucket)
    elif live_volatility <= max(volatility_low * 1.05, 0.01):
        bucket = _demote_profit_protection_bucket(bucket)

    return bucket


def _exness_loser_rotation_min_loss_for_symbol(symbol: str, volatility_bucket: Optional[str] = None) -> float:
    base_symbol = _normalize_symbol_base(symbol)
    symbol_upper = base_symbol.upper()
    forex_currencies = {'EUR', 'GBP', 'USD', 'JPY', 'CHF', 'AUD', 'NZD', 'CAD'}

    if base_symbol in {'GBPUSD', 'AUDUSD'}:
        return 0.9
    if base_symbol == 'XAUUSD':
        return 1.5

    if len(symbol_upper) == 6 and symbol_upper[:3] in forex_currencies and symbol_upper[3:] in forex_currencies:
        return 1.25

    if any(token in symbol_upper for token in {'BTC', 'ETH', 'XRP', 'SOL', 'ADA', 'DOGE', 'LTC', 'BNB'}):
        return 4.0

    if any(token in symbol_upper for token in {'SPX', 'NDX', 'USTEC', 'NAS', 'US30', 'DOW', 'GER', 'UK100', 'JP225', 'AUS200'}):
        return 3.5

    if any(token in symbol_upper for token in {'XAU', 'XAG', 'OIL', 'BRENT', 'WTI', 'GAS'}):
        return 2.5

    if volatility_bucket == 'very_high':
        return 3.5
    if volatility_bucket == 'high':
        return 3.0
    if volatility_bucket == 'medium':
        return 2.5
    if volatility_bucket == 'low':
        return 2.0
    return 1.75


def _resolve_profit_protection_for_symbol(
    bot_config: Dict[str, Any],
    symbol: str,
    market_data: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    normalized = _normalize_profit_protection_config(bot_config.get('profitProtection'))
    resolved = dict(normalized)
    resolved['volatilityBucket'] = None

    if not normalized.get('adaptiveByVolatility', True):
        return resolved

    bucket = _classify_profit_protection_bucket(symbol, market_data)
    profile = PROFIT_PROTECTION_VOLATILITY_PROFILES.get(bucket, PROFIT_PROTECTION_VOLATILITY_PROFILES['medium'])
    resolved['activationMinProfit'] = max(
        _safe_float(normalized.get('activationMinProfit'), 0.0),
        _safe_float(profile.get('activationMinProfit'), 0.0),
    )
    resolved['minLockedProfit'] = max(
        _safe_float(normalized.get('minLockedProfit'), 0.0),
        _safe_float(profile.get('minLockedProfit'), 0.0),
    )
    resolved['retraceClosePercent'] = min(
        _safe_float(normalized.get('retraceClosePercent'), 35.0),
        _safe_float(profile.get('retraceClosePercent'), 35.0),
    )
    resolved['breakEvenBufferProfit'] = max(
        _safe_float(normalized.get('breakEvenBufferProfit'), 0.0),
        _safe_float(profile.get('breakEvenBufferProfit'), 0.0),
    )
    resolved['breakEvenActivationShare'] = max(
        _safe_float(normalized.get('breakEvenActivationShare'), 0.5),
        _safe_float(profile.get('breakEvenActivationShare'), 0.5),
    )

    account_balance = max(
        _safe_float(bot_config.get('accountBalance'), 0.0),
        _safe_float(bot_config.get('accountEquity'), 0.0),
    )
    account_currency = str(bot_config.get('displayCurrency') or 'USD').upper()
    small_account_threshold = _get_small_live_account_threshold(account_currency)
    is_small_account = _normalize_management_profile(bot_config.get('managementProfile')) == 'small_account'
    broker_name = canonicalize_broker_name(
        bot_config.get('brokerName') or bot_config.get('broker_type') or bot_config.get('broker') or ''
    )
    base_symbol = _normalize_symbol_base(symbol)
    exness_guarded_small_live = bool(
        broker_name == 'Exness'
        and account_balance > 0
        and account_balance <= small_account_threshold * 1.5
        and (is_small_account or _is_guarded_small_live_account(bot_config, 1.5))
    )
    if broker_name == 'Exness':
        resolved['loserRotationMinLoss'] = max(
            _safe_float(resolved.get('loserRotationMinLoss'), 0.0),
            _exness_loser_rotation_min_loss_for_symbol(base_symbol, bucket),
        )
        if _is_exness_forex_symbol(base_symbol):
            # Keep forex trades out of spread-noise churn by requiring a more
            # meaningful move before profit protection is allowed to react.
            resolved['activationMinProfit'] = max(_safe_float(resolved.get('activationMinProfit'), 0.0), 4.0)
            resolved['minLockedProfit'] = max(_safe_float(resolved.get('minLockedProfit'), 0.0), 6.0)
            resolved['breakEvenBufferProfit'] = max(_safe_float(resolved.get('breakEvenBufferProfit'), 0.0), 12.0)
            resolved['minimumHoldMinutes'] = max(_safe_float(resolved.get('minimumHoldMinutes'), 0.0), 20.0)
            resolved['protectedSymbolCooldownMinutes'] = max(_safe_float(resolved.get('protectedSymbolCooldownMinutes'), 5.0), 15.0)

    if exness_guarded_small_live and _is_exness_forex_symbol(base_symbol):
        resolved['activationMinProfit'] = max(0.75, min(_safe_float(resolved.get('activationMinProfit'), 4.0), 1.5))
        resolved['minLockedProfit'] = max(0.45, min(_safe_float(resolved.get('minLockedProfit'), 6.0), 0.9))
        resolved['peakProfitHardLockShare'] = max(_safe_float(resolved.get('peakProfitHardLockShare'), 0.95), 0.96)
        resolved['retraceClosePercent'] = min(_safe_float(resolved.get('retraceClosePercent'), 35.0), 10.0)
        resolved['breakEvenBufferProfit'] = max(0.35, min(_safe_float(resolved.get('breakEvenBufferProfit'), 12.0), 0.8))
        resolved['breakEvenActivationShare'] = min(_safe_float(resolved.get('breakEvenActivationShare'), 0.5), 0.2)
        resolved['minimumHoldMinutes'] = min(_safe_float(resolved.get('minimumHoldMinutes'), 20.0), 6.0)
        resolved['protectedSymbolCooldownMinutes'] = max(_safe_float(resolved.get('protectedSymbolCooldownMinutes'), 5.0), 12.0)
        resolved['neverNegativeActivationProfit'] = max(0.25, min(_safe_float(resolved.get('neverNegativeActivationProfit'), 1.0), 0.4))
        resolved['neverNegativeFloorProfit'] = max(0.08, min(_safe_float(resolved.get('neverNegativeFloorProfit'), 0.25), 0.15))
        resolved['stallProfitGivebackPercent'] = min(_safe_float(resolved.get('stallProfitGivebackPercent'), 30.0), 18.0)
        resolved['stallSignalStrengthFloor'] = max(_safe_float(resolved.get('stallSignalStrengthFloor'), 55.0), 60.0)
        resolved['stallMinTpProgress'] = max(_safe_float(resolved.get('stallMinTpProgress'), 0.70), 0.5)

    if base_symbol in {'GBPUSD', 'AUDUSD'}:
        current_rotation_loss = _safe_float(resolved.get('loserRotationMinLoss'), 0.0)
        resolved['loserRotationMinLoss'] = 0.9 if current_rotation_loss <= 0 else min(current_rotation_loss, 0.9)
        resolved['activationMinProfit'] = max(1.0, min(_safe_float(resolved.get('activationMinProfit'), 4.0), 1.8))
        resolved['minLockedProfit'] = max(0.8, min(_safe_float(resolved.get('minLockedProfit'), 6.0), 1.2))
        resolved['peakProfitHardLockShare'] = max(_safe_float(resolved.get('peakProfitHardLockShare'), 0.95), 0.97)
        resolved['retraceClosePercent'] = min(_safe_float(resolved.get('retraceClosePercent'), 35.0), 8.0)
        resolved['breakEvenBufferProfit'] = max(0.6, min(_safe_float(resolved.get('breakEvenBufferProfit'), 12.0), 1.8))
        resolved['breakEvenActivationShare'] = max(0.12, min(_safe_float(resolved.get('breakEvenActivationShare'), 0.5), 0.22))
        resolved['minimumHoldMinutes'] = min(_safe_float(resolved.get('minimumHoldMinutes'), 20.0), 6.0)
        resolved['protectedSymbolCooldownMinutes'] = max(_safe_float(resolved.get('protectedSymbolCooldownMinutes'), 5.0), 12.0)
        resolved['neverNegativeActivationProfit'] = max(0.35, min(_safe_float(resolved.get('neverNegativeActivationProfit'), 1.0), 0.6))
        resolved['neverNegativeFloorProfit'] = max(0.1, min(_safe_float(resolved.get('neverNegativeFloorProfit'), 0.25), 0.25))
        resolved['stallProfitGivebackPercent'] = min(_safe_float(resolved.get('stallProfitGivebackPercent'), 30.0), 20.0)
        resolved['stallSignalStrengthFloor'] = max(_safe_float(resolved.get('stallSignalStrengthFloor'), 55.0), 60.0)
        resolved['stallMinTpProgress'] = max(_safe_float(resolved.get('stallMinTpProgress'), 0.70), 0.6)

    # Exness volatile metals & energy commodities (XAG, XAU, oils): these swing
    # hard and fast and a $1.25-$2.00 peak is meaningful for a 0.01-0.04 micro lot.
    # The adaptive volatility bucket (high=7.0 / very_high=10.0 activationMinProfit)
    # leaves a $1.25 peak unprotected, so the loss runs to the full cap. Lower the
    # arming thresholds so a modest peak still engages never-negative / zero-loss
    # locks well before the hard cap.
    if broker_name == 'Exness' and base_symbol in {'XAGUSD', 'XAUSD', 'XAUUSD', 'XPTUSD', 'XPDUSD', 'UKOIL', 'USOIL', 'UKOILm', 'USOILm', 'XAGUSDm', 'XAUUSDm', 'XPTUSDm', 'XPDUSDm'}:
        resolved['activationMinProfit'] = min(_safe_float(resolved.get('activationMinProfit'), 7.0), 1.5)
        resolved['neverNegativeActivationProfit'] = max(0.25, min(_safe_float(resolved.get('neverNegativeActivationProfit'), 1.0), 0.5))
        resolved['neverNegativeFloorProfit'] = max(0.08, min(_safe_float(resolved.get('neverNegativeFloorProfit'), 0.25), 0.25))
        resolved['minimumHoldMinutes'] = min(_safe_float(resolved.get('minimumHoldMinutes'), 20.0), 5.0)
        resolved['zeroLossLockEnabled'] = True
        # Flag only the metals resolver touched — lets _minimum_position_hold_minutes
        # honour this lower hold instead of the global env floor without bypassing it
        # for symbols whose raw profitProtection.minimumHoldMinutes is user-supplied.
        resolved['_volatileMetalHoldOverride'] = True

    if (
        broker_name == 'Binance'
        and account_balance > 0
        and account_balance <= small_account_threshold * 2.0
        and base_symbol in {'BTCUSD', 'BTCUSDT', 'ETHUSD', 'ETHUSDT'}
        and (is_small_account or _is_guarded_small_live_account(bot_config, 2.0))
    ):
        is_btc_runner = base_symbol in {'BTCUSD', 'BTCUSDT'}
        resolved['activationMinProfit'] = max(
            0.35 if is_btc_runner else 0.28,
            min(_safe_float(resolved.get('activationMinProfit'), 2.0), 0.55 if is_btc_runner else 0.45),
        )
        resolved['minLockedProfit'] = max(
            0.18,
            min(_safe_float(resolved.get('minLockedProfit'), 1.0), 0.30 if is_btc_runner else 0.25),
        )
        resolved['peakProfitHardLockShare'] = max(
            _safe_float(resolved.get('peakProfitHardLockShare'), 0.95),
            0.92 if is_btc_runner else 0.90,
        )
        resolved['retraceClosePercent'] = min(_safe_float(resolved.get('retraceClosePercent'), 35.0), 22.0 if is_btc_runner else 28.0)
        resolved['breakEvenBufferProfit'] = max(
            0.20,
            min(_safe_float(resolved.get('breakEvenBufferProfit'), 2.0), 0.30 if is_btc_runner else 0.25),
        )
