# ==================== EXNESS BROKER ENDPOINTS ====================
# Exness provides MT5-based trading with session token authentication

def generate_exness_session_token():
    """Generate secure session token for Exness MT5 trading"""
    return f"exness_{uuid.uuid4().hex[:32]}"

def validate_exness_server(server_name):
    """Validate that server name is correct for Exness"""
    valid_servers = ['Exness-MT5', 'Exness-MT5.5', 'Exness-MT5-Real']
    return server_name in valid_servers

def get_exness_available_symbols():
    """Return list of available Exness symbols based on VALID_SYMBOLS"""
    return get_mt5_ready_symbols_for_broker('Exness')

@app.route('/api/broker/exness/login', methods=['POST'])
def exness_login():
    """Login to Exness MT5 account and create session.
    CRITICAL: Uses ensure_mt5_ready() instead of mt5.initialize().
    NEVER calls mt5.shutdown() - the terminal is shared by all bots.
    """
    try:
        data = request.json or {}
        account_id = data.get('accountId') or data.get('account_id')
        password = data.get('password')
        server = data.get('server', 'Exness-MT5')
        is_live = data.get('is_live', False)
        
        if not account_id or not password:
            return jsonify({'success': False, 'error': 'accountId and password required'}), 400
        
        if not validate_exness_server(server):
            return jsonify({'success': False, 'error': f'Invalid Exness server: {server}'}), 400
        
        # Try to connect to MT5 for Exness
        try:
            import MetaTrader5 as mt5
            
            # SAFE: Use ensure_mt5_ready() instead of mt5.initialize()
            if not ensure_mt5_ready():
                return jsonify({
                    'success': False,
                    'error': 'Failed to initialize MT5',
                    'detail': 'MT5 terminal may not be installed or running'
                }), 500
            
            # Check if already logged into this account
            try:
                account_id_int = int(account_id)
            except ValueError:
                return jsonify({'success': False, 'error': 'accountId must be numeric'}), 400
            
            existing = mt5.account_info()
            if existing and existing.login == account_id_int:
                # Already logged in - just return the info
                logger.info(f"✅ Exness already logged in to account {account_id}")
                session_token = generate_exness_session_token()
                return jsonify({
                    'success': True,
                    'session_token': session_token,
                    'account_id': account_id,
                    'account_type': 'LIVE' if is_live else 'DEMO',
                    'balance': existing.balance,
                    'currency': existing.currency,
                    'leverage': existing.leverage,
                    'server': server,
                }), 200
            
            # Different account - try login (but NEVER shutdown on failure)
            login_result = mt5.login(account_id_int, password=password, server=server)
            
            if not login_result:
                error_msg = mt5.last_error()
                logger.warning(f"⚠️ Exness login failed for account {account_id}: {error_msg}")
                # CRITICAL: Do NOT call mt5.shutdown() here!
                return jsonify({
                    'success': False,
                    'error': 'Failed to login to Exness account',
                    'detail': f'Check account ID, password, and server name. Server must be "{server}"'
                }), 401
            
            # Get account info
            account_info = mt5.account_info()
            if not account_info:
                # CRITICAL: Do NOT call mt5.shutdown() here!
                return jsonify({
                    'success': False,
                    'error': 'Failed to retrieve account info from MT5'
                }), 500
            
            # Generate session token
            session_token = generate_exness_session_token()
            
            logger.info(f"✅ Exness login successful for account {account_id}")
            
            return jsonify({
                'success': True,
                'session_token': session_token,
                'account_id': account_id,
                'account_type': 'LIVE' if is_live else 'DEMO',
                'balance': account_info.balance,
                'currency': account_info.currency,
                'leverage': account_info.leverage,
                'server': server,
            }), 200
            
        except ImportError:
            return jsonify({
                'success': False,
                'error': 'MetaTrader5 SDK not installed',
                'detail': 'Install: pip install MetaTrader5>=5.0.45'
            }), 500
            
    except Exception as e:
        logger.error(f"Error in Exness login: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


# ==================== EXNESS ONBOARDING WIZARD ====================
@app.route('/api/broker/exness/onboard', methods=['POST'])
@require_session
def exness_onboard_wizard():
    """
    Multi-step Exness onboarding wizard for new users.

    Accepts a `step` field in the JSON body to drive the wizard:

    Step 1 — validate_account: verify account number + password reach the MT5 server,
             check user/global Exness slot availability.
    Step 2 — connect_and_save: do a full credential test-and-save, assign MT5 terminal
             path (demo or live), return credential_id ready for bot creation.
    Step 3 — create_bot: create a ready-to-start bot linked to the saved credential.
             Returns the bot_id so the Flutter app can call /api/bot/start.

    All steps require a valid session token (user must be logged in).
    """
    try:
        user_id = request.user_id
        data = request.get_json(silent=True) or {}
        step = str(data.get('step', '1')).strip()

        # ── STEP 1: validate account identity ─────────────────────────────
        if step == '1':
            account_number = str(data.get('account_number') or '').strip()
            is_live = bool(data.get('is_live', False))

            if not account_number or not account_number.isdigit() or len(account_number) != 9:
                return jsonify({
                    'success': False,
                    'step': 1,
                    'error': 'Enter your 9-digit Exness MT5 account number (e.g. 295677214).',
                }), 400

            # Check global Exness cap before doing anything heavy
            try:
                _c = get_db_connection()
                _cur = _c.cursor()
                _cur.execute(
                    '''SELECT COUNT(DISTINCT user_id) FROM broker_credentials
                       WHERE broker_name = 'Exness' AND is_active = 1 AND user_id != ?''',
                    (user_id,)
                )
                _exness_slots_used = (_cur.fetchone() or [0])[0]

                # Also count existing credential for this user (re-onboarding is always ok)
                _cur.execute(
                    '''SELECT credential_id FROM broker_credentials
                       WHERE broker_name = 'Exness' AND is_active = 1 AND user_id = ?
                       LIMIT 1''',
                    (user_id,)
                )
                _existing_cred = _cur.fetchone()
                _c.close()
            except Exception as _ce:
                logger.warning(f'Exness cap check failed: {_ce}')
                _exness_slots_used = 0
                _existing_cred = None

            at_capacity = (_exness_slots_used >= EXNESS_MAX_USERS) and not _existing_cred

            # Determine MT5 server and terminal path
            expected_server = normalize_mt5_server_name('Exness', is_live, None, account_number)
            terminal_path = _resolve_exness_terminal_path(
                is_live=is_live,
                server=expected_server,
                account_number=account_number,
            )
            terminal_available = bool(terminal_path and os.path.exists(str(terminal_path)))

            return jsonify({
                'success': True,
                'step': 1,
                'account_number': account_number,
                'is_live': is_live,
                'server': expected_server,
                'mode': 'live' if is_live else 'demo',
                'slots_used': _exness_slots_used,
                'slots_max': EXNESS_MAX_USERS,
                'at_capacity': at_capacity,
                'terminal_available': terminal_available,
                'existing_user': bool(_existing_cred),
                'message': (
                    f'Exness {"live" if is_live else "demo"} account {account_number} validated. '
                    f'Server: {expected_server}. '
                    + (f'{_exness_slots_used}/{EXNESS_MAX_USERS} slots used.' if not at_capacity
                       else f'FULL — {EXNESS_MAX_USERS}/{EXNESS_MAX_USERS} slots used.')
                ),
            }), 200

        # ── STEP 2: full credential test + save ───────────────────────────
        elif step == '2':
            account_number = str(data.get('account_number') or '').strip()
            password = str(data.get('password') or '').strip()
            is_live = bool(data.get('is_live', False))
            label = str(data.get('label') or '').strip() or None
            mt5_terminal_path = data.get('mt5_terminal_path') or data.get('mt5_path')

            if not account_number or not account_number.isdigit() or len(account_number) != 9:
                return jsonify({'success': False, 'step': 2, 'error': 'Invalid account number.'}), 400
            if not password:
                return jsonify({'success': False, 'step': 2, 'error': 'Password required.'}), 400

            # Re-check cap
            try:
                _c2 = get_db_connection()
                _cur2 = _c2.cursor()
                _cur2.execute(
                    '''SELECT COUNT(DISTINCT user_id) FROM broker_credentials
                       WHERE broker_name = 'Exness' AND is_active = 1 AND user_id != ?''',
                    (user_id,)
                )
                _slots = (_cur2.fetchone() or [0])[0]
                _cur2.execute(
                    '''SELECT credential_id FROM broker_credentials
                       WHERE broker_name = 'Exness' AND is_active = 1 AND user_id = ?
                       LIMIT 1''',
                    (user_id,)
                )
                _existing2 = _cur2.fetchone()
                _c2.close()
            except Exception:
                _slots = 0
                _existing2 = None

            if _slots >= EXNESS_MAX_USERS and not _existing2:
                return jsonify({
                    'success': False,
                    'step': 2,
                    'error': f'Exness is full ({EXNESS_MAX_USERS} users). Join the waitlist.',
                    'capacity_limit': True,
                }), 429

            server = normalize_mt5_server_name('Exness', is_live, None, account_number)
            terminal_path = _resolve_exness_terminal_path(
                configured_path=mt5_terminal_path,
                is_live=is_live,
                server=server,
                account_number=account_number,
            )
            if terminal_path:
                terminal_path = resolve_mt5_terminal_executable_path(terminal_path) or str(terminal_path).strip()
            terminal_path_str = str(terminal_path) if terminal_path else None

            # Quick MT5 test
            actual_balance = 0.0
            actual_currency = 'USD'
            verified = False
            test_error = None
            try:
                quick_conn = MT5Connection({
                    'broker': 'Exness',
                    'account': account_number,
                    'account_number': account_number,
                    'password': password,
                    'server': server,
                    'is_live': is_live,
                    'is_manual_test': True,
                    'lock_timeout': 5,
                    'init_timeout': 15,
                })
                if quick_conn.connect():
                    qi = quick_conn.get_account_info() or {}
                    actual_balance = float(qi.get('balance', 0) or 0)
                    actual_currency = str(qi.get('currency', 'USD') or 'USD').upper()
                    verified = True
                    quick_conn.disconnect()
                else:
                    test_error = quick_conn.last_error or 'Could not verify Exness credentials'
                    if quick_conn.last_error_code == 'AUTH_FAILED':
                        return jsonify({
                            'success': False,
                            'step': 2,
                            'error': f'Authentication failed: {test_error}. Check account number and password.',
                        }), 401
            except Exception as _te:
                test_error = str(_te)
                logger.warning(f'Exness wizard step 2 MT5 test error: {_te}')

            # Save or update credential
            now_iso = datetime.now().isoformat()
            credential_id = str(uuid.uuid4())
            try:
                _sc = get_db_connection()
                _scur = _sc.cursor()
                _scur.execute(
                    '''SELECT credential_id FROM broker_credentials
                       WHERE user_id = ? AND broker_name = 'Exness' AND account_number = ? AND is_active = 1
                       LIMIT 1''',
                    (user_id, account_number)
                )
                _existing_row = _scur.fetchone()
                if _existing_row:
                    credential_id = _existing_row[0]
                    _scur.execute(
                        '''UPDATE broker_credentials
                           SET password = ?, server = ?, is_live = ?, mt5_terminal_path = ?,
                               account_currency = ?, cached_balance = ?, updated_at = ?
                           WHERE credential_id = ?''',
                        (password, server, int(is_live), terminal_path_str,
                         actual_currency, actual_balance if verified else None,
                         now_iso, credential_id)
                    )
                else:
                    _scur.execute(
                        '''INSERT INTO broker_credentials
                           (credential_id, user_id, broker_name, account_number, password,
                            server, is_live, is_active, mt5_terminal_path, account_currency,
                            cached_balance, created_at, updated_at)
                           VALUES (?, ?, 'Exness', ?, ?, ?, ?, 1, ?, ?, ?, ?, ?)''',
                        (credential_id, user_id, account_number, password,
                         server, int(is_live), terminal_path_str,
                         actual_currency, actual_balance if verified else None,
                         now_iso, now_iso)
                    )
                if label:
                    _scur.execute(
                        'UPDATE broker_credentials SET label = ? WHERE credential_id = ?',
                        (label, credential_id)
                    )
                encrypt_credential_at_rest(_scur, credential_id)
                _sc.commit()
                _sc.close()
            except Exception as _sdb:
                logger.error(f'Exness wizard step 2 DB save failed: {_sdb}')
                return jsonify({
                    'success': False, 'step': 2,
                    'error': f'Failed to save credentials: {_sdb}',
                }), 500

            return jsonify({
                'success': True,
                'step': 2,
                'credential_id': credential_id,
                'account_number': account_number,
                'server': server,
                'is_live': is_live,
                'mode': 'live' if is_live else 'demo',
                'terminal_path': terminal_path_str,
                'balance': actual_balance,
                'currency': actual_currency,
                'verified': verified,
                'warning': test_error if not verified else None,
                'message': (
                    f'Exness {"live" if is_live else "demo"} account {account_number} saved. '
                    + (f'Balance: {actual_balance:.2f} {actual_currency}.' if verified else 'Saved (verification deferred).')
                ),
            }), 200

        # ── STEP 3: create a ready bot linked to the Exness credential ────
        elif step == '3':
            credential_id = str(data.get('credential_id') or '').strip()
            symbols = data.get('symbols') or ['EURUSD', 'GBPUSD', 'XAUUSD']
            strategy = str(data.get('strategy') or 'Trend Following').strip()
            risk_per_trade = float(data.get('risk_per_trade') or data.get('riskPerTrade') or 20)
            max_daily_loss = float(data.get('max_daily_loss') or data.get('maxDailyLoss') or 60)

            if not credential_id:
                return jsonify({'success': False, 'step': 3, 'error': 'credential_id required.'}), 400

            # Verify credential belongs to user
            try:
                _bc = get_db_connection()
                _bcur = _bc.cursor()
                _bcur.execute(
                    '''SELECT credential_id, account_number, is_live FROM broker_credentials
                       WHERE credential_id = ? AND user_id = ? AND is_active = 1''',
                    (credential_id, user_id)
                )
                _cred_row = _bcur.fetchone()
                _bc.close()
            except Exception as _bce:
                return jsonify({'success': False, 'step': 3, 'error': str(_bce)}), 500

            if not _cred_row:
                return jsonify({
                    'success': False, 'step': 3,
                    'error': 'Credential not found. Complete step 2 first.',
                }), 404

            account_number = _cred_row[1]
            is_live = bool(_cred_row[2])

            bot_payload = {
                'botId': f"bot_{int(time.time() * 1000)}",
                'credentialId': credential_id,
                'mode': 'live' if is_live else 'demo',
                'symbols': symbols if isinstance(symbols, list) else [symbols],
                'strategy': strategy,
                'riskPerTrade': risk_per_trade,
                'maxDailyLoss': max_daily_loss,
                'autoStart': False,  # User starts manually from the app
                'enabled': False,
            }

            try:
                with app.test_request_context(
                    '/api/bot/create',
                    method='POST',
                    json=bot_payload,
                    headers={'X-Session-Token': request.headers.get('X-Session-Token', '')},
                ):
                    request.user_id = user_id
                    create_result = create_bot.__wrapped__()
            except Exception as _create_err:
                logger.error(f'Exness wizard step 3 delegated create failed: {_create_err}')
                return jsonify({
                    'success': False,
                    'step': 3,
                    'error': f'Bot creation failed: {_create_err}',
                }), 500

            create_response = create_result[0] if isinstance(create_result, tuple) else create_result
            create_status = create_result[1] if isinstance(create_result, tuple) and len(create_result) > 1 else getattr(create_response, 'status_code', 500)
            create_data = create_response.get_json(silent=True) or {}

            if create_status not in (200, 201) or not create_data.get('success'):
                return jsonify({
                    'success': False,
                    'step': 3,
                    'error': create_data.get('error') or 'Bot creation failed.',
                }), create_status

            created_bot_id = str(create_data.get('botId') or bot_payload['botId'])
            return jsonify({
                'success': True,
                'step': 3,
                'bot_id': created_bot_id,
                'botId': created_bot_id,
                'credential_id': credential_id,
                'credentialId': credential_id,
                'account_number': account_number,
                'mode': 'live' if is_live else 'demo',
                'symbols': bot_payload['symbols'],
                'strategy': strategy,
                'warnings': create_data.get('warnings', []),
                'message': (
                    f'Exness bot created for account {account_number}. '
                    'Tap Start to begin trading.'
                ),
            }), 201

        else:
            return jsonify({
                'success': False,
                'error': f'Unknown wizard step: {step}. Use 1, 2, or 3.',
            }), 400

    except Exception as e:
        logger.error(f'Error in exness_onboard_wizard step {data.get("step","?")}: {e}')
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/broker/exness/logout', methods=['POST'])
def exness_logout():
    """Logout from Exness (cleanup session)
    CRITICAL: Does NOT call mt5.shutdown()! That would kill ALL bot connections.
    Only clears the session token - MT5 terminal stays running for bots."""
    try:
        session_token = request.headers.get('Authorization', '').replace('Bearer ', '')
        
        if not session_token:
            return jsonify({'success': False, 'error': 'No session token provided'}), 401
        
        # CRITICAL: Do NOT call mt5.shutdown() here!
        # The MT5 terminal is shared by all 9+ trading bots.
        # Calling shutdown() would disconnect EVERYTHING.
        # Just invalidate the session token.
        
        logger.info(f"✅ Exness session ended (MT5 terminal kept alive for bots)")
        
        return jsonify({
            'success': True,
            'message': 'Logged out from Exness'
        }), 200
        
    except Exception as e:
        logger.error(f"Error in Exness logout: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/broker/exness/account', methods=['GET'])
@require_session
def exness_account_info():
    """Get Exness account information - reconnects with user's saved credentials"""
    try:
        user_id = request.user_id  # From @require_session
        
        # Load user's latest active Exness credential
        conn = get_db_connection()
        cursor = conn.cursor()
        
        cursor.execute('''
            SELECT credential_id, account_number, password, server, is_live,
                   cached_balance, cached_equity, cached_margin_free,
                   cached_margin, cached_margin_level, cached_profit, account_currency
            FROM broker_credentials
            WHERE user_id = ? AND broker_name = 'Exness' AND is_active = 1
            ORDER BY created_at DESC
            LIMIT 1
        ''', (user_id,))
        
        cred_row = cursor.fetchone()
        conn.close()
        
        if not cred_row:
            return jsonify({
                'success': False, 
                'error': 'No Exness credentials found. Please connect your Exness account first.'
            }), 400
        
        cred = dict(cred_row)
        account = cred['account_number']
        is_live = cred['is_live']

        active_snapshot = read_active_mt5_account_snapshot(
            'Exness',
            account,
            credential_id=cred.get('credential_id'),
            user_id=user_id,
        )
        if active_snapshot:
            return jsonify({
                'success': True,
                'accountId': active_snapshot.get('accountNumber') or account,
                'balance': float(active_snapshot.get('balance', 0) or 0),
                'equity': float(active_snapshot.get('equity', 0) or 0),
                'margin': float(active_snapshot.get('margin', 0) or 0),
                'marginFree': float(active_snapshot.get('marginFree', 0) or 0),
                'marginLevel': float(active_snapshot.get('margin_level', 0) or 0),
                'currency': active_snapshot.get('currency', 'USD'),
                'leverage': active_snapshot.get('leverage'),
                'accountType': 'LIVE' if is_live else 'DEMO',
                'profitLoss': float(active_snapshot.get('profit', 0) or 0),
                'dataSource': 'active_mt5_session',
            }), 200

        cached_balance = float(cred.get('cached_balance') or 0)
        cached_equity = float(cred.get('cached_equity') or cached_balance)
        cached_margin = float(cred.get('cached_margin') or 0)
        cached_margin_free = float(cred.get('cached_margin_free') or 0)
        cached_margin_level = float(cred.get('cached_margin_level') or 0)
        cached_profit = float(cred.get('cached_profit') or 0)
        cached_currency = str(cred.get('account_currency') or 'USD').upper()

        if cached_balance > 0 or cached_equity > 0 or cached_profit != 0:
            return jsonify({
                'success': True,
                'accountId': account,
                'balance': cached_balance,
                'equity': cached_equity,
                'margin': cached_margin,
                'marginFree': cached_margin_free,
                'marginLevel': cached_margin_level,
                'currency': cached_currency,
                'leverage': None,
                'accountType': 'LIVE' if is_live else 'DEMO',
                'profitLoss': cached_profit,
                'dataSource': 'cached',
                'message': 'Requested Exness account is not the active MT5 session; returning cached values without switching accounts.',
            }), 200

        return jsonify({
            'success': False,
            'error': 'Requested Exness account is not the active MT5 session; refusing to switch MT5 automatically'
        }), 409
            
    except Exception as e:
        logger.error(f"Error in exness_account_info: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/broker/exness/trade', methods=['POST'])
@require_session
def exness_place_trade():
    """Place order on Exness MT5 account"""
    try:
        # @require_session decorator already validates authentication
        # User is authenticated if we reach here
        
        data = request.json or {}
        symbol = (data.get('symbol') or '').upper()
        side = (data.get('side') or 'BUY').upper()
        volume = float(data.get('volume', 0.1))
        stop_loss = data.get('stopLoss') or data.get('stop_loss')
        take_profit = data.get('takeProfit') or data.get('take_profit')
        
        if not symbol or side not in ['BUY', 'SELL']:
            return jsonify({'success': False, 'error': 'symbol and side (BUY/SELL) required'}), 400
        
        if volume <= 0:
            return jsonify({'success': False, 'error': 'volume must be positive'}), 400
        
        try:
            import MetaTrader5 as mt5
            
            if not ensure_mt5_ready():
                return jsonify({'success': False, 'error': 'MT5 not initialized'}), 500
            
            # Select symbol
            if not mt5.symbol_select(symbol, True):
                return jsonify({
                    'success': False,
                    'error': f'Symbol {symbol} not available on Exness'
                }), 400
            
            # Get tick for price
            tick = mt5.symbol_info_tick(symbol)
            if not tick:
                return jsonify({
                    'success': False,
                    'error': f'Cannot get market data for {symbol}'
                }), 500
            
            price = tick.ask if side == 'BUY' else tick.bid
            
            # Build order request — auto-detect filling type for Exness
            sym_info = mt5.symbol_info(symbol)
            if sym_info and sym_info.filling_mode & 2:
                _filling = mt5.ORDER_FILLING_IOC
            elif sym_info and sym_info.filling_mode & 1:
                _filling = mt5.ORDER_FILLING_FOK
            else:
                _filling = mt5.ORDER_FILLING_RETURN

            request_dict = {
                'action': mt5.TRADE_ACTION_DEAL,
                'symbol': symbol,
                'volume': volume,
                'type': mt5.ORDER_TYPE_BUY if side == 'BUY' else mt5.ORDER_TYPE_SELL,
                'price': price,
                'comment': 'Exness Order',
                'type_time': mt5.ORDER_TIME_GTC,
                'type_filling': _filling,
            }
            
            if stop_loss:
                request_dict['sl'] = float(stop_loss)
            if take_profit:
                request_dict['tp'] = float(take_profit)
            
            # Send order
            result = mt5.order_send(request_dict)
            
            if result is None:
                return jsonify({
                    'success': False,
                    'error': 'Order submission failed - terminal disconnected'
                }), 500
            
            if result.retcode != mt5.TRADE_RETCODE_DONE:
                return jsonify({
                    'success': False,
                    'error': f'Order failed: {result.comment}',
                    'retcode': result.retcode
                }), 400
            
            logger.info(f"✅ Exness order placed: {symbol} {side} {volume}L")
            
            return jsonify({
                'success': True,
                'orderId': result.order,
                'symbol': symbol,
                'side': side,
                'volume': volume,
                'price': price,
                'commission': result.comment if hasattr(result, 'comment') else 0,
            }), 201
            
        except ImportError:
            return jsonify({'success': False, 'error': 'MetaTrader5 SDK not available'}), 500
            
    except Exception as e:
        logger.error(f"Error placing Exness trade: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/broker/exness/orders', methods=['GET'])
@require_session
def exness_get_orders():
    """Get open orders/positions from Exness account"""
    try:
        # @require_session decorator already validates authentication
        
        try:
            import MetaTrader5 as mt5
            
            if not ensure_mt5_ready():
                return jsonify({'success': False, 'error': 'MT5 not initialized'}), 500
            
            # Get open positions
            positions = mt5.positions_get()
            if positions is None:
                positions = []
            
            orders = []
            for pos in positions:
                orders.append({
                    'orderId': pos.ticket,
                    'symbol': pos.symbol,
                    'side': 'BUY' if pos.type == mt5.ORDER_TYPE_BUY else 'SELL',
                    'volume': pos.volume,
                    'openPrice': pos.price_open,
                    'currentPrice': pos.price_current,
                    'profit': pos.profit,
                    'profitPercent': (pos.profit / (pos.price_open * pos.volume)) * 100 if pos.price_open > 0 else 0,
                    'openTime': datetime.fromtimestamp(pos.time).isoformat(),
                })
            
            logger.info(f"✅ Retrieved {len(orders)} open orders from Exness")
            
            return jsonify({
                'success': True,
                'orders': orders,
                'count': len(orders)
            }), 200
            
        except ImportError:
            return jsonify({'success': False, 'error': 'MetaTrader5 SDK not available'}), 500
            
    except Exception as e:
        logger.error(f"Error getting Exness orders: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/broker/exness/orders/<order_id>/close', methods=['POST'])
@require_session
def exness_close_order(order_id):
    """Close a specific order/position on Exness"""
    try:
        # @require_session decorator already validates authentication
        
        try:
            order_id_int = int(order_id)
        except ValueError:
            return jsonify({'success': False, 'error': 'Invalid order ID'}), 400
        
        try:
            import MetaTrader5 as mt5

            if not ensure_mt5_ready():
                return jsonify({'success': False, 'error': 'MT5 not initialized'}), 500

            # Get position
            position = mt5.positions_get(ticket=order_id_int)
            if not position:
                return jsonify({'success': False, 'error': 'Position not found'}), 404

            pos = position[0]

            min_hold_seconds = 60
            open_time = datetime.fromtimestamp(pos.time) if hasattr(pos, 'time') else None
            if open_time is not None:
                held_seconds = max(0, int((datetime.now() - open_time).total_seconds()))
                if held_seconds < min_hold_seconds:
                    return jsonify({
                        'success': False,
                        'error': f'Minimum holding period not met. Position open for {held_seconds}s, must be at least {min_hold_seconds}s.'
                    }), 400

            # Build close order request
            close_type = mt5.ORDER_TYPE_SELL if pos.type == mt5.ORDER_TYPE_BUY else mt5.ORDER_TYPE_BUY
            
            # Get current price
            tick = mt5.symbol_info_tick(pos.symbol)
            price = tick.bid if close_type == mt5.ORDER_TYPE_SELL else tick.ask
            
            # Auto-detect filling type for close order
            _sym_info = mt5.symbol_info(pos.symbol)
            if _sym_info and _sym_info.filling_mode & 2:
                _close_filling = mt5.ORDER_FILLING_IOC
            elif _sym_info and _sym_info.filling_mode & 1:
                _close_filling = mt5.ORDER_FILLING_FOK
            else:
                _close_filling = mt5.ORDER_FILLING_RETURN

            request_dict = {
                'action': mt5.TRADE_ACTION_DEAL,
                'symbol': pos.symbol,
                'volume': pos.volume,
                'type': close_type,
                'position': order_id_int,
                'price': price,
                'comment': 'Position Closed',
                'type_time': mt5.ORDER_TIME_GTC,
                'type_filling': _close_filling,
            }
            
            result = mt5.order_send(request_dict)
            
            if result is None or result.retcode != mt5.TRADE_RETCODE_DONE:
                return jsonify({
                    'success': False,
                    'error': 'Failed to close position'
                }), 500
            
            logger.info(f"✅ Exness position {order_id} closed successfully")
            
            return jsonify({
                'success': True,
                'orderId': order_id,
                'message': 'Position closed'
            }), 200
            
        except ImportError:
            return jsonify({'success': False, 'error': 'MetaTrader5 SDK not available'}), 500
            
    except Exception as e:
        logger.error(f"Error closing Exness order: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/broker/exness/orders/<order_id>', methods=['PATCH'])
@require_session
def exness_update_order(order_id):
    """Update stop loss and take profit for Exness order"""
    try:
        # @require_session decorator already validates authentication
        
        data = request.json or {}
        new_sl = data.get('stopLoss') or data.get('stop_loss')
        new_tp = data.get('takeProfit') or data.get('take_profit')
        
        if not new_sl and not new_tp:
            return jsonify({'success': False, 'error': 'stopLoss or takeProfit required'}), 400
        
        try:
            order_id_int = int(order_id)
        except ValueError:
            return jsonify({'success': False, 'error': 'Invalid order ID'}), 400
        
        try:
            import MetaTrader5 as mt5
            
            if not ensure_mt5_ready():
                return jsonify({'success': False, 'error': 'MT5 not initialized'}), 500
            
            # Get position
            position = mt5.positions_get(ticket=order_id_int)
            if not position:
                return jsonify({'success': False, 'error': 'Position not found'}), 404
            
            pos = position[0]
            
            # Build modify request
            request_dict = {
                'action': mt5.TRADE_ACTION_SLTP,
                'position': order_id_int,
                'sl': float(new_sl) if new_sl else pos.sl,
                'tp': float(new_tp) if new_tp else pos.tp,
            }
            
            result = mt5.order_send(request_dict)
            
            if result is None or result.retcode != mt5.TRADE_RETCODE_DONE:
                return jsonify({
                    'success': False,
                    'error': 'Failed to update position'
                }), 500
            
            logger.info(f"✅ Exness position {order_id} updated: SL={new_sl}, TP={new_tp}")
            
            return jsonify({
                'success': True,
                'orderId': order_id,
                'stopLoss': new_sl,
                'takeProfit': new_tp,
                'message': 'Position updated'
            }), 200
            
        except ImportError:
            return jsonify({'success': False, 'error': 'MetaTrader5 SDK not available'}), 500
            
    except Exception as e:
        logger.error(f"Error updating Exness order: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


@app.route('/api/broker/exness/symbols/<symbol>', methods=['GET'])
def exness_symbol_info(symbol):
    """Get symbol information and current market data from Exness"""
    try:
        session_token = request.headers.get('Authorization', '').replace('Bearer ', '')
        
        if not session_token or not session_token.startswith('exness_'):
            return jsonify({'success': False, 'error': 'Invalid session token'}), 401
        
        symbol = symbol.upper()
        
        try:
            import MetaTrader5 as mt5
            
            if not ensure_mt5_ready():
                return jsonify({'success': False, 'error': 'MT5 not initialized'}), 500
            
            # Get symbol info
            symbol_info = mt5.symbol_info(symbol)
            if not symbol_info:
                return jsonify({
                    'success': False,
                    'error': f'Symbol {symbol} not found on Exness'
                }), 404
            
            # Get tick data
            tick = mt5.symbol_info_tick(symbol)
            if not tick:
                return jsonify({
                    'success': False,
                    'error': f'Cannot get market data for {symbol}'
                }), 500
            
            return jsonify({
                'success': True,
                'symbol': symbol,
                'bid': tick.bid,
                'ask': tick.ask,
                'spread': tick.ask - tick.bid,
                'minSize': symbol_info.volume_min,
                'maxSize': symbol_info.volume_max,
                'stepSize': symbol_info.volume_step,
                'tradable': symbol_info.trade_mode != mt5.SYMBOL_TRADE_MODE_DISABLED,
                'lastUpdate': datetime.fromtimestamp(tick.time).isoformat(),
            }), 200
            
        except ImportError:
            return jsonify({'success': False, 'error': 'MetaTrader5 SDK not available'}), 500
            
    except Exception as e:
        logger.error(f"Error getting Exness symbol info: {e}")
        return jsonify({'success': False, 'error': str(e)}), 500


