@app.route('/api/bot/<bot_id>/risk-profile', methods=['POST', 'PUT'])
@require_session
def set_bot_risk_profile(bot_id):
    """Apply a risk profile to a bot"""
    conn = None
    try:
        user_id = request.user_id
        data = request.get_json(silent=True) or {}
        profile_name = str(data.get('profile') or '').strip().lower()
        
        if not profile_name or profile_name not in RISK_PROFILES:
            return jsonify({
                'success': False,
                'error': 'Invalid profile. Must be one of: ' + ', '.join(RISK_PROFILES.keys())
            }), 400
        
        profile_config = RISK_PROFILES[profile_name]
        
        # Get bot and update runtime_state
        conn = db_connection()
        cur = conn.cursor()
        
        cur.execute("""
            SELECT runtime_state FROM user_bots 
            WHERE bot_id = %s AND user_id = %s
        """, (bot_id, user_id))
        
        row = cur.fetchone()
        if not row:
            return jsonify({'success': False, 'error': 'Bot not found'}), 404
        
        # Parse existing state
        runtime_state = row[0] or '{}'
        try:
            state = json.loads(runtime_state) if isinstance(runtime_state, str) else runtime_state
        except:
            state = {}
        
        # Apply profile
        state['riskProfile'] = profile_name
        state['leverage'] = profile_config['leverage']
        state['maxDailyLoss'] = profile_config['maxDailyLoss']
        state['maxOpenTrades'] = profile_config['maxOpenTrades']
        state['positionSizeMultiplier'] = profile_config['positionSizeMultiplier']
        state['enableAcceleration'] = profile_config['enableAcceleration']
        state['antiMartingaleMode'] = profile_config['antiMartingaleMode']
        state['signalThreshold'] = profile_config['signalThreshold']
        state['lastProfileUpdate'] = datetime.utcnow().isoformat()
        
        # Save updated state
        state_json = json.dumps(state)
        cur.execute("""
            UPDATE user_bots 
            SET runtime_state = %s
            WHERE bot_id = %s AND user_id = %s
        """, (state_json, bot_id, user_id))
        
        conn.commit()
        
        # Update active bot if running
        if bot_id in active_bots:
            try:
                runtime_state_obj = active_bots[bot_id].get('runtime_state', {})
                if isinstance(runtime_state_obj, str):
                    runtime_state_obj = json.loads(runtime_state_obj)
                runtime_state_obj.update(state)
                active_bots[bot_id]['runtime_state'] = runtime_state_obj
            except:
                pass
        
        return jsonify({
            'success': True,
            'botId': bot_id,
            'profile': profile_name,
            'config': profile_config,
            'message': f'Risk profile "{profile_name}" applied successfully'
        }), 200
        
    except Exception as e:
        logger.error(f'[set_bot_risk_profile] error: {e}')
        if conn:
            try:
                conn.rollback()
            except:
                pass
        return jsonify({'success': False, 'error': str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except:
                pass


@app.route('/api/bots/apply-profile-bulk', methods=['POST'])
@require_session
def apply_profile_bulk():
    """Apply risk profile to multiple bots"""
    conn = None
    try:
        user_id = request.user_id
        data = request.get_json(silent=True) or {}
        profile_name = str(data.get('profile') or '').strip().lower()
        bot_ids = data.get('botIds', [])
        broker_filter = str(data.get('broker') or '').strip().lower()  # Optional: 'binance', 'exness', etc
        
        if not profile_name or profile_name not in RISK_PROFILES:
            return jsonify({
                'success': False,
                'error': 'Invalid profile'
            }), 400
        
        profile_config = RISK_PROFILES[profile_name]
        conn = db_connection()
        cur = conn.cursor()
        
        # If broker_filter provided, fetch all bots for that broker
        if broker_filter and not bot_ids:
            query = """
                SELECT bot_id FROM user_bots 
                WHERE user_id = %s 
                AND (broker_account_id ILIKE %s OR brokerName ILIKE %s)
            """
            cur.execute(query, (user_id, f'%{broker_filter}%', f'%{broker_filter}%'))
            bot_ids = [row[0] for row in cur.fetchall()]
        
        updated_count = 0
        
        for bot_id in bot_ids:
            try:
                # Get current state
                cur.execute("""
                    SELECT runtime_state FROM user_bots 
                    WHERE bot_id = %s AND user_id = %s
                """, (bot_id, user_id))
                
                row = cur.fetchone()
                if not row:
                    continue
                
                runtime_state = row[0] or '{}'
                try:
                    state = json.loads(runtime_state) if isinstance(runtime_state, str) else runtime_state
                except:
                    state = {}
                
                # Apply profile
                state['riskProfile'] = profile_name
                state['leverage'] = profile_config['leverage']
                state['maxDailyLoss'] = profile_config['maxDailyLoss']
                state['maxOpenTrades'] = profile_config['maxOpenTrades']
                state['positionSizeMultiplier'] = profile_config['positionSizeMultiplier']
                state['enableAcceleration'] = profile_config['enableAcceleration']
                state['antiMartingaleMode'] = profile_config['antiMartingaleMode']
                state['signalThreshold'] = profile_config['signalThreshold']
                state['lastProfileUpdate'] = datetime.utcnow().isoformat()
                
                # Update database
                state_json = json.dumps(state)
                cur.execute("""
                    UPDATE user_bots 
                    SET runtime_state = %s
                    WHERE bot_id = %s
                """, (state_json, bot_id))
                
                updated_count += 1
                
            except Exception as e:
                logger.warning(f'[apply_profile_bulk] Failed to update {bot_id}: {e}')
                continue
        
        conn.commit()
        
        return jsonify({
            'success': True,
            'profile': profile_name,
            'updatedCount': updated_count,
            'message': f'Applied "{profile_name}" profile to {updated_count} bots'
        }), 200
        
    except Exception as e:
        logger.error(f'[apply_profile_bulk] error: {e}')
        if conn:
            try:
                conn.rollback()
            except:
                pass
        return jsonify({'success': False, 'error': str(e)}), 500
    finally:
        if conn:
            try:
                conn.close()
            except:
                pass


def _serve_http():
    """Bind and serve the HTTP/HTTPS API. Runs in a background thread so that
    port 9000 opens within seconds of startup — bot/MT5/worker initialization can
    never delay API availability (which previously caused 'Backend not responding
    on port 9000 after 60 seconds' and client-side 'future not completed')."""
    try:
        # SSL/TLS Configuration
        ssl_context = None
        ssl_cert = os.environ.get('SSL_CERT_PATH', '')
        ssl_key = os.environ.get('SSL_KEY_PATH', '')

        if ssl_cert and ssl_key and os.path.isfile(ssl_cert) and os.path.isfile(ssl_key):
            import ssl
            ssl_context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
            ssl_context.load_cert_chain(ssl_cert, ssl_key)
            logger.info(f"🔒 SSL enabled with cert: {ssl_cert}")
        else:
            default_cert = os.path.join(os.path.dirname(__file__), 'cert.pem')
            default_key = os.path.join(os.path.dirname(__file__), 'key.pem')
            if os.path.isfile(default_cert) and os.path.isfile(default_key):
                import ssl
                ssl_context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
                ssl_context.load_cert_chain(default_cert, default_key)
                logger.info(f"🔒 SSL enabled with default certs: {default_cert}")
            else:
                logger.warning("⚠️ No SSL certificates found. Running HTTP (insecure). "
                             "Set SSL_CERT_PATH and SSL_KEY_PATH env vars, or place cert.pem/key.pem next to this script.")

        bind_host = resolve_bind_host()
        ports = resolve_bind_ports()
        use_waitress = (ssl_context is None) and (os.environ.get('USE_FLASK_DEV', '').lower() not in ('1', 'true', 'yes'))
        try:
            from waitress import serve as _waitress_serve
        except Exception as _werr:
            _waitress_serve = None
            if use_waitress:
                logger.warning(f"waitress not installed ({_werr}); falling back to Flask dev server. pip install waitress")
                use_waitress = False
        waitress_threads = int(os.environ.get('WAITRESS_THREADS', '16'))
        started = False
        for port in ports:
            try:
                protocol = "https" if ssl_context else "http"
                logger.info(f"Attempting to start on {protocol}://{bind_host}:{port}")
                if use_waitress and _waitress_serve is not None:
                    logger.info(f"🚀 Production WSGI: waitress (threads={waitress_threads})")
                    _waitress_serve(app, host=bind_host, port=port, threads=waitress_threads, ident='zwesta-trader')
                else:
                    app.run(host=bind_host, port=port, debug=False, use_reloader=False, threaded=True,
                            ssl_context=ssl_context)
                started = True
                break
            except OSError as e:
                logger.warning(f"Cannot bind to port {port}: {e}")
                continue

        if not started:
            logger.error("Failed to start server on any port")
    except Exception as e:
        logger.error(f"Fatal error in HTTP server thread: {e}")


# ==================== MT5 POSITION SYNC CACHE ====================

def _sync_mt5_position_cache():
    """Background thread that periodically fetches live MT5 positions and caches them.

    This allows /api/trades/open and /api/bot/summary to return live positions
    without blocking on the MT5 connection lock during API requests.
    """
    import time as _time
    cache_ttl = 15  # seconds
    while True:
        try:
            _sync_mt5_positions_for_active_bots()
        except Exception as e:
            logger.debug(f"MT5 position cache sync error: {e}")
        _time.sleep(cache_ttl)


def _sync_mt5_positions_for_active_bots():
    """Fetch open positions from MT5 for each active bot's credentials and cache them."""
    from datetime import datetime
    now = datetime.now()
    synced_count = 0

    for bot_id, bot in list(active_bots.items()):
        try:
            user_id = bot.get('user_id') or bot.get('userId') or ''
            # If bot has no user_id, use bot_id as the cache key fallback
            if not user_id:
                user_id = f"__bot__:{bot_id}"

            broker_name = canonicalize_broker_name(
                bot.get('brokerName') or bot.get('broker_type') or bot.get('broker') or ''
            )
            if broker_name not in ('Exness', 'MetaTrader5', 'XM', 'Octa'):
                continue

            account_number = str(
                bot.get('accountNumber') or bot.get('account_number') or ''
            ).strip()
            if not account_number:
                continue

            cache_key = f"{broker_name}:{account_number}"

            # Look up the actual credential_id from the database, since
            # get_broker_connection expects a UUID credential_id, not "Broker:account".
            credential_id = None
            try:
                conn = build_sqlite_connection(wal=False)
                cursor = conn.cursor()
                cursor.execute(
                    'SELECT credential_id FROM bot_credentials WHERE bot_id = ?',
                    (str(bot_id),)
                )
                row = cursor.fetchone()
                if row:
                    credential_id = row[0]
                conn.close()
            except Exception as db_exc:
                logger.warning(f"MT5 cache sync: credential lookup failed for bot {bot_id}: {db_exc}")

            if not credential_id:
                # Fall back to bot_config's credentialId or the cache_key format
                credential_id = bot.get('credentialId') or bot.get('credential_id') or cache_key

            conn_label, broker_conn = get_broker_connection(
                credential_id, user_id, bot_id=f'cache-sync:{bot_id}'
            )
            if not broker_conn:
                continue

            try:
                positions = broker_conn.get_positions() or []
                with _live_mt5_position_cache_lock:
                    if user_id not in _live_mt5_position_cache:
                        _live_mt5_position_cache[user_id] = {}
                    _live_mt5_position_cache[user_id][cache_key] = positions
                    _live_mt5_position_cache_time[user_id] = now
                synced_count += len(positions)
            except Exception as e:
                logger.debug(f"MT5 position sync: get_positions failed for {bot_id}: {e}")
        except Exception as e:
            logger.debug(f"MT5 position sync: bot {bot_id} failed: {e}")

    if synced_count > 0:
        logger.debug(f"MT5 position cache synced: {synced_count} positions across active bots")


def get_cached_mt5_positions(user_id: str) -> List[Dict[str, Any]]:
    """Return cached MT5 positions for a user (fast, no MT5 lock needed)."""
    with _live_mt5_position_cache_lock:
        cache = _live_mt5_position_cache.get(user_id, {})
        positions = []
        for acct_key, pos_list in cache.items():
            if isinstance(pos_list, list):
                for pos in pos_list:
                    if isinstance(pos, dict):
                        enriched = dict(pos)
                        enriched['cached'] = True
                        enriched['accountKey'] = acct_key
                        positions.append(enriched)
        # If no positions found for this user_id, also check fallback cache keys
        # (bots started without an explicit user_id are cached under "__bot__:{bot_id}")
        if not positions:
            for cache_key, acct_cache in _live_mt5_position_cache.items():
                if cache_key.startswith("__bot__:"):
                    for acct_key, pos_list in acct_cache.items():
                        if isinstance(pos_list, list):
                            for pos in pos_list:
                                if isinstance(pos, dict):
                                    enriched = dict(pos)
                                    enriched['cached'] = True
                                    enriched['accountKey'] = acct_key
                                    positions.append(enriched)
        return positions


def start_mt5_position_sync_thread():
    """Start the background MT5 position cache sync thread."""
    t = threading.Thread(target=_sync_mt5_position_cache, name='mt5-pos-cache', daemon=True)
    t.start()
    logger.info("📊 MT5 position cache sync thread started (15s refresh)")


